export const SEO_NODES: SeoNode[] = [
  // BILKJØP (44 noder) — URL: /bilkjop/[slug]
  { slug: "girkasse-havari", title: "Heve bilkjøp pga defekt girkasse", lawRef: "FKL § 32 / KL § 39", cat: "bilkjop", desc: "Girkasse-havari regnes som vesentlig mangel etter forbrukerkjøpsloven dersom feilen forelå ved kjøpet.", bodyText: "En defekt girkasse er blant de dyreste feilene som kan oppstå på en bruktbil. Utbedringskostnaden ligger typisk mellom 20 000 og 80 000 kr avhengig av biltype og om girkassen kan repareres eller må byttes. Dersom havariet skjer kort tid etter kjøpet, er utgangspunktet etter forbrukerkjøpsloven at feilen forelå ved overlevering — selger må bevise det motsatte innen de første 6 månedene.\n\nVesentlighetsvurderingen ved girkasse-havari er normalt oppfylt: feilen gjør bilen ubrukelig, og utbedringskostnaden utgjør ofte en betydelig andel av kjøpesummen. Dette gir deg rett til å kreve heving — altså å levere bilen tilbake mot full refusjon av kjøpesummen, med fradrag for den nytten du har hatt av bilen (nyttefradrag).\n\nFørste steg er å reklamere skriftlig til selger umiddelbart og få en uavhengig verkstedrapport som dokumenterer feilens art og sannsynlige opprinnelse. Ikke la selger reparere bilen før dere er enige om hvem som bærer kostnadene.", faqs: [{ q: "Kan jeg heve kjøpet hvis selger tilbyr å reparere girkassen?", a: "Selger har rett til å forsøke utbedring én gang. Dersom reparasjonen mislykkes eller tar uforholdsmessig lang tid (normalt over 4 uker), kan du kreve heving." }, { q: "Girkasse-havariet skjedde etter 8 måneder. Har jeg fortsatt krav?", a: "Ja, reklamasjonsfristen er 2 år ved privatkjøp og 5 år ved forhandlerkjøp. Etter 6 måneder må du sannsynliggjøre at feilen forelå ved kjøpet — verkstedrapport er avgjørende." }, { q: "Hva er nyttefradrag og hvor mye kan selger trekke?", a: "Nyttefradrag beregnes per kjørte kilometer, typisk 1–3,50 kr/km avhengig av bilens verdi. Selger trekker dette fra kjøpesummen ved heving." }]},
  { slug: "registerreim-brudd", title: "Krav ved registerreim-brudd på bruktbil", lawRef: "FKL § 16", cat: "bilkjop", desc: "Registerreim-brudd innen rimelig tid etter kjøp er et klart tegn på skjult mangel.", bodyText: "Registerreimen er en av bilens mest kritiske komponenter — den styrer timingen mellom motor og ventiler. Dersom den ryker, kan motoren ta enorme skader på sekunder. En ny motor koster gjerne 40 000–120 000 kr, og mange biler totalhavarerer.\n\nEn registerreim har oppgitt skifteintervall fra produsenten, typisk hvert 4.–6. år eller 60 000–120 000 km. Dersom reimen ryker lenge før dette intervallet er nådd, er det sterk indikasjon på at den var i dårlig stand ved kjøpet — enten fordi den allerede var gammel, skadet eller at servicen selger hevdet var utført ikke faktisk ble gjort.\n\nDokumenter alt: hent inn service-historikk, be om dokumentasjon på siste registerreim-skifte og få en uavhengig motortekniker til å vurdere årsaken. Dette er grunnlaget for reklamasjonen.", faqs: [{ q: "Selger hevder registerreimen ble skiftet for ett år siden. Hva gjør jeg?", a: "Krev dokumentasjon — faktura fra verksted med dato og kilometerstand. Dersom han ikke kan fremlegge dette, er påstanden uten bevisverdi." }, { q: "Motoren er ødelagt etter registerreim-brudd. Kan jeg kreve ny motor?", a: "Ja, du kan kreve utbedring som dekker hele skaden inkludert følgeskader på motoren. Dersom kostnadene er uforholdsmessige kan du kreve heving." }, { q: "Bilen ble solgt 'som den er'. Gjelder reklamasjonsretten?", a: "'Som den er'-forbehold fritar ikke selger dersom feilen er vesentlig eller selger holdt tilbake informasjon om service-historikk." }]},
  { slug: "skjult-rust-skade", title: "Heve kjøp pga skjult rust i ramme", lawRef: "KL § 19", cat: "bilkjop", desc: "Skjult rust i bærende konstruksjoner er vesentlig mangel som gir hevingsrett.", bodyText: "Rust i bærende konstruksjoner som ramme, bunnplate og bærende søyler er ikke bare en estetisk feil — det er en sikkerhetskritisk mangel som kan gjøre bilen ulovlig å kjøre. Dersom rust ble bevisst skjult med sparkel, maling eller understellsbehandling, er det svik og gir deg rett til heving.\n\nEn uavhengig rustinspeksjon på et godkjent verksted eller karosserisenter er første skritt. Be om skriftlig rapport som angir rustens omfang, plassering og sannsynlig alder. Rust som tydelig er eldre enn kjøpsdatoen er bevis for at tilstanden forelå ved salget.\n\nVed privatkjøp er terskelen for heving 'vesentlig mangel' etter kjøpsloven § 39. Gjennomgående rust i bærende deler vil normalt oppfylle dette kravet. Ved forhandlerkjøp er terskelen lavere — 'ikke uvesentlig mangel' etter forbrukerkjøpsloven.", faqs: [{ q: "Rust ble oppdaget ved EU-kontroll etter kjøpet. Er det for sent å reklamere?", a: "Nei. EU-kontroll som avdekker rust kort tid etter kjøpet er god dokumentasjon for at feilen forelå ved salget. Reklamér umiddelbart etter kontrollen." }, { q: "Selger bestrider at rusten var skjult. Hvem har bevisbyrden?", a: "Innen 6 måneder etter kjøpet har selger bevisbyrden. Etter 6 måneder må du sannsynliggjøre at rusten eksisterte ved kjøpet — rustrapport med aldersangivelse er avgjørende." }, { q: "Kan jeg kreve erstatning for utgifter til rustinspeksjon?", a: "Ja, rimelige dokumentasjonskostnader kan kreves dekket av selger dersom mangelen bekreftes." }]},
  { slug: "kilometerfusk", title: "Rettigheter ved kilometerfusk på bruktbil", lawRef: "KL § 18", cat: "bilkjop", desc: "Manipulert kilometerstand er svik og gir rett til heving og erstatning.", bodyText: "Kilometerfusk — manipulering av kilometertelleren — er et alvorlig kontraktsbrudd og kan i tillegg være straffbart. En bil med høyere reell kilometerststand enn oppgitt er vesentlig mer slitt enn kjøper forventes å legge til grunn, og verdien er tilsvarende lavere.\n\nFor å dokumentere kilometerfusk kan du hente inn service-historikk fra autoriserte verksteder, sjekke NAF-rapport eller Autovid-rapport, be om EU-kontroll historikk og sammenligne disse med oppgitt kilometerstand. Avvik i disse kildene er sterkt bevis.\n\nKilometerfusk gir deg rett til heving uavhengig av om feilen er 'vesentlig' i tradisjonell forstand — fordi det er svik etter kjøpsloven § 18. Du kan i tillegg kreve erstatning for dokumenterte tap utover kjøpesummen.", faqs: [{ q: "Hvordan beviser jeg at kilometerstanden er manipulert?", a: "Hent inn service-historikk fra verksteder, EU-kontroll-historikk og Autovid/NAF-rapport. Dersom disse viser høyere km enn oppgitt ved salg er det bevis for fusk." }, { q: "Kan jeg anmelde selger for kilometerfusk?", a: "Ja, kilometerfusk kan være straffbart bedrageri. Anmeldelse til politiet er mulig, men en sivil reklamasjonssak er ofte raskere vei til refusjon." }, { q: "Har jeg krav på erstatning utover kjøpesummen?", a: "Ja, dersom du har dokumenterte tap som følge av fusket — f.eks. ekstra vedlikeholdskostnader — kan du kreve erstatning for disse i tillegg." }]},
  { slug: "elbil-batteri-degradert", title: "Dårlig batterikapasitet (lav SOH) på brukt elbil", lawRef: "FKL § 15", cat: "bilkjop", desc: "Batteriet skal holde annonsert rekkevidde. Vesentlig avvik er reklamasjonsgrunnlag.", bodyText: "Brukte elbiler selges ofte med påstander om rekkevidde eller batterikapasitet (SOH — State of Health) som ikke stemmer med virkeligheten. Et batteri med lav SOH lader saktere, gir kortere rekkevidde og kan ha redusert levetid — alle faktorer som påvirker bilens verdi betydelig.\n\nDu kan måle batteriets SOH via OBD-diagnostikk hos et verksted eller ved hjelp av apper som LeafSpy (Nissan), BMWi Remote eller tilsvarende for din bilmodell. En SOH under 70–75% på en relativt ny eller lavmils elbil er normalt reklamasjonsgrunnlag.\n\nDersom selger annonserte en spesifikk rekkevidde eller SOH som ikke stemmer, er dette brudd på opplysningsplikten etter forbrukerkjøpsloven § 15. Du kan kreve prisavslag, utbedring (batteriskift) eller heving avhengig av avvikets størrelse.", faqs: [{ q: "Hva er akseptabel SOH på en brukt elbil?", a: "Det finnes ingen fast rettslig norm, men bransjepraksis tilsier at SOH under 70% på en bil under 5 år gammel er utenfor det kjøper kan forvente uten særskilt opplysning." }, { q: "Selger oppga ikke SOH ved salget. Har jeg krav?", a: "Ja, dersom SOH er vesentlig lavere enn det som er rimelig å forvente for bilens alder og km-stand. Selger trenger ikke ha opplyst om det eksplisitt." }, { q: "Kan jeg kreve at selger bytter batteriet?", a: "Du kan kreve utbedring. Batteriskift er ekstremt kostbart, så selger vil normalt tilby prisavslag. Dersom avviket er vesentlig kan du kreve heving." }]},
  { slug: "turbo-defekt", title: "Heve bilkjøp etter turbo-havari", lawRef: "KL § 39", cat: "bilkjop", desc: "Turbo-havari kort tid etter kjøp er presumpsjon for mangel ved overlevering.", bodyText: "Turboladeren er en kompleks og kostbar komponent som koster 15 000–50 000 kr å bytte. Et turbo-havari kort tid etter kjøpet — typisk innen de første 6 månedene — presumeres å stamme fra forhold som forelå ved overlevering.\n\nVanlige årsaker til turbo-havari som selger burde kjent til: for lite motorolje ved salg, forurenset olje som ikke ble skiftet, slitte oljekanaler eller tidligere turbo-problemer som ble skjult. En motortekniker kan ofte fastslå om havariet skyldes akutt skade eller progressiv slitasje.\n\nDersom verkstedrapport konkluderer med at turboens tilstand ikke samsvarer med bilens oppgitte service-historikk eller km-stand, har du et sterkt grunnlag for reklamasjon. Krev heving dersom utbedringskostnaden utgjør en vesentlig del av kjøpesummen.", faqs: [{ q: "Turboen havarerte etter 3 måneder. Selger sier jeg har kjørt feil. Kan han ha rett?", a: "Han må dokumentere dette. Turbo-havari etter 3 måneder presumeres å skyldes forhold ved kjøpet. Selger har bevisbyrden innen de første 6 månedene." }, { q: "Selger tilbyr å betale halvparten av turbo-reparasjonen. Bør jeg akseptere?", a: "Ikke uten videre. Dersom feilen forelå ved kjøpet skal selger dekke hele kostnaden. Aksepter ikke delbetaling uten å reservere retten til å kreve resten." }, { q: "Bilen har 200 000 km. Kan selger si turbo-slitasje er forventet?", a: "Avhenger av bilmodell og service-historikk. En godt vedlikeholdt turbo skal vare over 200 000 km. Manglende service-dokumentasjon taler mot selger." }]},
  { slug: "toppakning-defekt", title: "Defekt toppakning på bruktbil: Hev kjøpet", lawRef: "KL § 39", cat: "bilkjop", desc: "Defekt toppakning er kostbar og alvorlig mangel med klar hevingsrett.", bodyText: "Toppakningen tetter mellom motorblokk og topplokk og hindrer at kjølevæske og olje blandes. En defekt toppakning er en alvorlig mangel — uoppdaget kan den føre til motorhavari. Symptomene inkluderer hvit røyk fra eksosen, oljefilm på kjølevæsken, raskt synkende kjølevæskenivå og overoppheting.\n\nReparasjon av toppakning koster typisk 15 000–40 000 kr avhengig av motor og arbeidsomfang. Dersom motoren allerede har tatt skade er kostnaden vesentlig høyere. Dette er normalt tilstrekkelig til å oppfylle vesentlighetskravet for heving.\n\nEn toppakning som svikter kort tid etter kjøpet er nesten alltid en pre-eksisterende feil — prosessen med å brenne toppakningen tar tid og viser tydelige symptomer som en selger som kjørte bilen jevnlig burde ha oppdaget.", faqs: [{ q: "Bilen overopphetet og toppakningen sprakk. Hvem er ansvarlig?", a: "Dersom overophetingen skyldtes en eksisterende feil (f.eks. defekt termostat eller kjølevæskelekkasje) som forelå ved kjøpet er selger ansvarlig for hele skaden inkludert toppakningen." }, { q: "Selger sier jeg har kjørt bilen for hardt. Kan han ha rett?", a: "Han må dokumentere dette konkret. Generell påstand om feil kjøring uten bevis er ikke tilstrekkelig til å frita selger fra ansvar." }, { q: "Kan jeg kreve heving selv om selger ikke visste om toppakningen?", a: "Ja. Selger er ansvarlig for skjulte mangler selv uten kunnskap, forutsatt at mangelen forelå ved kjøpet og er vesentlig." }]},
  { slug: "clutch-utslitt", title: "Klage på utslitt clutch ved levering", lawRef: "KL § 17", cat: "bilkjop", desc: "Unormalt slitt clutch som ikke ble opplyst om er skjult mangel.", bodyText: "Clutchen er en slitedel med begrenset levetid, men den skal vare i samsvar med bilens alder og kilometerstand. En clutch som slipper eller begynner å slure kort tid etter kjøpet tyder på at den allerede var i dårlig stand ved overlevering.\n\nVerkstedet kan vurdere clutchens tilstand og gi en faglig mening om hvor lenge den har vært slitt. Dersom vurderingen tilsier at clutchen hadde gjenværende levetid på under 5 000–10 000 km ved kjøpet, er det reklamasjonsgrunnlag — særlig hvis selger ikke opplyste om dette.\n\nVed forhandlerkjøp er terskelen lavere enn ved privatkjøp. En forhandler forventes å kjenne bilens tilstand og opplyse om nær forestående clutch-skifte. Unnlatelse av dette er brudd på opplysningsplikten.", faqs: [{ q: "Selger sier clutch alltid er kjøpers risiko. Stemmer det?", a: "Nei, ikke dersom clutchen var unormalt slitt ved kjøpet og selger ikke opplyste om det. Slitedeler som er ved slutten av levetiden skal opplyses om." }, { q: "Clutchen begynte å slure etter 2 000 km. Er det reklamasjonsgrunnlag?", a: "Ja, clutch som slurer etter 2 000 km er klar indikasjon på at den var nær slutt ved kjøpet. Krev verkstedvurdering og reklamér skriftlig." }, { q: "Hva kan jeg kreve — utbedring eller prisavslag?", a: "Du kan velge. Utbedring (nytt clutchsett) eller prisavslag tilsvarende utbedringskostnaden. Heving er sjelden aktuelt for clutch alene." }]},
  { slug: "luftfjaring-defekt", title: "Reklamasjon på defekt luftfjæring", lawRef: "FKL § 16", cat: "bilkjop", desc: "Luftfjæring som svikter kort etter kjøp gir rett til utbedring eller prisavslag.", bodyText: "Luftfjæring er et avansert og kostbart system som erstatter tradisjonelle fjærer og støtdempere med luftputer styrt av kompressor og ventiler. Systemet gir utmerket kjørekomfort, men er dyrt å reparere — typisk 15 000–60 000 kr for kompressor, ventilblokk eller luftputebytte.\n\nLuftfjæring som svikter kort tid etter kjøpet — bilen synker ned på én eller flere akslinger, kompressoren kjører konstant eller feilmeldinger oppstår — presumeres å ha hatt latente feil ved kjøpet. Kompressorslitasje og sprekker i luftputene utvikler seg over tid og er ikke plutselige feil.\n\nDersom selger solgte bilen som 'fullt fungerende' eller ikke opplyste om kjente problemer med luftfjæringen, er dette brudd på opplysningsplikten. Krev skriftlig reklamasjon og verksteddiagnose før du lar noen reparere systemet.", faqs: [{ q: "Bilen synker ned på høyre side om natten. Er det en mangel?", a: "Ja, en luftpute som langsomt tømmer seg er defekt. Dette er ikke normal oppførsel og er reklamasjonsgrunnlag dersom det startet kort tid etter kjøpet." }, { q: "Selger sier luftfjæringsproblemer er kjent for denne bilmodellen. Endrer det noe?", a: "Tvert imot — dersom det er et kjent problem for modellen pliktet selger å opplyse om det eksplisitt. Kjent feil som ikke opplyses om er brudd på informasjonsplikten." }, { q: "Kan jeg konvertere til vanlig fjæring og kreve kostnadene dekket?", a: "Ja, dersom konvertering er rimeligere enn reparasjon av luftfjæringen og selger samtykker eller ikke svarer på reklamasjonen innen rimelig tid." }]},
  { slug: "oljeforbruk-hoyt", title: "Reklamasjon på unormalt høyt oljeforbruk", lawRef: "FKL § 16", cat: "bilkjop", desc: "Unormalt høyt oljeforbruk tyder på skjult motorskade og er reklamasjonsgrunnlag.", bodyText: "Alle motorer bruker litt olje, men produsenten setter en maksgrense — typisk 0,5 liter per 1 000 km for bensinmotorer. Overskrider bilen dette vesentlig, tyder det på slitte stempelringer, ventiltetninger eller andre indre motorskader som var til stede ved kjøpet.\n\nFor å dokumentere oljeforbruket: noter oljenivå og kilometerstand ved kjøpet, og mål deretter ved regelmessige intervaller. Et forbruk på over 1 liter per 1 000 km er klart over normalen for de fleste biler. Verksted kan også gjennomføre kompresjonstest og lekkasjetest for å identifisere årsaken.\n\nHøyt oljeforbruk er en progressiv tilstand som utvikler seg over tid — bilen har ikke plutselig begynt å bruke mye olje. Dette styrker argumentet for at feilen forelå ved kjøpet.", faqs: [{ q: "Selger sier høyt oljeforbruk er normalt for denne motortypen. Kan han ha rett?", a: "Sjekk produsentens spesifikasjoner. Dersom forbruket overstiger produsentens maksgrense, er det per definisjon unormalt og selgers påstand holder ikke." }, { q: "Jeg har kjørt 5 000 km siden kjøpet og brukt 4 liter olje. Er det nok til å reklamere?", a: "Ja, 0,8 liter per 1 000 km er over normalen for de fleste motorer. Dokumenter dette skriftlig og reklamér til selger med påstand om skjult motorskade." }, { q: "Hva kan jeg kreve ved unormalt høyt oljeforbruk?", a: "Utbedring (motoroverhaling eller bytte), prisavslag, eller heving dersom kostnaden er vesentlig. Krev verkstedrapport som grunnlag." }]},
  { slug: "ac-anlegg-defekt", title: "Defekt AC-anlegg oppdaget etter kjøp", lawRef: "FKL § 16", cat: "bilkjop", desc: "AC som ikke fungerer og ikke ble opplyst om er mangel ved kjøpet.", bodyText: "AC-anlegget er en av bilens mest komplekse komponenter, og reparasjon kan koste alt fra 5 000 til 30 000 kr avhengig av om det er kompressoren, kondensatoren eller styringselektronikken som er defekt. Dersom AC-en ikke fungerer ved levering og dette ikke ble opplyst om, er det en mangel etter forbrukerkjøpsloven § 16. I Forbrukerklageutvalgets sak 2022-451 ble det fastslått at defekt AC-anlegg utgjør en kjøpsrettslig mangel selv om bilen var solgt «som den er» — selgers forbehold fritar ikke for feil som ikke ble opplyst om.\n\nDersom bilannonseen oppga klimaanlegg, forutsettes det at dette fungerer. Selger kan ikke fraskrive seg ansvar ved å hevde at AC er et komfort-tilbehør — det er en del av bilens spesifikasjoner som kjøper har betalt for. Høyesterett slo i Rt. 2007 s. 1274 (Støvletthæl-dommen) fast at 2 måneder alltid er innenfor «rimelig tid» for reklamasjon.\n\nDokumenter feilen hos et autorisert verksted som kan bekrefte at AC-problemet skyldes en eksisterende feil, ikke manglende påfyll av kjølegass. Skriftlig reklamasjon til selger med vedlagt verkstedrapport er første steg mot utbedring eller prisavslag.", faqs: [{ q: "Er defekt AC en mangel selv om bilen er solgt «som den er»?", a: "Ja. Forbrukerklageutvalget fastslo i sak 2022-451 at defekt AC er en mangel selv med «som den er»-forbehold, fordi selger ikke opplyste om feilen ved salget." }, { q: "Selger sier AC bare trenger påfyll av kjølegass. Er det mitt ansvar?", a: "Påfyll av kjølegass er vedlikehold, men dersom det er lekkasje i systemet som forårsaker tapet, er dette en mangel selger er ansvarlig for. Krev verkstedrapport som avklarer årsaken." }, { q: "Kan jeg kreve heving pga. defekt AC?", a: "Alene er det sjelden nok for heving, men sammen med andre mangler kan det styrke en hevingssak. Prisavslag tilsvarende utbedringskostnaden er mest realistisk — typisk 5 000–30 000 kr." }] },
  { slug: "elektrisk-feil-bil", title: "Elektriske feil og kortslutning på bruktbil", lawRef: "FKL § 16", cat: "bilkjop", desc: "Elektriske feil som ikke ble opplyst om er skjult mangel.", bodyText: "Elektriske feil i moderne biler kan være alt fra irriterende (ikke-fungerende vindusheiser, feil på instrumentpanel) til alvorlige (kortslutning, brannfare). Komplekse elektriske feil er dyre å utbedre fordi feilsøking er tidkrevende — timepriser på 1 200–1 800 kr gjør at selv enkle feil kan koste 5 000–20 000 kr å diagnostisere og fikse.\n\nElektriske problemer utvikler seg sjelden over natten. En bil med ustabilt elektrisk anlegg vil normalt ha vist symptomer som selger burde ha merket — sporadiske feil, blinkende lys, ikke-fungerende komponenter. Unnlatelse av å opplyse om dette er brudd på informasjonsplikten.\n\nDokumenter alle elektriske feil du oppdager og be verksted om skriftlig diagnose. Be spesifikt om vurdering av feilens alder og sannsynlige årsak.", faqs: [{ q: "Sentrallåsen virker av og til. Er det reklamasjonsgrunnlag?", a: "Ja, intermitterende feil på sentrallås som starter rett etter kjøpet er reklamasjonsgrunnlag. Dokumenter med beskrivelse av symptomer og tidspunkt." }, { q: "Selger sier han ikke visste om de elektriske problemene. Fritar det ham?", a: "Nei. Elektriske problemer som er synlige og merkbare er vanskelig å ikke ha kjent til. Selger er uansett ansvarlig for feil som forelå ved kjøpet." }, { q: "Verkstedregningen for feilsøking er høyere enn reparasjonen. Kan jeg kreve begge deler?", a: "Ja, rimelige diagnostikkostnader er en del av utbedringskostnaden og kan kreves dekket av selger." }]},
  { slug: "eu-kontroll-mangel", title: "Bilen besto ikke EU-kontroll etter kjøp", lawRef: "KL § 19", cat: "bilkjop", desc: "Feil som avdekkes ved EU-kontroll kort etter kjøp presumeres å ha eksistert ved salg.", bodyText: "Dersom bilen ikke bestod EU-kontroll kort tid etter kjøpet, er feilene som avdekkes sterke bevis for at bilen var i dårligere stand enn det selger forespeilet. EU-kontrollen er en standardisert gjennomgang av sikkerhetskritiske komponenter, og alvorlige avvik tyder klart på at mangelen forelå ved overlevering. I Forbrukerklageutvalgets sak 2022-190 ble det fastslått at defekte bremser oppdaget rett etter EU-kontroll utgjorde mangel som trumfet selgers «som den er»-forbehold.\n\nEtter kjøpsloven § 19 har bilen en mangel dersom den ikke svarer til det kjøper hadde grunn til å forvente. En bil som ikke kan bestå EU-kontroll oppfyller ikke de grunnleggende kravene til lovlig ferdsel på vei. Kostnadene ved utbedring kan variere enormt — fra noen tusen for bremser til titusener for rust i bærende konstruksjoner.\n\nReklamér skriftlig til selger med kopi av EU-kontroll-rapporten. Høyesterett fastslo i Rt. 2007 s. 1274 (Støvletthæl-dommen) at reklamasjon innen 2 måneder alltid er rettidig. Be om utbedring for selgers regning, eller prisavslag tilsvarende utbedringskostnaden. Ved alvorlige og kostbare feil kan heving av kjøpet være aktuelt.", faqs: [{ q: "Bilen fikk flere EU-kontroll-avvik etter kjøpet. Er alt selgers ansvar?", a: "Feil som forelå ved kjøpet er selgers ansvar. I sak 2022-190 ble selger holdt ansvarlig for bremsedefekter oppdaget rett etter EU-kontroll, selv med «som den er»-forbehold. Slitasje som oppstår etter kjøpet er ditt ansvar." }, { q: "Selger sier EU-kontroll ikke er hans problem. Har han rett?", a: "Nei. Dersom bilen ble solgt som kjørbar og lovlig, og EU-kontrollen avdekker alvorlige feil, er dette mangel. Selger er ansvarlig uavhengig av hva han hevder muntlig." }, { q: "Kan jeg kreve at selger betaler for ny EU-kontroll etter utbedring?", a: "Ja, alle rimelige kostnader knyttet til mangelen kan kreves dekket, inkludert ny kontroll og eventuelle fraktkostnader." }] },
  { slug: "lakkfeil-skjult", title: "Skjult lakkfeil eller skadet lakk etter kjøp", lawRef: "KL § 19", cat: "bilkjop", desc: "Sparkel og lakkreparasjoner som ikke ble opplyst om er skjult mangel.", bodyText: "Skjult lakkskade eller sparkelarbeid er blant de vanligste tvistene ved bruktbilkjøp. Selger har opplyst at bilen er skadefri, men ved nærmere inspeksjon avdekkes sparkel, underlakk-misfarging eller avvikende lakk-tykkelse som tyder på tidligere kollisjonsskade. I Forbrukerklageutvalgets sak 2022-1784 ble skjult rust i rammen ansett som vesentlig mangel og ga kjøper 45 000 kr i prisavslag — samme prinsipp gjelder for skjulte lakkfeil som maskerer underliggende skade.\n\nEtter kjøpsloven § 19 foreligger mangel dersom selger har gitt uriktige opplysninger eller holdt tilbake informasjon som kjøper hadde grunn til å forvente. Omfattende lakkreparasjon indikerer typisk underliggende skade som kan påvirke bilens verdi, sikkerhet og fremtidig rustbeskyttelse. I sak 2020-144 ga manglende opplysning om bilens historikk prisavslag — samme prinsipp gjelder for skjulte kollisjonsskader.\n\nEn profesjonell lakktykkelsemåling koster kun noen hundrelapper og gir objektiv dokumentasjon. Resultatet viser nøyaktig hvor det er sparklet og lakkert. Dersom skaden er kosmetisk er prisavslag mest aktuelt; ved strukturelle skader kan heving kreves.", faqs: [{ q: "Lakktykkelsemåling viser avvik. Er det nok bevis?", a: "Ja, lakktykkelsemåling er anerkjent som pålitelig dokumentasjon. Avvik over 200–300 mikron tyder klart på sparkel og omlakkering. I sak 2022-1784 ble tilsvarende dokumentasjon av skjulte skader lagt til grunn for prisavslag." }, { q: "Er kosmetisk lakkskade nok til å heve kjøpet?", a: "Sjelden. Ren kosmetisk skade gir typisk prisavslag. Men dersom den skjulte lakkeringen maskerer strukturelle skader i karosseriet, kan heving være aktuelt — som i saker der skjult skade vesentlig reduserer bilens verdi." }, { q: "Selger kjente ikke til den tidligere skaden. Har jeg likevel krav?", a: "Ja. Selger er objektivt ansvarlig for bilens tilstand. Manglende kunnskap fritar ikke for ansvar når mangelen er dokumentert. Opplysningsplikten etter kjøpsloven § 19 gjelder uansett." }] },
  { slug: "4wd-feil", title: "Feil på 4WD/4x4-system oppdaget etter kjøp", lawRef: "FKL § 16", cat: "bilkjop", desc: "4WD-system som ikke fungerer korrekt og ikke ble opplyst om er reklamasjonsgrunnlag.", bodyText: "Firehjulsdrift (4WD/AWD) er ofte en avgjørende faktor i kjøpsbeslutningen, og en bil solgt med 4WD-system forutsettes å ha et fungerende system. Feil på 4WD kan inkludere defekte koplinger, elektroniske styringsproblemer, slitte kardangkryss eller ødelagte differensialer — alt kostbare reparasjoner som typisk ligger mellom 10 000 og 50 000 kr. I Forbrukerklageutvalgets sak 2022-998 ble defekt 4WD/Haldex-system regnet som skjult mangel som ga kjøper rett til utbedring.\n\nEtter forbrukerkjøpsloven § 16 har bilen en mangel dersom den ikke samsvarer med det kjøper hadde grunn til å forvente. Dersom 4WD-systemet var en del av bilens spesifikasjoner i annonsen, foreligger det en mangel uavhengig av om selger kjente til feilen. Ved forhandlerkjøp presumeres feilen å ha eksistert ved kjøpet dersom den viser seg innen 6 måneder.\n\nFå en verkstedrapport som bekrefter feilens art, estimert utbedringskostnad og sannsynlig årsak. Reklamér skriftlig innen rimelig tid — Høyesterett fastslo i Rt. 2007 s. 1274 (Støvletthæl-dommen) at 2 måneder alltid er innenfor fristen.", faqs: [{ q: "4WD-lampen lyser etter kjøpet. Er det en mangel?", a: "Ja. I sak 2022-998 fastslo Forbrukerklageutvalget at defekt 4WD/Haldex-system er en skjult mangel selger svarer for, uavhengig av om han kjente til feilen." }, { q: "Bilen trekker til en side i 4WD-modus. Er det reklamasjonsgrunnlag?", a: "Ja, dette tyder på defekt kobling eller differensial. Dokumenter symptomet og reklamér med verkstedrapport. Tilsvarende feil ga utbedringsansvar i sak 2022-998." }, { q: "Selger sier 4WD er ekstrautstyr han ikke garanterer. Har han rett?", a: "Nei. Utstyr som fremgår av bilens spesifikasjoner eller annonse er inkludert i kjøpet og skal fungere. FKL § 16 krever at bilen samsvarer med det som er avtalt." }] },
  { slug: "automatgir-feil", title: "Feil på automatgirkasse etter bilkjøp", lawRef: "FKL § 32", cat: "bilkjop", desc: "Automatgirkasse som rykker eller slirer er alvorlig mangel med høy utbedringskostnad.", bodyText: "Automatgirkasser er komplekse og kostbare komponenter. En ny eller revidert automatgirkasse koster typisk 25 000–80 000 kr inkludert montering. Feil som rykking ved girskift, sluring, forsinkede gir eller feilkoder relatert til transmisjon er tegn på at girkassen er i dårlig stand.\n\nLikesom manuell girkasse presumeres automatgirkassefeil innen 6 måneder å ha eksistert ved overlevering. Feil som rykking og sliring utvikler seg gradvis og er ikke plutselige — en selger som kjørte bilen jevnlig burde ha merket symptomene.\n\nFå verksteddiagnose med utskrift av feilkoder og beskrivelse av symptomer. Spør spesifikt om feilkodehistorikk — nullstilte feilkoder som dukker opp igjen er bevis på at problemet var kjent ved salget.", faqs: [{ q: "Girkassen rykker bare av og til. Er det tilstrekkelig grunn til å reklamere?", a: "Ja, intermitterende feil er ofte vanskeligere å dokumentere men like gyldige som reklamasjonsgrunnlag. Film symptomene og be verksted reprodusere feilen." }, { q: "Selger tilbyr å skifte girolje. Er det tilstrekkelig utbedring?", a: "Dersom oljeskifte løser problemet permanent er det akseptabelt. Dersom problemet vedvarer har selger brukt opp sin ene utbedringssjanse og du kan kreve heving." }, { q: "Kan jeg bruke en hvilken som helst verksted til diagnosen?", a: "Ja, men bruk gjerne et autorisert verksted for din bilmodell. Deres diagnose har mer tyngde overfor selger og eventuell nemnd." }]},
  { slug: "bremsesystem-feil", title: "Defekt bremsesystem oppdaget etter kjøp", lawRef: "FKL § 16", cat: "bilkjop", desc: "Bremsesvikt er sikkerhetskritisk mangel med sterk hevingsrett.", bodyText: "Bremsesvikt er den mest sikkerhetskritiske mangelen en bil kan ha. Defekte bremser setter fører, passasjerer og andre trafikanter i direkte fare, og er en mangel som normalt oppfyller vesentlighetskravet for heving. I Forbrukerklageutvalgets sak 2022-190 ble det fastslått at defekte bremser oppdaget rett etter EU-kontroll trumfet selgers «som den er»-forbehold — sikkerhetskritiske feil aksepteres ikke.\n\nEtter forbrukerkjøpsloven § 16 har bilen en mangel dersom den ikke er i samsvar med det kjøper hadde grunn til å forvente. En bil med defekte bremser er ikke trafikksikker og oppfyller ikke minstekravene til lovlig ferdsel. Utbedringskostnader for bremser varierer fra 3 000 kr for klosser og skiver til 20 000+ kr for hydraulikk- og ABS-reparasjoner.\n\nReklamér umiddelbart — ikke kjør bilen videre med defekte bremser. Dokumenter feilen med verkstedrapport og bilder. Høyesterett fastslo i Rt. 2007 s. 1274 at 2 måneder alltid er innenfor reklamasjonsfristen. Krev utbedring for selgers regning, og hold tilbake et beløp tilsvarende utbedringskostnaden fra eventuelt gjenstående betaling.", faqs: [{ q: "Bremsene var dårlige ved levering. Kan selger si det er slitedeler?", a: "Bremser er slitedeler, men de skal være i forsvarlig stand ved levering. I sak 2022-190 fastslo Forbrukerklageutvalget at bremser under minstekrav ved EU-kontroll er en mangel — selv med «som den er»-forbehold." }, { q: "ABS-lampen lyser. Er det en mangel?", a: "Ja, lysende ABS-lampe indikerer feil i sikkerhetssystemet. Selger plikter å utbedre dette dersom feilen forelå ved kjøpet. Slike sikkerhetsfeil veier tungt i vesentlighetsvurderingen." }, { q: "Kan jeg kreve heving pga. bremsesvikt?", a: "Ja, bremsesvikt er sikkerhetskritisk og oppfyller normalt vesentlighetskravet for heving, særlig dersom selger ikke utbedrer innen rimelig tid. Sak 2022-190 bekrefter at slike feil ikke kan forbeholdes bort." }] },
  { slug: "motor-oljetrykk", title: "Lavt oljetrykk og motorskade etter kjøp", lawRef: "KL § 39", cat: "bilkjop", desc: "Motorskade kort tid etter kjøp presumeres å stamme fra forhold ved overlevering.", bodyText: "Lavt oljetrykk og motorskade kort tid etter kjøpet er en alvorlig situasjon som kan koste titusener å utbedre. Årsaken kan være slitte motorlagre, defekt oljepumpe, tilstoppet oljefilter eller langvarig oljemangel som har forårsaket permanent skade på motorens indre deler. I Forbrukerklageutvalgets sak 2023-112 ble lavt oljetrykk og motorhavari ved overtakelse ansett som vesentlig mangel som ga kjøper rett til heving av kjøpet.\n\nEtter kjøpsloven § 39 presumeres feil som viser seg kort tid etter kjøpet å stamme fra forhold som forelå ved overlevering. Selger må bevise at motorskaden oppsto etter kjøpet. Dersom motoren hadde latente skader ved salget, er dette selgers ansvar. I sak 2022-1104 ble ekstremt oljeforbruk på en Audi TFSI fastslått som mangel — et prinsipp som også gjelder andre oljeproblemer.\n\nFå en uavhengig motorkyndig til å vurdere årsaken skriftlig. En kompresjonsmåling og oljeanalyse kan avsløre om motoren hadde eksisterende slitasje. Kostnadene ved motorbytte (40 000–120 000 kr) gjør at heving ofte er mest aktuelt.", faqs: [{ q: "Oljelampen lyste etter 1 uke. Selger sier jeg ikke sjekket oljen. Har han rett?", a: "Selger må bevise dette. I sak 2023-112 ga lavt oljetrykk ved overtakelse rett til heving. Dersom motoren hadde slitasje som forårsaket lavt oljetrykk allerede ved kjøpet, er det selgers ansvar." }, { q: "Motoren er totalhavarert. Kan jeg kreve ny motor eller heving?", a: "Begge deler er mulig. Sak 2023-112 ga heving ved motorhavari. Du kan kreve utbedring (ny/brukt motor) eller heving dersom kostnadene er vesentlige i forhold til kjøpesummen." }, { q: "Bilen har ekstremt oljeforbruk. Er det en mangel?", a: "Ja. I sak 2022-1104 ble ekstremt oljeforbruk på en Audi TFSI fastslått som mangel. Unormalt oljeforbruk indikerer slitasje som sannsynligvis forelå ved kjøpet." }] },
  { slug: "karosseri-skade-skjult", title: "Skjult karosseri- eller kollisjonsskade", lawRef: "KL § 19", cat: "bilkjop", desc: "Uopplyst kollisjonsskade i karosseri er vesentlig mangel og hevingsgrunnlag.", bodyText: "En skjult kollisjonsskade i karosseriet er en alvorlig mangel som påvirker bilens sikkerhet, verdi og holdbarhet. Moderne biler er konstruert med deformasjonssoner som absorberer energi ved kollisjon — dersom disse er skadet og reparert uten at det er opplyst om, kan bilen være farlig ved en ny ulykke. I Forbrukerklageutvalgets sak 2022-1784 ble skjult rust i rammen ansett som vesentlig mangel og ga kjøper 45 000 kr i prisavslag.\n\nEtter kjøpsloven § 19 foreligger mangel dersom selger har holdt tilbake opplysninger som kjøper hadde grunn til å regne med å få. Uopplyst kollisjonsskade er et klassisk brudd på opplysningsplikten. I sak 2020-144 ble mangelfull historikk på bruktimportert bil ansett som prisavslagsgrunn — prinsippet gjelder tilsvarende for skjulte karosseriskader.\n\nDokumentasjon er avgjørende. En karosserikontroll med lakktykkelsemåling og chassismåling avslører om bilen har vært i kollisjon. Dersom skaden er alvorlig og vesentlig påvirker bilens verdi, er heving aktuelt — ellers prisavslag tilsvarende verditapet.", faqs: [{ q: "Lakktykkelsemåling viser sparkel på flere paneler. Er det nok bevis?", a: "Ja, sparkel på flere paneler tyder klart på uopplyst kollisjonsskade. I sak 2022-1784 ble tilsvarende dokumentasjon lagt til grunn for prisavslag på 45 000 kr." }, { q: "Bilen ble solgt som 'skadefri'. Hva betyr det juridisk?", a: "Dersom selger aktivt har oppgitt at bilen er skadefri og det viser seg å være uriktig, foreligger brudd på opplysningsplikten etter KL § 19 — potensielt svik som styrker hevingskravet." }, { q: "Kan jeg sjekke bilens skadehistorikk selv?", a: "Ja, tjenester som AutoSys gir tilgang til registrerte forsikringsskader. En lakktykkelsemåling er den beste fysiske kontrollen. I sak 2020-144 ble manglende historikk-opplysning ansett som mangel." }] },
  { slug: "hybrid-batteri-feil", title: "Defekt hybridbatteri på brukt hybridbil", lawRef: "FKL § 15", cat: "bilkjop", desc: "Hybridbatteri som ikke holder forventet kapasitet er reklamasjonsgrunnlag.", bodyText: "Hybridbatteriet er bilens dyreste enkeltkomponent — et nytt batteri koster typisk 30 000–80 000 kr avhengig av bilmodell. Batteriet skal holde tilstrekkelig kapasitet til at hybridsystemet fungerer som forutsatt. Dersom elbil-rekkevidden eller regenereringen er vesentlig dårligere enn forventet for bilens alder og km-stand, er dette reklamasjonsgrunnlag.\n\nHybridbatterier degraderes over tid, men en bil som selges som fungerende hybrid skal levere akseptabel hybridytelse. Be verksted lese ut batteriets SOH (State of Health) og cellebalanse via OBD-diagnostikk. Avvik mellom celler og lav total SOH dokumenterer problemet.\n\nDersom selger markedsførte bilen med hybridøkonomi og batteriet ikke understøtter dette, er det brudd på markedsføringsplikten etter forbrukerkjøpsloven § 15. Du kan kreve prisavslag tilsvarende kostnaden for batteriskift eller heving dersom avviket er vesentlig.", faqs: [{ q: "Hybridindikatoren lyser alltid rødt. Er det en mangel?", a: "Ja, vedvarende feil i hybridsystemet kort tid etter kjøpet presumeres å ha eksistert ved overlevering. Krev verksteddiagnose og reklamér skriftlig." }, { q: "Selger sier hybridbatterier alltid er slitt på eldre biler. Holder det?", a: "Nei som generell ansvarsfraskrivelse. Dersom SOH er vesentlig lavere enn forventet for bilens alder og km-stand er det reklamasjonsgrunnlag uavhengig av alder." }, { q: "Kan jeg kreve at selger betaler for helt nytt batteri?", a: "Du kan kreve utbedring. Selger kan velge å reparere, bytte batteri eller tilby prisavslag. Dersom ingen av løsningene er akseptable kan du kreve heving." }]},

  // BILKJØP (20 nye noder med FAQs)
  { slug: "infotainment-skjerm-svart", title: "Feil på infotainment eller skjerm etter bilkjøp", lawRef: "FKL § 16", cat: "bilkjop", desc: "Skjerm som går i svart eller fryser kan regnes som mangel etter forbrukerkjøpsloven dersom feilen forelå ved kjøpet.", bodyText: "Infotainment-skjermen er blitt en sentral del av moderne bilers funksjonalitet — den styrer navigasjon, klimaanlegg, ryggekamera og ofte viktige kjørefunksjoner. En skjerm som går i svart, fryser eller har døde piksler kan koste 10 000–40 000 kr å reparere, avhengig av bilmerke og modell. I Forbrukerklageutvalgets sak 2023-344 ble defekt infotainment/hovedskjerm ansett som mangel som ga kjøper rett til gratis utbedring.\n\nEtter forbrukerkjøpsloven § 16 skal bilen samsvare med det kjøper hadde grunn til å forvente. Dersom bilen ble solgt med fungerende infotainment-system, skal dette virke. Innen 6 måneder etter kjøpet presumeres feilen å ha eksistert ved overlevering — selger må bevise det motsatte.\n\nDokumenter feilen med video og skjermbilder. Be verkstedet lese ut feilkoder relatert til infotainment-enheten. Dersom feilkoder ble slettet før salget, er dette sterkt bevis for at selger kjente til problemet. Reklamér skriftlig med vedlagt dokumentasjon.", faqs: [{ q: "Gjelder reklamasjonsretten selv om skjermen virket da jeg kjøpte bilen?", a: "Ja. Dersom feilen viser seg innen 6 måneder etter overtakelse, presumeres den å ha eksistert ved kjøpet. I sak 2023-344 fikk kjøper medhold i krav om utbedring av defekt hovedskjerm." }, { q: "Kan jeg kreve at selger bytter hele infotainment-enheten?", a: "Du kan kreve utbedring. Selger velger om det gjøres ved reparasjon eller bytte, men utbedringen må skje innen rimelig tid og uten vesentlig ulempe for deg." }, { q: "Skjermen fryser bare av og til. Er det nok til å reklamere?", a: "Ja, intermitterende feil er like gyldige som reklamasjonsgrunnlag. Dokumenter med video hver gang feilen oppstår — dette ble lagt til grunn i sak 2023-344." }]},
  { slug: "partikkelfilter-dpf-feil", title: "Tett partikkelfilter (DPF) på bruktbil", lawRef: "KL § 19", cat: "bilkjop", desc: "Tett DPF kort tid etter kjøp er en klassisk tvist. Selger hevder det er driftsfeil, kjøper mener det var skjult mangel.", bodyText: "Tett eller defekt partikkelfilter (DPF) er en av de vanligste tvistene ved kjøp av brukt dieselbil. Et nytt DPF koster gjerne 15 000–40 000 kr, og selger hevder ofte at problemet skyldes kjøpers kjørestil. Realiteten er at et DPF som tettes kort tid etter kjøpet sannsynligvis allerede var i dårlig stand. Prinsippet fra Rt. 1998 s. 774 (Videospillerdommen) om at produkter ment å vare lenge har 5 års reklamasjonsrett, gjelder tilsvarende for bilkomponenter.\n\nEtter kjøpsloven § 19 foreligger mangel dersom bilen ikke svarer til det kjøper hadde grunn til å forvente. Et fungerende avgassystem er en grunnleggende forutsetning for lovlig ferdsel. Innen 6 måneder etter kjøpet har kjøper en presumpsjon på sin side — selger må bevise at DPF-problemet skyldes forhold etter overlevering.\n\nFå en OBD-utlesning fra verksted som viser DPF-sot-nivå og feilkodehistorikk. Dersom feilkoder ble slettet like før salget, er dette sterkt bevis for at selger kjente til problemet og bevisst skjulte det. I sak 2022-1104 ble relaterte avgass- og motorproblemer ansett som mangel.", faqs: [{ q: "Hvem har bevisbyrden for om DPF-problemet eksisterte ved kjøpet?", a: "Innen 6 måneder har kjøper presumpsjon på sin side. Etter 6 måneder må kjøper sannsynliggjøre feilen via verkstedrapport. Rt. 2007 s. 1274 fastslår at reklamasjon innen 2 måneder alltid er rettidig." }, { q: "Selger hevder tett DPF skyldes min kjørestil. Har han rett?", a: "Mulig, men selger må dokumentere dette. Slettet feilkodehistorikk eller høy sot-nivå ved kjøpet taler mot selger. I sak 2022-1104 ble lignende ansvarsfraskrivelse avvist." }, { q: "DPF-reparasjonen koster 30 000 kr. Kan jeg heve kjøpet?", a: "Dersom utbedringskostnaden utgjør en vesentlig andel av kjøpesummen, kan heving være aktuelt etter kjøpsloven § 39. Be om skriftlig prisestimat fra verksted som grunnlag for kravet." }]},
  { slug: "adblue-system-feil", title: "Reklamasjon på AdBlue-feil og sensorer", lawRef: "FKL § 16", cat: "bilkjop", desc: "AdBlue-problemer er kostbare. Sviktende system kort tid etter kjøp kan gi krav på utbedring.", bodyText: "AdBlue-systemet er påkrevd på moderne dieselbiler for å redusere utslipp av nitrogenoksider. Feil i systemet — typisk defekte sensorer, pumpe eller styringsenhet — kan koste 8 000–25 000 kr å reparere og kan sette bilen i nødmodus der motorytelsen reduseres drastisk. I Forbrukerklageutvalgets sak 2022-1104 ble alvorlige avgass- og motorproblemer fastslått som mangel — prinsippet gjelder tilsvarende for defekte AdBlue-komponenter.\n\nEtter forbrukerkjøpsloven § 16 har bilen en mangel dersom den ikke samsvarer med det kjøper hadde grunn til å forvente. En bil som går i nødmodus pga. AdBlue-feil er ikke i den stand kjøper kunne forvente. Innen 6 måneder presumeres feilen å ha eksistert ved kjøpet — selger må bevise det motsatte.\n\nViktig å skille mellom tom AdBlue-tank (driftsvedlikehold — ditt ansvar) og defekte komponenter i systemet (mangel — selgers ansvar). Få verkstedet til å dokumentere nøyaktig hva som feiler. Reklamér skriftlig innen rimelig tid — Høyesterett fastslo i Rt. 2007 s. 1274 at 2 måneder alltid er innenfor fristen.", faqs: [{ q: "AdBlue-varsellys kom på to uker etter kjøp. Er dette selgers ansvar?", a: "Dersom feilen skyldes defekte sensorer eller pumpe som var til stede ved kjøpet, ja. I sak 2022-1104 ble lignende avgassrelaterte feil ansett som mangel selger svarer for." }, { q: "Kan jeg holde tilbake betaling mens AdBlue-feilen utbedres?", a: "Ja, etter forbrukerkjøpsloven § 28 kan du holde tilbake et beløp tilsvarende utbedringskostnaden frem til selger retter mangelen." }, { q: "Bilen går i nødmodus pga. AdBlue-feil. Kan jeg kreve leiebil?", a: "Dersom mangelen gjør bilen ubrukelig, kan du kreve erstatning for dokumenterte tap — inkludert rimelige leiebilkostnader mens selger utbedrer feilen." }]},
  { slug: "vannlekkasje-kupe", title: "Vannlekkasje inn i kupé eller bagasjerom", lawRef: "KL § 19", cat: "bilkjop", desc: "Fukt og mugglukt pga. utette lister eller drenering kan gi grunnlag for prisavslag eller heving.", bodyText: "Vannlekkasje inn i kupé eller bagasjerom er en alvorlig mangel som kan forårsake mugg, lukt, elektriske feil og korrosjon. Typiske årsaker er utette vindus- og dørlister, tette dreneringshull, sprukne tetningsfjærer eller sveisefeil i karosseriet. I Forbrukerklageutvalgets sak 2023-412 ble vannlekkasje i kupé pga. tette dreneringskanaler ansett som skjult mangel selger var ansvarlig for.\n\nEtter kjøpsloven § 19 har bilen en mangel dersom den ikke svarer til det kjøper hadde grunn til å forvente. En bil skal ikke lekke vann inn i kupéen. Fukt og mugglukt tyder dessuten på at problemet har eksistert over tid, noe som styrker argumentet for at det forelå ved kjøpet. Utbedring kan koste alt fra 2 000 kr for nye lister til 30 000+ kr for karosseriarbeid.\n\nDokumenter lekkasjen med video (helst under regn), ta bilder av fuktige matter og mugg, og få verkstedrapport som identifiserer årsaken. Dersom fuktskaden er omfattende og har gitt følgeskader på elektronikk eller karosseri, kan heving være aktuelt — slik prinsippet i sak 2023-412 tilsier.", faqs: [{ q: "Bilen lukter mugg og gulvmattene er fuktige. Er dette en mangel?", a: "Ja. I sak 2023-412 ble vannlekkasje pga. tette dreneringskanaler ansett som skjult mangel. Mugglukt tyder på at problemet har eksistert en stund — før kjøpet." }, { q: "Kan jeg heve kjøpet pga. vannlekkasje?", a: "Det avhenger av omfanget. Er det dokumentert fuktskade i gulv, elektronikk eller karosseri, og utbedring er uforholdsmessig dyr, kan heving være aktuelt etter kjøpsloven § 39." }, { q: "Vannet har skadet elektronikken i bilen. Kan jeg kreve dette erstattet?", a: "Ja, dokumenterte følgeskader forårsaket av mangelen kan kreves erstattet i tillegg til selve utbedringen. Sak 2023-412 bekrefter at vannlekkasje kan gi omfattende ansvar." }]},
  { slug: "hjullager-ulyd", title: "Ulyd fra hjullager på nylig kjøpt bil", lawRef: "FKL § 15", cat: "bilkjop", desc: "Hjullager som synger rett etter kjøp tyder på slitasje som burde vært opplyst om.", bodyText: "Et hjullager som brummer eller synger er mer enn bare en irriterende lyd — det er et sikkerhetsproblem. Et skadet hjullager som ikke skiftes kan i ytterste konsekvens føre til at hjulet løsner under kjøring. Utbedringskostnaden ligger typisk mellom 3 000 og 8 000 kr per hjul. Høyesterett fastslo i Rt. 2007 s. 1274 (Støvletthæl-dommen) at reklamasjon innen 2 måneder alltid er rettidig.\n\nEtter forbrukerkjøpsloven § 15 skal bilen samsvare med de egenskaper kjøper kan forvente. Et hjullager som svikter etter bare dager eller uker er klart utenfor normal levetid og presumeres å ha vært i dårlig stand ved kjøpet. Selger kan ikke avvise reklamasjonen med henvisning til normal slitasje når svikten kommer så raskt.\n\nLa et verksted dokumentere feilen skriftlig med angivelse av hvilke lager som er skadet og estimert gjenværende levetid. I Rt. 1998 s. 774 (Videospillerdommen) fastslo Høyesterett at produkter ment å vare lenge har 5 års reklamasjonsrett — hjullager på en nyere bil bør holde langt mer enn noen uker.", faqs: [{ q: "Hjullageret begynte å brumme etter én uke. Kan selger skylde på normal slitasje?", a: "Nei. Rt. 2007 s. 1274 fastslår at reklamasjon innen 2 måneder alltid er rettidig, og hjullager som svikter etter én uke er utenfor normal levetid." }, { q: "Verkstedet sier hjullageret er originalt og gammelt. Hva betyr det for saken min?", a: "Det styrker din posisjon. Et slitt originallager som selger ikke opplyste om, er brudd på opplysningsplikten etter KL § 19. Selger burde oppdaget dette før salg." }, { q: "Kan jeg kreve alle fire hjullager skiftet dersom bare ett feiler?", a: "Du kan kreve utbedring av det defekte lageret. Dersom verkstedet anbefaler å skifte flere pga. tilsvarende slitasje, kan dette inngå i kravet som forebyggende utbedring." }]},
  { slug: "stotdempere-utslitt", title: "Defekte støtdempere ved levering", lawRef: "KL § 19", cat: "bilkjop", desc: "Bilen hopper eller er ustabil pga. støtdempere som var utslitte ved kjøp.", bodyText: "Utslitte støtdempere påvirker bilens kjøreegenskaper, bremselengde og stabilitet. En bil som hopper, gynger eller føles ustabil i svinger har sannsynligvis støtdempere som er langt forbi sin levetid. Kostnad for nye støtdempere med montering ligger typisk mellom 6 000 og 20 000 kr for et komplett sett. I Forbrukerklageutvalgets sak 2022-190 ble det fastslått at sikkerhetskritiske feil trumfer selgers «som den er»-forbehold — prinsippet gjelder også for utslitte støtdempere som påvirker kjøresikkerhet.\n\nEtter kjøpsloven § 19 foreligger mangel dersom bilen ikke er i samsvar med det kjøper hadde grunn til å forvente. Selv om støtdempere er slitedeler, forventes det at de er i akseptabel stand ved levering. Støtdempere som er så slitte at de påvirker kjøresikkerhet, er en mangel selger burde ha opplyst om.\n\nEn profesjonell støtdempertest på verksted gir objektiv dokumentasjon. Testen sammenligner demperkraften med minimumsverdier for bilens type og vekt. Reklamér skriftlig innen rimelig tid — Rt. 2007 s. 1274 fastslår at 2 måneder alltid er innenfor fristen.", faqs: [{ q: "Støtdemperne er utslitte ifølge verkstedet. Kan selger si dette er normal slitasje?", a: "Avhenger av alder og km. I sak 2022-190 ble det fastslått at sikkerhetskritiske feil ikke kan forbeholdes bort med «som den er». Er demperne unormalt slitte for bilens alder, er det mangel." }, { q: "Hva er rimelig krav — utbedring eller prisavslag?", a: "Du velger. Utbedring (nye støtdempere) eller prisavslag tilsvarende utbedringskostnaden. Heving er sjelden aktuelt for støtdempere alene, men kumulative mangler kan styrke kravet." }, { q: "Bilen bestod ikke EU-kontroll pga. støtdemperne. Har jeg rett til heving?", a: "Alene gir det sjelden heving, men sammen med andre feil fra EU-kontrollen kan den samlede mangelen oppfylle vesentlighetskravet etter KL § 39." }]},
  { slug: "feilkode-motorlampe", title: "Motorlampe lyser rett etter bilkjøp", lawRef: "FKL § 16", cat: "bilkjop", desc: "Lysende motorlampe er det klareste tegnet på en mangel. Sjekk dine rettigheter.", bodyText: "Motorlampe som lyser er det tydeligste signalet på at noe er galt med bilen. Feilkoden bak lampen kan indikere alt fra en løs tankplugg til alvorlige motorproblemer. I Forbrukerklageutvalgets sak 2021-1930 ble turbo-havari kort tid etter salg ansett som mangel som ga full dekning av reparasjon — motorlampe er ofte det første varselet om slike feil.\n\nEtter forbrukerkjøpsloven § 16 har bilen en mangel dersom den ikke svarer til det kjøper hadde grunn til å forvente. Feilkoder som ble slettet rett før salget dukker typisk opp igjen raskt etter kjøpet. En OBD-utlesning kan avsløre om koder nylig ble slettet — dette er sterkt bevis for at selger bevisst skjulte en kjent feil.\n\nReklamér skriftlig umiddelbart — Høyesterett fastslo i Rt. 2007 s. 1274 at 2 måneder alltid er innenfor fristen. Be om komplett feilkodeutskrift fra verksted med datoer og feilhistorikk. Ikke reparer bilen for egen regning før du har reklamert — da mister du muligheten til å kreve dekket kostnadene.", faqs: [{ q: "Motorlampen kom på dagen etter levering. Hva gjør jeg?", a: "Reklamér skriftlig til selger umiddelbart. I sak 2021-1930 fikk kjøper full dekning av reparasjon etter motorproblem kort tid etter salg. Ikke reparer på egen regning før du har reklamert." }, { q: "Selger sier motorlampen kom av at jeg kjørte feil. Kan han ha rett?", a: "Kun dersom han kan dokumentere dette. En feilkode leses av verksted og forteller nøyaktig hva som er feil. Slettet feilkodehistorikk taler mot selger." }, { q: "Feilkodene ble slettet like før salget. Er det bevis for juks?", a: "Ja, slettet feilkodehistorikk rett før salg er sterkt bevis for at selger bevisst skjulte kjente feil. Dette styrker reklamasjonskravet betydelig." }]},
  { slug: "soltak-lekkasje-feil", title: "Feil med soltak eller panoramatak", lawRef: "KL § 19", cat: "bilkjop", desc: "Lekkasje eller mekanisk feil på soltak er dyrt og utgjør ofte en kjøpsrettslig mangel.", bodyText: "Soltak og panoramatak er luksusfeatures som dessverre er blant de mest problemutsatte komponentene på bruktbiler. Lekkasje fra dreneringssystem, defekte tetninger eller mekanisk svikt kan koste 5 000–30 000 kr å reparere, og følgeskader fra vannlekkasje kan gjøre situasjonen enda dyrere. I Forbrukerklageutvalgets sak 2023-412 ble vannlekkasje i kupé pga. tette dreneringskanaler ansett som skjult mangel — samme prinsipp gjelder for soltak-lekkasje.\n\nEtter kjøpsloven § 19 har bilen en mangel dersom selger har holdt tilbake opplysninger om kjente problemer. Soltak-lekkasje er et problem som typisk utvikler seg over tid — tette dreneringshull, sprukne slanger og utslitte tetninger er alle tegn på langvarig slitasje som selger burde ha kjent til.\n\nDokumenter lekkasjen med video og bilder. Få verkstedrapport som identifiserer den konkrete årsaken. Dersom følgeskader som fukt i takfôr, mugg eller elektronikkfeil har oppstått, skal disse inkluderes i kravet. Reklamér innen rimelig tid — Rt. 2007 s. 1274 fastslår at 2 måneder alltid holder.", faqs: [{ q: "Soltaket lekker ved regn. Selger sier det er normal slitasje. Stemmer det?", a: "Nei. I sak 2023-412 ble vannlekkasje via tette dreneringskanaler ansett som skjult mangel. Et soltak som lekker er ikke normal slitasje — selger plikter å opplyse om dette." }, { q: "Panoramataket knirker og glir ikke jevnt. Er det en mangel?", a: "Dersom mekanikken ikke fungerer som den skal og dette ikke ble opplyst, er det en mangel etter KL § 19. Krev utbedring hos selger med vedlagt verkstedrapport." }, { q: "Vannlekkasjen har forårsaket mugg i taktrekket. Kan jeg kreve dette reparert?", a: "Ja, følgeskader forårsaket av mangelen kan kreves erstattet. Sak 2023-412 bekrefter at vannlekkasje kan gi ansvar for hele skadeomfanget." }]},
  { slug: "sentrallas-nokkelfri-feil", title: "Problemer med sentrallås eller Keyless", lawRef: "FKL § 16", cat: "bilkjop", desc: "Nøkkelen gjenkjennes ikke eller dørene låses ikke — kjøpsrettslig mangel.", bodyText: "Feil på sentrallås eller Keyless-system gjør at bilen ikke kan låses eller låses opp pålitelig — et sikkerhetsproblem og et daglig irritasjonsmoment. Reparasjon kan innebære alt fra nøkkelomprogrammering (2 000–5 000 kr) til bytte av hele låsmodulen eller styreenheten (10 000–25 000 kr). I Forbrukerklageutvalgets sak 2021-882 ble feil ved elektronikk ansett som mangel som ga utbedringsansvar — prinsippet gjelder tilsvarende for sentrallås- og Keyless-feil.\n\nEtter forbrukerkjøpsloven § 16 har bilen en mangel dersom den ikke fungerer som forventet. Et sentrallåssystem er en grunnleggende sikkerhetsfunksjon som må virke. Dersom feilen er sporadisk og vanskelig å gjenskape, er video-dokumentasjon fra flere anledninger verdifull bevisføring.\n\nTest nøkkelen med nytt batteri først — dette eliminerer den enkleste forklaringen. Dersom problemet vedvarer, reklamér skriftlig til selger. Høyesterett fastslo i Rt. 2007 s. 1274 at 2 måneder alltid er innenfor reklamasjonsfristen. Selger har rett til ett utbedringsforsøk.", faqs: [{ q: "Keyless-systemet virker av og til. Kan selger si det er batteriet i nøkkelen?", a: "Selger kan foreslå det, men dersom problemet vedvarer etter nytt batteri, er det en feil i bilens system. I sak 2021-882 ble elektronikkfeil ansett som mangel selger svarer for." }, { q: "Sentrallåsen svikter sporadisk. Er det nok til å kreve utbedring?", a: "Ja. Sporadiske feil er vanskeligere å dokumentere, men video-bevis og verkstedrapport er tilstrekkelig grunnlag. Rt. 2007 s. 1274 fastslår at reklamasjon innen 2 måneder er rettidig." }, { q: "Kan manglende sentrallås gi heving av kjøpet?", a: "Alene sjelden nok for heving, men sammen med andre mangler kan det styrke en hevingssak. Prisavslag tilsvarende utbedringskostnaden er normalt mest realistisk." }]},
  { slug: "ryggekamera-sensor-feil", title: "Defekt ryggekamera eller parkeringssensor", lawRef: "KL § 17", cat: "bilkjop", desc: "Hjelpesystemer som ikke virker er mangel dersom de var inkludert i utstyrslisten.", bodyText: "Ryggekamera og parkeringssensorer er sikkerhetsutstyr som mange kjøpere legger stor vekt på ved bilvalg. Dersom disse systemene er oppført i utstyrslisten men ikke fungerer, foreligger en mangel. Reparasjon av ryggekamera koster typisk 3 000–10 000 kr, mens sensorer kan koste 1 500–5 000 kr per sensor. I Forbrukerklageutvalgets sak 2021-882 ble feil ved elektronikk og tilbehør ansett som mangel med utbedringsansvar.\n\nEtter kjøpsloven § 17 foreligger mangel dersom bilen mangler egenskaper som selger har fremhevet eller som fremgår av utstyrslisten. Sjekk salgsdokumentene, annonsen og eventuelt bilens utstyrskode — dersom ryggekamera eller sensorer er oppført, skal de fungere. Prinsippet fra sak 2023-344 om utbedring av defekt elektronikk gjelder tilsvarende.\n\nDokumenter feilen med video som viser svart skjerm, feilmelding eller feilaktige sensorvarsler. Reklamér skriftlig til selger og krev utbedring innen rimelig tid — Rt. 2007 s. 1274 fastslår at 2 måneder alltid er innenfor fristen.", faqs: [{ q: "Ryggekameraet viser svart bilde. Selger sier det ikke var med i kjøpet. Hva gjør jeg?", a: "Sjekk salgsdokumentene og utstyrslisten. I sak 2021-882 ble feil ved elektronikk ansett som mangel. Er kameraet montert og oppført, er det inkludert i kjøpet." }, { q: "Parkeringssensorene piper konstant uten grunn. Er dette en mangel?", a: "Ja, defekte sensorer som gir falske signaler er en mangel. I sak 2023-344 ble defekt elektronikk ansett som mangel med utbedringsrett — prinsippet gjelder tilsvarende." }, { q: "Hvor lang er reklamasjonsfristen for elektronikk i bilen?", a: "Ved forhandlerkjøp er fristen 5 år (FKL § 27). Rt. 1998 s. 774 fastslår at produkter ment å vare lenge har utvidet reklamasjonsrett. Ved privatkjøp gjelder 2 års frist." }]},
  { slug: "varmeseter-defekt", title: "Defekte varmeseter i bruktbil", lawRef: "KL § 17", cat: "bilkjop", desc: "Varmeseter som ikke virker skal normalt opplyses om ved salg.", bodyText: "Varmeseter er komfort-utstyr som sjelden utgjør grunnlag for heving alene, men som likevel er en mangel dersom de ikke fungerer og dette ikke ble opplyst om. Reparasjonskostnaden varierer fra 2 000 kr for et enkelt varmeelement til 8 000 kr for hele setemodulen med elektronikk. I Forbrukerklageutvalgets sak 2023-344 ble defekt utstyr som var en del av bilens spesifikasjoner ansett som mangel med utbedringsrett — prinsippet gjelder også for varmeseter.\n\nEtter kjøpsloven § 17 foreligger mangel dersom bilen mangler egenskaper som kjøper hadde grunn til å forvente basert på bilens utstyrsnivå og pris. Dersom bilen ble annonsert med varmeseter, skal de fungere. Selger kan ikke hevde at slik feil er normal slitasje uten å dokumentere dette.\n\nReklamér skriftlig og krev utbedring eller prisavslag. Høyesterett fastslo i Rt. 2007 s. 1274 at reklamasjon innen 2 måneder alltid er rettidig. Dersom varmeseter-feilen opptrer sammen med andre mangler, kan den samlede mangelsbyrden gjøre at vesentlighetskravet for heving likevel er oppfylt.", faqs: [{ q: "Varmesetene virket da jeg kjøpte bilen, men sluttet etter en uke. Kan jeg reklamere?", a: "Ja, innen 6 måneder presumeres feilen å ha eksistert ved kjøpet. I sak 2023-344 ble tilsvarende utstyrsfeil ansett som mangel med utbedringsrett." }, { q: "Er defekte varmeseter alene nok til å heve kjøpet?", a: "Neppe alene. Varmeseter er komfort-utstyr, ikke sikkerhetskritisk. Prisavslag tilsvarende utbedringskostnaden (2 000–8 000 kr) er mer realistisk." }, { q: "Kan kumulative småfeil gi hevingsrett?", a: "Ja, flere småfeil som samlet utgjør et vesentlig kontraktsbrudd kan gi heving etter KL § 39. Defekte varmeseter sammen med andre mangler styrker saken." }]},
  { slug: "vindusheis-defekt", title: "Vindusheis som ikke fungerer", lawRef: "KL § 17", cat: "bilkjop", desc: "Elektriske vindusheiser som svikter kort tid etter kjøp er typisk reklamasjonssak.", bodyText: "En vindusheis som ikke fungerer er mer enn en ulempe — vinduet kan ikke lukkes ved regn, det utgjør en sikkerhetsrisiko og bilen kan ikke brukes i bomstasjoner med manuell betaling. Reparasjon koster typisk 2 000–6 000 kr for motor og mekanikk, mer dersom det er elektronisk styringsfeil. I Forbrukerklageutvalgets sak 2021-882 ble feil ved elektronikk og tilbehør ansett som mangel med utbedringsansvar.\n\nEtter kjøpsloven § 17 har bilen en mangel dersom den ikke samsvarer med det kjøper hadde grunn til å forvente. Alle vindusheiser skal fungere ved levering. Selger har rett til å forsøke utbedring først, men ved gjentatt svikt kan du reparere for selgers regning.\n\nDokumenter feilen med video og reklamér skriftlig. Høyesterett fastslo i Rt. 2007 s. 1274 at reklamasjon innen 2 måneder alltid er rettidig. Dersom flere vindusheiser er defekte, styrker dette argumentet for at bilen generelt var i dårligere stand enn forespeilet.", faqs: [{ q: "Vindusheisen på førersiden virker ikke. Selger sier det er normal slitasje. Har han rett?", a: "For en nyere bil (under 10 år) er sviktende vindusheis utenfor normal slitasje. I sak 2021-882 ble elektronikkfeil ansett som mangel uavhengig av alder." }, { q: "Kan jeg reparere vindusheisen selv og kreve penger av selger?", a: "Du bør først reklamere og gi selger mulighet til å utbedre. Dersom selger avviser eller ikke svarer innen rimelig tid (2–4 uker), kan du reparere for selgers regning." }, { q: "Flere vindusheiser er defekte. Styrker det saken min?", a: "Ja, kumulative mangler styrker vesentlighetsvurderingen etter KL § 39. Flere defekte vindusheiser tyder på generelt dårlig vedlikehold selger burde opplyst om." }]},
  { slug: "xenon-led-lys-feil", title: "Feil på Xenon eller LED-hovedlys", lawRef: "FKL § 16", cat: "bilkjop", desc: "Moderne lysmoduler koster titusenvis. Sjekk om selger må dekke bytte.", bodyText: "Moderne Xenon- og LED-lysmoduler er ekstremt dyre å bytte — en enkelt modul kan koste 15 000–40 000 kr. Feil i hovedlysene er dessuten sikkerhetskritisk fordi nedsatt sikt øker ulykkesrisikoen vesentlig. Rt. 1998 s. 774 (Videospillerdommen) fastslår at produkter ment å vare lenge har 5 års reklamasjonsrett — LED-lys med forventet levetid på 15 000–30 000 timer faller klart innenfor dette prinsippet.\n\nEtter forbrukerkjøpsloven § 16 presumeres feil som viser seg innen 6 måneder å ha eksistert ved overlevering. LED-lys har svært lang forventet levetid, så svikt kort tid etter kjøpet tyder sterkt på en eksisterende defekt. Selger er ansvarlig uavhengig av om han kjente til feilen — objektivt ansvar gjelder.\n\nHent inn prisestimat fra merkeverksted og reklamér skriftlig innen rimelig tid. Høyesterett fastslo i Rt. 2007 s. 1274 at 2 måneder alltid er innenfor fristen. Dersom utbedringskostnaden utgjør en vesentlig del av kjøpesummen, kan heving være aktuelt.", faqs: [{ q: "Det ene LED-lyset sluknet etter to uker. Selger sier det er normalt. Stemmer det?", a: "Nei. LED-lys har svært lang levetid. Svikt etter to uker er klar defekt. Rt. 1998 s. 774 fastslår utvidet reklamasjonsrett for varige produkter — LED-lys er nettopp det." }, { q: "Et nytt Xenon-modul koster 25 000 kr. Kan jeg kreve heving pga. dette alene?", a: "Mulig. Dersom utbedringskostnaden utgjør en vesentlig del av kjøpesummen og feilen ikke ble opplyst, kan vesentlighetskravet for heving etter KL § 39 være oppfylt." }, { q: "Gjelder 5-årsfristen for reklamasjon på billys?", a: "Ja, ved forhandlerkjøp gjelder 5 år etter FKL § 27. Rt. 1998 s. 774 bekrefter utvidet frist for varige produkter. LED-moduler er ment å vare bilens levetid." }]},
  { slug: "oljelekkasje-motor-gir", title: "Oljelekkasje fra motor eller girkasse", lawRef: "KL § 19", cat: "bilkjop", desc: "Bilen 'markerer revir' rett etter kjøp — ofte en skjult mangel selger svarer for.", bodyText: "En bil som lekker olje etterlater seg flekker på parkeringsplassen og kan i verste fall føre til motorhavari dersom oljenivået blir kritisk lavt. Årsaken kan være slitte pakninger, defekte simmerringer, sprukne oljekjølere eller alvorlige skader i motor- eller girkasseblokken. I Forbrukerklageutvalgets sak 2022-1104 ble ekstremt oljeforbruk på en Audi TFSI fastslått som mangel — prinsippet gjelder tilsvarende for synlige oljelekkasjer.\n\nEtter kjøpsloven § 19 har bilen en mangel dersom den ikke svarer til det kjøper hadde grunn til å forvente. En bil skal ikke lekke olje — selv mindre lekkasjer er en mangel selger plikter å utbedre. Reparasjonskostnaden varierer enormt: en enkel pakningsjobb kan koste 3 000–5 000 kr, mens lekkasje fra motorblokk eller girkasse kan kreve titusener.\n\nDokumenter lekkasjen med bilder av oljeflekker og få verkstedrapport som identifiserer kilde og årsak. Reklamér skriftlig innen rimelig tid — Rt. 2007 s. 1274 fastslår at 2 måneder alltid er innenfor fristen.", faqs: [{ q: "Bilen lekker olje på parkeringsplassen. Selger sier det er normale drypp. Er det riktig?", a: "Nei. En bil skal ikke lekke olje. I sak 2022-1104 ble unormalt oljeforbruk fastslått som mangel — synlig oljelekkasje er enda mer åpenbart en mangel." }, { q: "Kan oljelekkasje gi grunnlag for heving av kjøpet?", a: "Avhenger av årsaken. Lekkasje fra motorblokk eller girkasse kan indikere alvorlig slitasje. I sak 2023-112 ga motorhavari pga. oljeproblemer rett til heving." }, { q: "Selger hevder oljelekkasjen oppsto etter kjøpet. Hvem har bevisbyrden?", a: "Innen 6 måneder ved forhandlerkjøp presumeres feilen å ha eksistert ved overtakelse — selger må bevise det motsatte. Ved privatkjøp må du sannsynliggjøre det via verkstedrapport." }]},
  { slug: "airbag-lampe-feil", title: "Airbag-lampe lyser: Sikkerhetsmangel", lawRef: "FKL § 15", cat: "bilkjop", desc: "Feil på sikkerhetssystemer er kritiske mangler som nesten alltid gir rett til utbedring.", bodyText: "Lysende airbag-lampe betyr at bilens passive sikkerhetssystem kan være helt eller delvis deaktivert. Ved en kollisjon kan airbagene unnlate å utløses, noe som setter fører og passasjerer i livsfare. Dette er en sikkerhetskritisk mangel av alvorligste slag. I Forbrukerklageutvalgets sak 2022-190 ble det fastslått at sikkerhetskritiske feil trumfer selgers «som den er»-forbehold — prinsippet gjelder i aller høyeste grad for airbag-feil.\n\nEtter forbrukerkjøpsloven § 15 skal bilen ha de sikkerhetsegenskaper kjøper kan forvente. Et fungerende airbag-system er en absolutt forutsetning. Selger er ansvarlig selv uten kunnskap om feilen — objektivt ansvar gjelder for skjulte mangler. Feilsøking koster typisk 2 000–5 000 kr, mens reparasjon kan koste 5 000–30 000 kr.\n\nReklamér umiddelbart — Høyesterett fastslo i Rt. 2007 s. 1274 at 2 måneder alltid er innenfor fristen. Ikke kjør bilen med lysende airbag-lampe — det er farlig og kan redusere forsikringsutbetalingen ved ulykke.", faqs: [{ q: "Airbag-lampen lyser. Er bilen trygg å kjøre?", a: "Ikke nødvendigvis. Airbag-systemet kan være deaktivert. Reklamér umiddelbart. I sak 2022-190 ble sikkerhetsfeil ansett som mangel som trumfer alle forbehold." }, { q: "Selger visste ikke om airbag-feilen. Har jeg likevel krav?", a: "Ja. Selger er objektivt ansvarlig for skjulte mangler. Airbag-feil er normalt vesentlig, og sak 2022-190 fastslår at sikkerhetsfeil ikke kan forbeholdes bort — selv med «som den er»." }, { q: "Kan airbag-feil gi heving av kjøpet?", a: "Ja, airbag-feil er sikkerhetskritisk og veier tungt i vesentlighetsvurderingen etter KL § 39. Sammen med andre mangler er heving svært realistisk." }]},
  { slug: "vibrasjoner-under-kjoring", title: "Uforklarlige vibrasjoner i ratt eller bil", lawRef: "KL § 18", cat: "bilkjop", desc: "Vibrasjoner kan skyldes alt fra dekk til drivverk. Finn ut hvem som har ansvaret.", bodyText: "Vibrasjoner i ratt, seter eller karosseri under kjøring kan skyldes alt fra enkle problemer som ubalanserte hjul til alvorlige feil som slitte drivaksler, defekte ledd eller motorlagringssvikt. I Forbrukerklageutvalgets sak 2020-552 ble registerreimbrudd før skifteintervall ansett som mangel som utløste full erstatning — prinsippet om at mekaniske svikt kort tid etter kjøp tyder på eksisterende feil, gjelder tilsvarende for vibrasjoner.\n\nEtter kjøpsloven § 18 foreligger mangel dersom selger har gitt uriktige opplysninger om bilens tilstand. Vibrasjoner som er merkbare ved prøvekjøring burde selger ha oppdaget og opplyst om. Innen 6 måneder har kjøper presumpsjon for at feilen forelå ved kjøpet.\n\nStart med den enkleste diagnosen: hjulbalansering og dekkssjekk. Dersom vibrasjonene vedvarer, be verkstedet undersøke drivaksler, ledd, drivskive og motorlagre. Reklamér skriftlig innen rimelig tid — Rt. 2007 s. 1274 fastslår at 2 måneder alltid er innenfor fristen.", faqs: [{ q: "Rattet vibrerer ved 80 km/t. Selger sier det bare er hjulbalansering. Har han rett?", a: "Mulig, men hjulbalansering er vedlikehold selger burde utføre ved salg. Dersom vibrasjoner vedvarer etter balansering, er det en dypere mangel. I sak 2020-552 ga mekanisk svikt full erstatning." }, { q: "Verkstedet sier vibrasjonene skyldes slitte drivaksler. Er det reklamasjonsgrunnlag?", a: "Ja, slitte drivaksler er en skjult mangel selger er ansvarlig for. Innen 6 måneder presumeres feilen å ha eksistert ved kjøpet — selger må bevise det motsatte." }, { q: "Vibrasjoner kommer og går. Er det likevel grunnlag for reklamasjon?", a: "Ja, intermitterende feil er like gyldige. Dokumenter med video og kjøredagbok. Sporadiske vibrasjoner kan tyde på defekte ledd eller lagre som forverres over tid." }]},
  { slug: "eksosanlegg-rust-stoy", title: "Defekt eller rustent eksosanlegg", lawRef: "KL § 17", cat: "bilkjop", desc: "Eksosanlegg som faller av eller bråker unormalt rett etter overtakelse.", bodyText: "Et eksosanlegg som bråker, ruster i stykker eller lekker avgasser kort tid etter kjøpet er en mangel som kan koste 3 000–20 000 kr å utbedre. Avgasslekkasje er dessuten en helsefare fordi karbonmonoksid kan trenge inn i kupéen. I Forbrukerklageutvalgets sak 2022-1784 ble skjult rust i bærende konstruksjoner ansett som vesentlig mangel — prinsippet gjelder tilsvarende for gjennomrustet eksosanlegg.\n\nEtter kjøpsloven § 17 har bilen en mangel dersom den ikke har de egenskaper kjøper kan forvente basert på alder, pris og presentasjon. Selv om noe eksos-rust er normalt på eldre biler, er gjennomrustet eksosanlegg en mangel som påvirker både funksjon og sikkerhet. Rt. 1998 s. 774 (Videospillerdommen) fastslår at produkter ment å vare lenge har utvidet reklamasjonsrett.\n\nDokumenter problemet med bilder og verkstedrapport. Be verkstedet vurdere om rusten er av nyere eller eldre dato — gjennomgående rust som oppstår kort tid etter kjøp tyder på at eksosen allerede var sterkt svekket ved overlevering.", faqs: [{ q: "Eksosen begynte å lage støy etter én uke. Er det reklamasjonsgrunnlag?", a: "Ja. I sak 2022-1784 ble skjult rust ansett som vesentlig mangel. Unormal støy etter én uke tyder klart på eksisterende skade selger burde opplyst om." }, { q: "Selger sier rust på eksosen er normalt for en gammel bil. Har han rett?", a: "Noe rust er normalt, men gjennomrustet eksos med funksjonsfeil er mangel etter KL § 17. Selger plikter å opplyse om alvorlig rust han kjente til." }, { q: "Avgasslekkasje gir hodepine under kjøring. Er det farlig nok for heving?", a: "Avgasslekkasje i kupéen er en alvorlig helsefare. Kombinert med høy utbedringskostnad kan dette oppfylle vesentlighetskravet for heving etter KL § 39." }]},
  { slug: "varmeapparat-webasto-feil", title: "Feil på varmeapparat eller Webasto", lawRef: "FKL § 16", cat: "bilkjop", desc: "Dårlig varme eller defekt parkeringsvarmer er en vesentlig mangel i norsk klima.", bodyText: "I norsk klima er et fungerende varmeapparat eller Webasto-anlegg ikke luksus — det er en nødvendighet. Defekt parkeringsvarmer eller svak kupévarme kan gjøre bilen ubrukelig i vinterhalvåret. Reparasjon av Webasto koster typisk 5 000–20 000 kr. Rt. 1998 s. 774 (Videospillerdommen) fastslår at produkter ment å vare lenge har 5 års reklamasjonsrett — Webasto-anlegg og varmeapparater faller klart innenfor dette prinsippet.\n\nEtter forbrukerkjøpsloven § 16 har bilen en mangel dersom den ikke samsvarer med det kjøper hadde grunn til å forvente. Dersom Webasto er montert og fremgår av bilens utstyrsliste eller ble fremhevet i salgsannonsen, er det inkludert i kjøpet og skal fungere. I sak 2023-344 ble defekt utstyr som var del av bilens spesifikasjoner ansett som mangel med utbedringsrett.\n\nLa verkstedet diagnostisere om feilen ligger i Webasto-enheten, styringselektronikk eller bilens eget varmesystem. Reklamér skriftlig innen rimelig tid — Rt. 2007 s. 1274 fastslår at 2 måneder alltid er innenfor fristen. I norsk klima kan mangel på varme argumenteres som vesentlig mangel.", faqs: [{ q: "Webasto-anlegget virker ikke. Selger sier det ikke var inkludert i kjøpet. Hva gjør jeg?", a: "Sjekk salgsdokumentene. I sak 2023-344 ble utstyr som fremgår av bilens spesifikasjoner ansett som inkludert. Er Webasto montert og oppført, er selger ansvarlig." }, { q: "Varmen i bilen er svak selv på maks. Er det en mangel?", a: "Kan være det. Svak varme kan skyldes defekt termostat, slitt kjølevæskepumpe eller tilstoppet varmeapparat. Rt. 1998 s. 774 gir 5 års reklamasjonsrett på varige komponenter." }, { q: "Er mangel på varme vesentlig nok for heving i Norge?", a: "I norsk klima kan dette argumenteres sterkt. En bil uten fungerende varme er ubrukelig store deler av året, noe som veier tungt i vesentlighetsvurderingen etter KL § 39." }]},
  { slug: "bruktbil-eu-kontroll-fusk", title: "Bruktbil solgt med fersk men feilaktig EU-kontroll", lawRef: "KL § 18", cat: "bilkjop", desc: "Dersom bilen har alvorlige feil som burde vært oppdaget på kontrollen, har du en sterk sak.", bodyText: "Når en bruktbil selges med fersk EU-godkjenning, stoler kjøper på at bilen er i teknisk forsvarlig stand. Dersom det kort tid etter avdekkes alvorlige feil som bremsesvikt, rust i bærende deler eller lysfeil, kan det tyde på at EU-kontrollen ble utført lemfeldig. I Forbrukerklageutvalgets sak 2022-190 ble defekte bremser oppdaget rett etter EU-kontroll ansett som mangel som trumfet «som den er»-forbehold. I sak 2021-1209 ble kilometerfusk med 60 000 km avvik ansett som grunnlag for heving — tilsvarende prinsipp gjelder ved feilaktig EU-kontroll.\n\nEtter kjøpsloven § 18 har bilen en mangel dersom selger har gitt uriktige opplysninger. En fersk EU-godkjenning impliserer at bilen er i teknisk orden. Dersom det viser seg at bilen har alvorlige feil som burde vært avdekket, har du en sterk sak — både mot selger og potensielt mot kontrollorganet.\n\nDokumenter feilene med ny verkstedrapport og sammenlign med EU-kontroll-protokollen. Dersom feilene åpenbart eksisterte ved kontrolltidspunktet, kan du reklamere til selger og vurdere å anmelde kontrollstasjonen til Statens vegvesen.", faqs: [{ q: "Bilen fikk EU-godkjenning for 2 måneder siden men har alvorlige bremseproblemer. Hva gjør jeg?", a: "Reklamér til selger. I sak 2022-190 ble bremsedefekter etter EU-kontroll ansett som mangel. Dokumenter feilen med verkstedrapport og vurder å anmelde kontrollstasjonen." }, { q: "Kan jeg holde selger ansvarlig for at EU-kontrollen ikke avdekket feilene?", a: "Ja. Selger garanterer implisitt at bilen er i den stand EU-kontrollen tilsier. I sak 2021-1209 ga juks med bilens dokumentasjon rett til heving — tilsvarende gjelder for feilaktig EU-kontroll." }, { q: "Kan jeg også klage på kontrollstasjonen?", a: "Ja, dersom feilene åpenbart eksisterte ved kontrolltidspunktet, kan du anmelde kontrollstasjonen til Statens vegvesen. Du har separate krav mot selger og kontrollorganet." }]},

  // BILKJØP (nye noder med bodyText)
  { slug: "vanninntrengning-kupe", title: "Vannintrengning i kupé etter bilkjøp", lawRef: "KL § 19", cat: "bilkjop", desc: "Vannintrengning i kupé er skjult mangel som gir rett til utbedring eller heving.", bodyText: "Vann i kupéen er en alvorlig feil som kan skade elektronikk, gi mugglukt, råte i gulvmatter og forårsake kortslutning i det elektriske anlegget. Problemet skyldes ofte defekte dørtetninger, sprukket vindusramme, korrodert bunnstopper eller skader etter kollisjon som ikke ble korrekt reparert.\n\nVannintrengning er nesten alltid en pre-eksisterende feil — selger som jevnlig brukte bilen vil ha oppdaget fuktlukten eller sett vann i bunnmatten. Dersom selger ikke opplyste om dette, er det brudd på opplysningsplikten etter kjøpsloven § 19.\n\nDokumenter med bilder og fuktmålinger. En karosseriekspert kan vurdere årsaken og anslå reparasjonskostnad. Utbedring kan koste 5 000–30 000 kr avhengig av omfang og om elektronikk er skadet.", faqs: [{ q: "Det lukter mugg i bilen men jeg ser ikke vann. Er det nok til å reklamere?", a: "Ja, mugglukt er sterk indikasjon på tidligere eller pågående vannintrengning. Krev karosseriinspeksjon og reklamér skriftlig." }, { q: "Selger sier det bare skjer ved kraftig regn. Er det en mangel?", a: "Ja. En bil som er tett skal være tett i alle normale værforhold. Lekkasje ved kraftig regn er en mangel." }, { q: "Vannet har ødelagt radioen og gulvmattene. Kan jeg kreve disse erstattet?", a: "Ja, dokumenterte følgeskader forårsaket av mangelen kan kreves erstattet i tillegg til selve utbedringen." }]},
  { slug: "rammeknekk-skjult", title: "Skjult rammeknekk etter kollisjon på bruktbil", lawRef: "KL § 18", cat: "bilkjop", desc: "Skjult rammeknekk er svik og gir rett til heving og erstatning.", bodyText: "Rammeknekk etter kollisjon er en av de mest alvorlige skjulte feilene ved bilkjøp. Biler med skadet ramme eller bærende karosseri har redusert kollisjonssikkerhet og kan oppføre seg uforutsigbart i trafikken. Dersom selger kjente til rammeknekken og ikke opplyste om den, er det svik etter kjøpsloven § 18.\n\nTegn på skjult rammeknekk inkluderer ujevne spalter mellom dører og karosseri, biler som trekker til siden, dører som ikke lukker jevnt og synlige reparasjonsspor inne i motorrommets kanter. En karosseriekspert kan med lasermåling av karosseriet fastslå om bilen har vært i alvorlig kollisjon.\n\nDersom skaden er dokumentert, har du sterkt grunnlag for heving pluss erstatning for utgifter til inspeksjon og eventuell tapt bruk av kjøretøy.", faqs: [{ q: "Bilen har fartsskritthistorikk fra NAF. Viser det ingen kollisjon. Kan selger skjule det?", a: "NAF-historikk er ikke komplett — ikke alle skader registreres. En karosseriinspeksjon er mer pålitelig enn historikkrapporter alene." }, { q: "Selger sier han ikke visste om rammeknekken. Kan han fritas for ansvar?", a: "Nei. Selger er ansvarlig for skjulte mangler uavhengig av kunnskap, forutsatt at mangelen forelå ved kjøpet. Svik krever kunnskap, men mangel gjør det ikke." }, { q: "Bilen er reparert etter kollisjonen. Er det da en mangel?", a: "Avhenger av kvaliteten på reparasjonen. Korrekt utbedret kollisjonsskade er ikke nødvendigvis en mangel, men selger plikter å opplyse om skadehistorikken." }]},
  { slug: "motorlys-feilmeldinger", title: "Vedvarende motorlys og feilmeldinger etter kjøp", lawRef: "FKL § 16", cat: "bilkjop", desc: "Motorlys som lyser rett etter kjøp tyder på nullstilte feilkoder og skjult problem.", bodyText: "Motorlyset (MIL — Malfunction Indicator Lamp) indikerer at bilens motorstyringssystem har registrert en feil. Det er svært vanlig at useriøse selgere nullstiller feilkoder rett før salg slik at motorlyset ikke lyser under visning — men feilkodene dukker opp igjen etter noen kjørte km.\n\nVerksted kan lese feilkodehistorikk fra ECU og i mange tilfeller se tidsstempel for første gangs registrering av feilen. Dersom tidsstempelet er fra før salgsdatoen, er det bevis på at selger kjente til feilen.\n\nFeilmeldinger kan indikere alt fra enkle sensorfeil (100–500 kr å fikse) til alvorlige problemer med motor, catalysator eller avgassrensing. Uansett alvorlighetsgrad er skjulte feilkoder brudd på opplysningsplikten.", faqs: [{ q: "Motorlyset lyste ikke ved kjøp men tente seg etter 200 km. Er det selgers problem?", a: "Ja. Feilkoder som dukker opp etter få km presumeres å ha eksistert ved kjøpet. Særlig mistenksomt dersom ECU viser at feilen ble nullstilt nylig." }, { q: "Selger sier det bare er en oksygensensor og tilbyr 500 kr prisavslag. Bør jeg akseptere?", a: "Bare dersom det faktisk er en enkel sensorfeil. Be om verksteddiagnose som bekrefter dette — noen ganger er sensor-feilkoden symptom på et dypere problem." }, { q: "Kan jeg kreve at selger fikser alle feilkoder uansett årsak?", a: "Du kan kreve utbedring av feil som forelå ved kjøpet. Dersom feilkoder dokumenteres å ha eksistert ved salget ja, uavhengig av kostnaden." }]},
  { slug: "4wd-system-feil", title: "Feil på firehjulsdrift (4WD/AWD) etter kjøp", lawRef: "FKL § 15", cat: "bilkjop", desc: "4WD/AWD-system som ikke fungerer er vesentlig mangel dersom bilen ble solgt som firehjulsdrift.", bodyText: "Firehjulsdrift er for mange kjøpere et avgjørende kriterium — særlig i Norge med krevende vinterforhold. Dersom 4WD- eller AWD-systemet ikke fungerer korrekt, er dette et vesentlig avvik fra det bilen ble solgt som.\n\nFeil på 4WD-systemer kan manifestere seg som feilmeldinger på dashbordet, manglende kraftoverføring til forakselen, vibrasjoner ved aktivering av 4WD eller overopphetning av overføringsakselen. Disse feilene er kostbare å utbedre — en transfercase-revisjon koster typisk 15 000–40 000 kr.\n\nDersom selger annonserte bilen som 'firehjulsdrift' og systemet ikke fungerer, er dette brudd på opplysningsplikten etter forbrukerkjøpsloven § 15. Du kan kreve utbedring, prisavslag eller heving avhengig av feilens omfang.", faqs: [{ q: "AWD-lampen lyser av og til. Er det en mangel?", a: "Ja, intermitterende AWD-feil er reklamasjonsgrunnlag. Dokumenter med bilde av dashbordet og be verksted lese feilkoder." }, { q: "Selger sier 4WD kun er ment for offroad og jeg bruker det feil. Holder det?", a: "Nei dersom bilen er solgt som AWD for normal vinterbruk. Selgers brukspåstand er irrelevant dersom systemet ikke fungerer som beskrevet." }, { q: "Kan jeg kreve prisavslag tilsvarende differansen mellom 4WD og 2WD-versjon?", a: "Ja, prisavslag kan beregnes som differansen mellom hva du betalte for en 4WD-bil og hva en tilsvarende 2WD-bil ville kostet." }]},
  { slug: "aircondition-defekt", title: "Defekt aircondition (AC) etter bilkjøp", lawRef: "KL § 17", cat: "bilkjop", desc: "AC som ikke kjøler er en mangel dersom selger ikke opplyste om dette.", bodyText: "Aircondition er standard utstyr på de fleste biler solgt etter 2000, og kjøper har rimelig grunn til å forvente at det fungerer med mindre selger eksplisitt opplyste om det motsatte. Defekt AC oppdages ofte sommeren etter kjøpet — og da er det gjerne gått lang tid siden kjøpet.\n\nVanlige årsaker til defekt AC: tom for kjølemiddel (R134a eller R1234yf) pga. lekkasje, defekt kompressor, defekt kondensator eller elektrisk feil. En AC-sjekk hos verksted koster typisk 500–1 500 kr og avklarer raskt hva som er galt. Lekkasjesøk kan i tillegg fastslå om lekkasjen er gammel eller ny.\n\nDersom lekkasjesøket viser en gammel lekkasje som selger burde ha kjent til, er dette reklamasjonsgrunnlag. Utbedring koster typisk 3 000–15 000 kr avhengig av hva som er defekt.", faqs: [{ q: "AC virket da jeg kjøpte bilen, men sluttet å kjøle etter 2 måneder. Er det selgers ansvar?", a: "Dersom lekkasjesøk viser at lekkasjen er gammel og ikke ny, ja. Be verksted dokumentere lekkasjens alder i rapporten." }, { q: "Selger sier han ikke brukte AC og visste ikke om problemet. Fritar det ham?", a: "Nei. Selger er ansvarlig for skjulte mangler uavhengig av kunnskap, forutsatt at feilen forelå ved kjøpet." }, { q: "AC-kompressoren er ødelagt og koster 12 000 kr. Er det nok til å kreve heving?", a: "Alene er det sannsynligvis ikke nok til heving — krav om vesentlig mangel stiller høye krav. Prisavslag er mer realistisk for AC-feil isolert sett." }]},
  { slug: "bremser-defekte", title: "Defekte bremser oppdaget etter bilkjøp", lawRef: "KL § 17", cat: "bilkjop", desc: "Defekte bremser er sikkerhetskritisk mangel med reklamasjonsrett.", bodyText: "Bremser er bilens viktigste sikkerhetssystem. Defekte bremser — enten det er tynnslitte skiver og klosser, defekte bremseslanger, dårlig bremsevæske eller bremsesvikt — er en alvorlig mangel som gjør bilen farlig å kjøre.\n\nBremseskiver og -klosser er slitedeler, men de skal ha rimelig gjenværende levetid ved salg. En bil solgt uten opplysning om at bremsene er nær slutt, der klossene ryker etter få tusen kilometer, er et brudd på opplysningsplikten. Bremseslanger og hovedbremsesylinder er ikke slitedeler og skal vare bilens levetid.\n\nFå en sikkerhetssjekk hos verksted som dokumenterer bremsenes tilstand. En rapport som viser tynnslitt materiale med kort gjenværende levetid er godt grunnlag for reklamasjon.", faqs: [{ q: "Bremsene gnir kraftig. Er det en mangel eller normal slitasje?", a: "Kraftig gnissing indikerer at klossene er gjennomslitt ned til metall. Dersom dette skjedde etter få km er det klar indikasjon på at klossene var nær slutt ved kjøpet." }, { q: "Selger sier han nylig skiftet bremser. Kan han bevise det?", a: "Krev faktura fra verksted med dato og km-stand. Kan han ikke dokumentere dette, er påstanden uten bevisverdi." }, { q: "Kan jeg kreve heving på grunn av defekte bremser?", a: "Defekte bremser som sikkerhetskritisk feil kan kvalifisere til heving dersom de gjør bilen ubrukelig eller farlig. Isolerte klosskift kvalifiserer normalt til prisavslag." }]},
  { slug: "dekkslitasje-skjev", title: "Skjev dekkslitasje og feil på understell", lawRef: "KL § 17", cat: "bilkjop", desc: "Unormal dekkslitasje avslører ofte skjulte feil på understell eller hjulgeometri.", bodyText: "Skjev eller unormal dekkslitasje er et symptom, ikke bare et estetisk problem. Ensidig slitasje på innsiden eller utsiden av dekket indikerer feil hjulstilling (camber/toe), slitte bærekuler, defekte støtdempere eller skjev ramme etter kollisjon. Dette er feil som forelå ved kjøpet dersom dekket allerede hadde unormal slitemønster.\n\nEt verksted kan ved hjulstillingskontroll avdekke om hjulgeometrien er innenfor produsentens toleranser. Slitte bærekuler og støtdempere kan diagnostiseres ved en enkel understellssjekk. Kost for hjulstillingskontroll er typisk 800–1 500 kr.\n\nDersom understellsfeilene er årsaken til den unormale slitasjen, kan du kreve dekket kostnadene for nye dekk, hjulstilling og understellsreparasjon samlet.", faqs: [{ q: "Dekket er slitt på innsiden etter 5 000 km. Er det selgers problem?", a: "Ja, dersom årsaken er feil camber eller slitte bærekuler som forelå ved kjøpet. Krev understellssjekk og hjulstillingskontroll." }, { q: "Selger sier det er mitt ansvar å sjekke dekk og understell ved kjøpet. Stemmer det?", a: "Kjøper har en viss undersøkelsesplikt, men selger plikter å opplyse om kjente feil. Selger kan ikke gjemme seg bak kjøpers manglende undersøkelse for feil han kjente til." }, { q: "Kan jeg kreve at selger betaler for 4 nye dekk?", a: "Du kan kreve nye dekk dersom de måtte byttes pga. unormal slitasje forårsaket av understellsfeil selger er ansvarlig for. Dokumenter med bilder og verkstedrapport." }]},
  { slug: "heving-privat-kjop", title: "Heve bilkjøp fra privatperson", lawRef: "KL § 39", cat: "bilkjop", desc: "Heving av privat bilkjøp krever vesentlig mangel — her er terskelen høyere enn ved forhandlerkjøp.", bodyText: "Heving av kjøp fra privatperson reguleres av kjøpsloven, ikke forbrukerkjøpsloven. Terskelen er høyere — mangelen må være 'vesentlig' for at du kan heve. Vesentlighetsvurderingen tar hensyn til feilens art, kostnad sett opp mot kjøpesummen, om bilen er brukbar og om selger visste om feilen.\n\nTypiske feil som oppfyller vesentlighetskravet ved privatkjøp: motorhavari, girkasse-havari, rammeknekk, gjennomgående rust i bærende deler, kilometerfusk og skjulte vannskader. Feil som normalt ikke oppfyller kravet alene: slitte bremser, defekt AC, enkle elektriske feil.\n\nVed privatkjøp er 'som den er'-forbehold vanlig og lovlig — men det fritar ikke selger fra feil han visste om og ikke opplyste om, feil som er vesentlig dårligere enn kjøpers rimelige forventning, og feil selger garanterte ikke eksisterte.", faqs: [{ q: "Bilen hadde 'selges som den er' i annonsen. Kan jeg likevel heve?", a: "Ja, dersom feilen er vesentlig og selger kjente til den, eller feilen gjør bilen vesentlig dårligere enn kjøper hadde rimelig grunn til å forvente." }, { q: "Selger er privatperson og sier han ikke har penger til å refundere. Hva gjør jeg?", a: "Du kan bringe saken inn for Forbrukertvistutvalget (gratis) eller tingretten. En dom gir deg grunnlag for namsmannen å inndrive kravet." }, { q: "Hva er forskjellen på heving og prisavslag?", a: "Ved heving leverer du bilen tilbake og får kjøpesummen refundert (minus nyttefradrag). Prisavslag beholder du bilen men får tilbake deler av prisen. Velg heving ved alvorlige feil." }]},
  { slug: "skade-ved-levering", title: "Bil skadet ved levering — hva kan du kreve?", lawRef: "KL § 14", cat: "bilkjop", desc: "Skader oppdaget ved levering må reklameres umiddelbart for å bevare retten.", bodyText: "Dersom bilen har synlige skader ved levering som ikke ble opplyst om i annonsen eller ved visning, skal du reklamere umiddelbart. Skader oppdaget etter levering er vanskeligere å bevise at ikke oppsto under din bruk, med mindre du har dokumentasjon.\n\nVed levering bør du alltid gå grundig gjennom bilen — sjekk lakken i godt lys, kontroller alle hjørner, se under bilen og test all elektronikk. Ta bilder av alt du ser, med tidsstempel. Dersom selger er til stede, noter eventuelle påpekte feil skriftlig og få selger til å signere.\n\nOm du oppdager skader etter levering som åpenbart ikke kan ha oppstått under din korte bruk (f.eks. rust under maling, gammel ripe under panseret), har du fortsatt krav — men dokumentasjonen er mer krevende.", faqs: [{ q: "Jeg oppdaget en stor bulk under panseret etter levering. Kan jeg reklamere?", a: "Ja, dersom du kan sannsynliggjøre at bulken er gammel og ikke oppsto under din bruk. Bilder med tidsstempel og vitner styrker saken din." }, { q: "Selger nekter å skrive under på skadelisten ved levering. Hva gjør jeg?", a: "Ta bilder av alt og send en skriftlig e-post til selger samme dag med beskrivelse av skadene. Dette dokumenterer at reklamasjonen ble fremsatt umiddelbart." }, { q: "Kan jeg nekte å hente bilen hvis den er skadet?", a: "Ja, du kan nekte å overta bilen dersom den ikke er i den stand som ble avtalt. Be selger utbedre skadene før overlevering eller krev prisavslag." }]},
  { slug: "finansiering-bil-problemer", title: "Problemer med billån og finansiering ved skjult mangel", lawRef: "FKL § 38", cat: "bilkjop", desc: "Ved heving av finansiert bilkjøp har du rettigheter mot både selger og finansieringsselskap.", bodyText: "Mange bilkjøp finansieres gjennom lån fra bank eller forhandlerens finansieringsselskap. Dersom du hever kjøpet på grunn av mangel, påvirker dette også låneavtalen — men reglene kan være kompliserte.\n\nVed finansiering gjennom forhandlerens eget finansieringsselskap (linked credit) gir forbrukerkjøpsloven § 38 deg rettigheter mot finansieringsselskapet direkte. Du kan holde tilbake betalinger mens heving behandles, og finansieringsselskapet plikter å tilbakebetale innbetalte avdrag ved heving.\n\nVed eksternt billån er situasjonen mer komplisert — du skylder fortsatt banken lånet uavhengig av bilens tilstand. Sørg for å heving-kravet mot selger blir behandlet raskt, og informer banken skriftlig om situasjonen.", faqs: [{ q: "Kan jeg slutte å betale billånet mens hevingssaken pågår?", a: "Kun dersom finansieringen er 'linked credit' gjennom forhandleren. Ved eksternt banklån bør du fortsette å betale for å unngå betalingsanmerkning." }, { q: "Forhandleren er konkurs. Kan jeg kreve refusjon fra finansieringsselskapet?", a: "Ja, ved linked credit har du krav mot finansieringsselskapet direkte etter forbrukerkjøpsloven § 38 selv om forhandleren er konkurs." }, { q: "Hva skjer med rentene jeg har betalt hvis jeg hever?", a: "Du kan kreve tilbakebetalt alle innbetalte avdrag og renter som tilsvarer bilens bruksverdi du ikke har hatt nytte av. Dokumenter alle innbetalinger." }]},
  { slug: "garanti-utlopt-feil", title: "Feil oppdaget rett etter garantiutløp på bil", lawRef: "FKL § 27", cat: "bilkjop", desc: "Garantiutløp fritar ikke selger fra reklamasjonsansvar etter forbrukerkjøpsloven.", bodyText: "Det er svært vanlig at bilforhandlere avviser reklamasjoner med henvisning til utløpt garanti. Dette er feil jus. Garanti og lovfestet reklamasjonsrett er to helt separate rettigheter — garantien er en frivillig tilleggsrettighet fra selger, mens reklamasjonsretten er lovfestet og kan ikke fraskrives.\n\nForbrukerkjøpsloven gir deg 5 års reklamasjonsrett fra kjøpsdatoen uavhengig av garantiens lengde. En feil som oppstår i år 3 etter kjøpet kan fortsatt reklameres selv om garantien løp ut etter 2 år — forutsatt at du kan sannsynliggjøre at feilen skyldtes forhold som forelå ved kjøpet.\n\nDersom forhandleren avviser reklamasjonen med 'garantien er utløpt', send skriftlig reklamasjon med eksplisitt henvisning til forbrukerkjøpsloven § 27. Dersom forhandleren fortsatt avviser, ta saken til Forbrukerrådet eller Forbrukertvistutvalget.", faqs: [{ q: "Garantien gikk ut for 6 måneder siden og motoren har nå havarert. Har jeg krav?", a: "Potensielt ja. Du må sannsynliggjøre at motorhavariet skyldes en feil som forelå ved kjøpet — service-historikk og verkstedrapport er avgjørende." }, { q: "Forhandleren tilbyr å dekke 50% av reparasjonen som 'goodwill'. Bør jeg akseptere?", a: "Ikke uten forbehold. Aksepter kun som fullt og endelig oppgjør dersom du er fornøyd. Ellers aksepter og reserver retten til å kreve resten." }, { q: "Har jeg samme rettigheter ved kjøp av ny bil som brukt?", a: "Ja, forbrukerkjøpsloven gjelder for både nye og brukte biler kjøpt fra næringsdrivende. Reklamasjonsfristen er alltid 5 år." }]},
  { slug: "nyttekjoretoy-feil", title: "Feil på varebil eller nyttekjøretøy etter kjøp", lawRef: "KL § 17", cat: "bilkjop", desc: "Nyttekjøretøy har samme reklamasjonsrett som personbiler ved kjøp fra forhandler.", bodyText: "Varebiler, campingbiler og andre nyttekjøretøy er ofte dyrere å reparere enn personbiler, og feil kan ha direkte konsekvenser for næringsdrift. Reklamasjonsreglene er de samme som for personbiler — forbrukerkjøpsloven ved kjøp fra næringsdrivende, kjøpsloven ved privatkjøp.\n\nFor næringsdrivende som kjøper varebil gjelder kjøpsloven uavhengig av om selger er næringsdrivende. Terskelen for heving er høyere enn for forbrukere, men retten til utbedring og prisavslag er den samme.\n\nVed feil som medfører driftstap — varebil som ikke kan brukes i jobben — kan du i tillegg til utbedring kreve erstatning for dokumentert driftstap etter kjøpslovens erstatningsregler.", faqs: [{ q: "Varebilen er mitt arbeidsverktøy og er inne til reparasjon. Kan jeg kreve leiebil?", a: "Du kan kreve dekket rimelige kostnader til alternativt transportmiddel som følge av mangelen, forutsatt at disse er dokumentert og rimelige sett opp mot feilens art." }, { q: "Jeg er næringsdrivende. Gjelder forbrukerkjøpsloven for meg?", a: "Nei, næringsdrivende som kjøper til bruk i virksomheten faller utenfor forbrukerkjøpsloven. Kjøpsloven gjelder, som gir noe svakere rettigheter." }, { q: "Campingbilen har feil på boligdelen. Hvem er ansvarlig — bilforhandler eller campingprodusent?", a: "Reklamasjonen rettes til selger (forhandleren) uavhengig av hvem som produserte hvilken del. Selger kan eventuelt regresskrve produsenten." }]},

  // BILKJØP (juridisk prosess og spesialtilfeller)
  { slug: "reklamasjon-frister-bil", title: "Reklamasjonsfrister ved bilkjøp — alt du må vite", lawRef: "FKL § 27 / KL § 32", cat: "bilkjop", desc: "Reklamasjonsfristen er 2 år ved privatkjøp og 5 år ved forhandlerkjøp — uavhengig av garanti.", bodyText: "Reklamasjonsfristen er en av de mest misforståtte rettighetene ved bilkjøp. Mange tror garantien er det eneste vernet — men den lovfestede reklamasjonsretten er helt separat og gir deg rett til å klage på feil i opptil 5 år etter kjøpet ved forhandlerkjøp.\n\nVed privatkjøp er reklamasjonsfristen 2 år fra levering. Ved forhandlerkjøp er den 5 år. I tillegg må du reklamere innen 'rimelig tid' etter at du oppdaget feilen — normalt 2–3 måneder. Venter du for lenge etter å ha oppdaget feilen, kan du miste retten selv om du er innenfor den absolutte fristen.\n\nInnen de første 12 månedene etter kjøpet (ved forhandlerkjøp) presumeres feilen å ha eksistert ved overlevering. Etter 12 måneder må du sannsynliggjøre dette selv — verkstedrapport som beskriver feilens sannsynlige alder er da avgjørende.", faqs: [{ q: "Jeg oppdaget feilen for 4 måneder siden men har ikke reklamert ennå. Er det for sent?", a: "Det kan være det. Reklamér umiddelbart. 'Rimelig tid' tolkes strengt — normalt 2–3 måneder fra oppdagelse. Lengre ventetid risikerer tap av reklamasjonsretten." }, { q: "Garantien er 1 år men reklamasjonsfristen er 5 år — hva betyr det i praksis?", a: "I garantiperioden hjelper forhandleren uten diskusjon om bevis. Etter garantiperioden må du sannsynliggjøre at feilen skyldes forhold ved kjøpet, men retten eksisterer fortsatt." }, { q: "Selger sier jeg burde ha oppdaget feilen tidligere. Har han rett?", a: "Kjøper plikter å undersøke bilen innen rimelig tid etter levering. Åpenbare feil du burde sett ved en normal gjennomgang kan du ikke reklamere på måneder senere." }]},
  { slug: "prisavslag-beregning", title: "Slik beregnes prisavslag ved bilmangel", lawRef: "FKL § 31 / KL § 38", cat: "bilkjop", desc: "Prisavslag skal gjenspeile kostnad for å utbedre mangelen — her er reglene.", bodyText: "Prisavslag er det vanligste kravet ved bilreklamasjon — du beholder bilen men får tilbake deler av kjøpesummen tilsvarende feilens verdi. Prisavslagets størrelse fastsettes normalt som kostnad for å utbedre mangelen hos et autorisert verksted.\n\nFor å dokumentere prisavslaget bør du innhente skriftlig pristilbud eller faktura fra verksted for utbedring av mangelen. Selger kan ikke tvinge deg til å bruke et bestemt verksted for pristilbudet — du kan innhente tilbud fra et uavhengig verksted.\n\nDersom selger er uenig i prisavslagets størrelse, kan saken bringes inn for Forbrukertvistutvalget som fastsetter beløpet basert på innsendt dokumentasjon. Prosessen er gratis for forbrukere.", faqs: [{ q: "Selger tilbyr 2 000 kr i prisavslag men verkstedet sier reparasjonen koster 15 000 kr. Hva gjør jeg?", a: "Aksepter ikke et utilstrekkelig tilbud. Send verkstedets pristilbud til selger og krev prisavslag tilsvarende faktisk reparasjonskostnad." }, { q: "Kan jeg kreve prisavslag og beholde bilen uten å reparere den?", a: "Ja, du kan motta prisavslag og la være å reparere mangelen. Pengene tilhører deg uavhengig av hva du gjør med bilen." }, { q: "Selger vil gi meg rabatt på neste service i stedet for prisavslag. Er det lovlig?", a: "Kun dersom du aksepterer det frivillig. Du har rett til kontant prisavslag og kan avslå tilbud om vouchers eller tjenester i stedet." }]},
  { slug: "forbrukertvist-bil", title: "Klage til Forbrukertvistutvalget ved bilkjøp", lawRef: "FKL § 32", cat: "bilkjop", desc: "Forbrukertvistutvalget behandler klager gratis og gir bindende avgjørelser.", bodyText: "Dersom du og selger ikke kommer til enighet om en reklamasjon, kan du klage til Forbrukertvistutvalget (FTU). FTU behandler forbrukerklager mot næringsdrivende gratis og gir bindende avgjørelser som kan tvangsfullbyrdes som en dom.\n\nFør du kan klage til FTU må saken ha vært behandlet av Forbrukerrådet. Forbrukerrådet forsøker mekling mellom partene — lykkes ikke det, kan du klage videre til FTU. Hele prosessen er gratis.\n\nFTU behandler saker skriftlig og baserer seg på dokumentasjon du sender inn. Sørg for å ha verkstedrapporter, korrespondanse med selger, kjøpskontrakt og kvitteringer klare. Saksbehandlingstiden er typisk 6–12 måneder.", faqs: [{ q: "Kan jeg klage til FTU selv om selger er et lite enkeltmannsforetak?", a: "Ja, FTU behandler klager mot alle næringsdrivende selgere, uavhengig av selskapets størrelse." }, { q: "Selger har ikke svart på mine reklamasjoner. Kan jeg gå rett til FTU?", a: "Ja, manglende svar fra selger er tilstrekkelig til å konstatere at forhandlinger har brutt sammen. Kontakt Forbrukerrådet for veiledning om neste steg." }, { q: "Hva skjer hvis selger ikke etterkommer FTUs avgjørelse?", a: "FTUs avgjørelse er bindende og kan tvangsfullbyrdes gjennom namsmannen uten ny rettsak, på samme måte som en dom." }]},
  { slug: "bil-totalskade-kjopt", title: "Kjøpt bil som viser seg å være totalskade", lawRef: "KL § 18", cat: "bilkjop", desc: "Skjult totalskadehistorikk er svik og gir rett til heving og erstatning.", bodyText: "En bil som er registrert som totalskade av forsikringsselskapet og deretter reparert og solgt videre uten opplysning om historikken, er et alvorlig brudd på opplysningsplikten. Totalskadede biler har redusert verdi og kan ha sikkerhetskritiske skjulte skader selv etter reparasjon.\n\nDu kan sjekke om en bil har vært totalskade via Autovid, NAF-historikksjekk eller ved å be forsikringsselskapet om skadehistorikk på registreringsnummeret. Carfax og lignende tjenester kan gi internasjonal historikk for importerte biler.\n\nDersom du oppdager at bilen har skjult totalskadehistorikk, har du rett til heving uavhengig av bilens nåværende tilstand. Totalskadehistorikk som ikke ble opplyst om er svik etter kjøpsloven § 18.", faqs: [{ q: "Bilen kjørte fint men viste seg å ha vært totalskade. Kan jeg heve?", a: "Ja. Totalskadehistorikk som ikke ble opplyst om er svik uavhengig av bilens nåværende kjørbarhet. Historikken påvirker verdien og retten til heving." }, { q: "Selger hevder han ikke visste om totalskadehistorikken. Fritar det ham?", a: "Ikke nødvendigvis. En forhandler forventes å kjenne bilens historikk. Privatpersoner kan fritas dersom uvitenheten er troverdig, men bevisbyrden ligger hos selger." }, { q: "Har jeg krav på erstatning utover heving ved skjult totalskade?", a: "Ja, dokumenterte tap som følge av å ha eid en bil med skjult totalskade — f.eks. lavere salgsverdi dersom du solgte den videre — kan kreves erstattet." }]},
  { slug: "importert-bil-feil", title: "Problemer med importert bruktbil", lawRef: "KL § 17", cat: "bilkjop", desc: "Importerte biler har samme reklamasjonsrett, men dokumentasjon kan være vanskeligere å innhente.", bodyText: "Importerte bruktbiler — særlig fra Tyskland, Sverige og Danmark — er populære i Norge på grunn av lavere priser. Reklamasjonsreglene er de samme som for norsksolgte biler, men det kan være praktisk vanskeligere å følge opp reklamasjonen.\n\nVanlige problemer med importerte biler: manglende norsk service-historikk, utenlandske dokumenter som er vanskelige å verifisere, kjøretøy tilpasset andre klimasoner (rustbeskyttelse, vinterutstyr) og biler med manipulert historikk som er vanskeligere å avsløre på norske databaser.\n\nDersom du kjøper fra en norsk importør/forhandler, gjelder forbrukerkjøpsloven fullt ut. Kjøper du direkte fra utlandet, kan internasjonale kjøpsregler gjelde og rettshåndhevelse kan være krevende.", faqs: [{ q: "Bilen er importert fra Tyskland og har rust som ikke er synlig i tyske databaser. Hva gjør jeg?", a: "Reklamér til norsk selger dersom du kjøpte via norsk forhandler. Norsk selger er ansvarlig uavhengig av opprinnelsesland." }, { q: "Kjøpte direkte fra tysk privatperson. Har jeg reklamasjonsrett?", a: "Teknisk sett gjelder tysk kjøpslovgivning og EU-regler. Det er i praksis svært vanskelig å håndheve slike krav. Direkte utenlandskjøp er høyrisiko." }, { q: "Kilometerstanden er i miles fra UK-bil. Kan det manipuleres?", a: "Ja, omregning mellom miles og km gir mulighet for manipulasjon. Sjekk alltid britisk kjøretøyshistorikk via DVLA i tillegg til norske databaser." }]},
  { slug: "bil-solgt-med-feil-opplysninger", title: "Bil solgt med feilaktige opplysninger i annonse", lawRef: "KL § 18", cat: "bilkjop", desc: "Feilaktige opplysninger i annonse er brudd på opplysningsplikten og gir hevingsrett.", bodyText: "Annonsen er en del av avtalen. Dersom selger i annonsen oppgav feilaktige opplysninger om bilens tilstand, utstyr, service-historikk eller kilometerstand, er dette brudd på opplysningsplikten etter kjøpsloven § 18 — uavhengig av hva som ble sagt muntlig ved visning.\n\nTypiske feilaktige annonseropplysninger: 'full servicehistorikk' uten dokumentasjon, 'ingen rust' på bil med rust, feil årsmodell, oppgitt utstyr som mangler og 'ett eiers bil' på bil med flere eiere. Ta skjermbilde av annonsen ved kjøpet — annonseplattformer sletter annonser etter salg.\n\nFeilaktige opplysninger gir deg rett til prisavslag eller heving avhengig av alvorlighetsgrad. Dersom opplysningene var bevisst feilaktige, er det svik med rett til erstatning i tillegg.", faqs: [{ q: "Annonsen sa 'full servicehistorikk' men selger kan ikke fremlegge dette. Hva gjør jeg?", a: "Krev dokumentasjon. Kan selger ikke fremlegge servicehistorikk som ble lovet, er det brudd på avtalen og grunnlag for prisavslag." }, { q: "Jeg tok ikke skjermbilde av annonsen og den er slettet. Kan jeg bevise innholdet?", a: "Prøv Wayback Machine (web.archive.org) eller kontakt annonseplattformen. Finn.no lagrer annonseinformasjon og kan fremlegge den ved tvist." }, { q: "Selger sier annonsen var en skrivefeil. Er det et gyldig forsvar?", a: "Nei som regel. Selger har ansvar for nøyaktigheten av sin annonse. Vesentlige 'skrivefeil' om sentrale egenskaper er selgers risiko." }]},
  { slug: "vannskade-bil", title: "Skjult vannskade på bruktbil", lawRef: "KL § 19", cat: "bilkjop", desc: "Vannskadede biler har alvorlige skjulte problemer og klar hevingsrett.", bodyText: "Biler som har stått i flom eller vann har potensielt ødelagt elektronikk, korroderte kontakter, skjemmede interiørkomponenter og muggvekst i isolasjon og trekk. Disse skadene er svært kostbare å utbedre og kan gi elektriske problemer i årevis etter at bilen tilsynelatende er reparert.\n\nTegn på skjult vannskade: mugglukt i kupéen, vannstrek på dørpaneler eller bagasjerommet, korroderte elektriske kontakter under setene, rustede skruer og festepunkter i gulvet, og sediment eller kalkavleiringer i teppebelegget.\n\nEn bil med uopplyst vannskadehistorikk er svik etter kjøpsloven § 18. Sjekk forsikringshistorikk via Autovid og be om skadehistorikk — vannskader registreres normalt som totalskade hos forsikringsselskapet.", faqs: [{ q: "Bilen lukter mugg men selger nekter for vannskade. Hva gjør jeg?", a: "Krev karosseriinspeksjon og elektrisk gjennomgang. Mugglukt kombinert med korroderte kontakter er sterk indikasjon på vannskade som selger har vanskelig for å bortforklare." }, { q: "Forsikringshistorikken viser ingen vannskade. Er bilen trygg?", a: "Ikke nødvendigvis. Ikke alle vannskader meldes til forsikring — særlig på eldre biler. Fysisk inspeksjon er mer pålitelig enn historikkrapporter alene." }, { q: "Kan jeg kreve erstatning for elektriske problemer som dukker opp måneder etter kjøpet?", a: "Ja, dersom du kan sannsynliggjøre at problemene stammer fra vannskaden som forelå ved kjøpet. Dokumenter alle feil med tidspunkt og verkstedrapporter." }]},
  { slug: "odometer-manipulert", title: "Manipulert kilometerstand — slik avslører du det", lawRef: "KL § 18", cat: "bilkjop", desc: "Manipulert kilometerstand er svik og gir deg rett til heving og erstatning.", bodyText: "Kilometerstandmanipulering er dessverre utbredt i bruktbilmarkedet. En bil med lavere oppgitt km-stand enn reell stand er mer slitt enn kjøper forventer, har lavere restverdi og kan ha overskredet vedlikeholdsintervaller for kritiske komponenter.\n\nSlik avslører du manipulert km-stand: sammenlign med service-historikk fra autoriserte verksteder, sjekk EU-kontroll-historikk, se på slitasje på ratt, girknopp og pedaler opp mot oppgitt km-stand, be om Autovid-rapport og sjekk odometerhistorikk der det er tilgjengelig.\n\nKilometerstandmanipulering er svik etter kjøpsloven § 18 og gir deg rett til heving uavhengig av vesentlighetskravet, samt erstatning for dokumenterte tap som følge av manipuleringen.", faqs: [{ q: "Service-historikken viser 180 000 km men selger oppga 120 000 km. Er det nok bevis?", a: "Ja, dette er sterkt bevis for kilometerstandmanipulering. Dokumenter avviket nøye og reklamér umiddelbart med krav om heving." }, { q: "Selger kjøpte bilen med lav km-stand og videresolgte den i god tro. Er han ansvarlig?", a: "Ja, selger er ansvarlig for feilaktige opplysninger uavhengig av om han selv ble lurt. Han må selv kreve regress fra sin selger." }, { q: "Kan jeg anmelde forholdet til politiet?", a: "Ja, bevisst kilometerstandmanipulering er bedrageri. Anmeldelse kan støtte den sivile saken, men straffesak og sivil reklamasjonssak er separate prosesser." }]},
  { slug: "bilkjop-mindreaarig", title: "Bilkjøp på vegne av mindreårig eller umyndiggjort person", lawRef: "KL § 2", cat: "bilkjop", desc: "Mindreårige kan ikke inngå bindende kjøpsavtaler uten verges samtykke.", bodyText: "Mindreårige under 18 år er ikke rettslig handlekraftige og kan ikke inngå bindende kjøpsavtaler uten vergens samtykke. Dersom en mindreårig kjøper en bil uten vergens godkjenning, kan avtalen kjennes ugyldig etter vergemålsloven.\n\nFor selger medfører salg til mindreårig risiko for at kjøpet omgjøres. For kjøper (eller vergen) er dette primært aktuelt dersom bilen viser seg å ha mangler og selger bestrider reklamasjonsretten.\n\nI praksis er dette mest relevant der unge kjøpere blir utnyttet av useriøse selgere. Reklamasjonsreglene gjelder fullt ut dersom den mindreåriges verge ratifiserer kjøpet — noe som skjer automatisk dersom vergen betaler kjøpesummen eller aksepterer leveringen.", faqs: [{ q: "Sønnen min på 17 år kjøpte bil uten mitt samtykke. Kan vi omgjøre kjøpet?", a: "Ja, kjøpet kan erklæres ugyldig etter vergemålsloven dersom du ikke ratifiserer det. Gi beskjed til selger skriftlig så raskt som mulig." }, { q: "Jeg er 17 og kjøpte bil — selger avviser reklamasjon fordi jeg er mindreårig. Er det lovlig?", a: "Nei, dersom vergen har ratifisert kjøpet gjelder reklamasjonsretten fullt ut. Selger kan ikke avvise reklamasjon på grunn av kjøpers alder." }, { q: "Kan mindreårige kjøpe bil via foreldrenes navn og likevel bruke reklamasjonsretten?", a: "Ja, dersom forelder er formell kjøper gjelder alle reklamasjonsregler normalt. Hvem som faktisk bruker bilen er irrelevant for reklamasjonsretten." }]},
  { slug: "bileiers-ansvar-etter-salg", title: "Selgers ansvar etter salg av bil med skjulte feil", lawRef: "KL § 20", cat: "bilkjop", desc: "Selger har ansvar for skjulte feil i inntil 2–5 år etter salget.", bodyText: "Mange selgere tror at ansvaret opphører ved overleveringen — dette er feil. Selger har lovfestet ansvar for feil som forelå ved salget i opptil 2 år (privatkjøp) eller 5 år (forhandlerkjøp) etter leveringen, forutsatt at kjøper reklamerer innen rimelig tid etter å ha oppdaget feilen.\n\nSelger kan forsøke å begrense ansvaret gjennom 'som den er'-forbehold eller ansvarsfraskrivelser i kjøpekontrakten. Slike forbehold er gyldige ved privatkjøp men har begrenset virkning ved alvorlige feil — de fritar ikke selger for feil han kjente til og ikke opplyste om.\n\nVed forhandlerkjøp kan ikke selger fraskrive seg reklamasjonsretten overfor forbrukere. Klausuler i kjøpekontrakt som begrenser forbrukerkjøpslovens rettigheter er ugyldige.", faqs: [{ q: "Kjøpekontrakten sier 'ingen reklamasjon'. Er den gyldig?", a: "Ved forhandlerkjøp: nei, slike klausuler er ugyldige etter forbrukerkjøpsloven. Ved privatkjøp: delvis, men fritar ikke for kjente skjulte feil." }, { q: "Selger har solgt boligen sin og er ikke lenger kontaktbar. Hva gjør jeg?", a: "Forsøk å nå selger via ny adresse fra folkeregisteret. Alternativt kan du stevne selger for tingretten. Kravet foreldes ikke selv om selger er vanskelig å nå." }, { q: "Kan jeg kreve at selger stiller garanti for sitt ansvar ved kjøpet?", a: "Du kan be om det, men selger er ikke forpliktet til å stille garanti. Lovens regler om reklamasjonsfrist gir deg tilstrekkelig vern uten særskilt garanti." }]},
  { slug: "bil-ikke-levert", title: "Selger leverer ikke bilen etter kjøpet", lawRef: "KL § 21", cat: "bilkjop", desc: "Dersom selger ikke leverer bilen kan du kreve oppfyllelse, heving og erstatning.", bodyText: "Dersom selger ikke leverer bilen til avtalt tid og sted, er dette kontraktsbrudd. Du har krav på at selger oppfyller avtalen — leverer bilen som avtalt. Dersom levering ikke skjer innen en rimelig tilleggsfrist du setter, kan du heve kjøpet og kreve tilbake eventuell betalt forskudd.\n\nBetal aldri full kjøpesum før bilen er levert og kontrollert. Dersom du har betalt forskudd og selger ikke leverer, er selger i betalingsansvar for tilbakebetaling pluss erstatning for dokumenterte tap.\n\nVær spesielt forsiktig med selgere som ber om forskuddsbetaling og utsetter levering med ulike unnskyldninger — dette er et klassisk mønster for bedrageri. Politianmeldelse og sivil sak kan kjøres parallelt.", faqs: [{ q: "Selger ber om forskudd og vil levere bilen om 2 uker. Er det trygt?", a: "Sett klare betingelser skriftlig: eksakt leveringsdato, og betaling kun ved levering og kontroll. Unngå store forskudd til ukjente selgere." }, { q: "Jeg betalte forskudd og selger svarer ikke lenger. Hva gjør jeg?", a: "Anmeld forholdet til politiet som mulig bedrageri og kontakt banken umiddelbart for å forsøke å reversere betalingen. Tid er avgjørende." }, { q: "Kan jeg kreve erstatning for utgifter til leiebil mens jeg venter på levering?", a: "Ja, dokumenterte kostnader til alternativt transportmiddel som følge av forsinket levering kan kreves erstattet av selger." }]},
  { slug: "bruktbil-as-is", title: "Dine rettigheter ved 'som den er'-kjøp av bil", lawRef: "KL § 19", cat: "bilkjop", desc: "'Som den er'-forbehold begrenser ikke rettene dine ved skjulte vesentlige feil.", bodyText: "'Som den er' er det vanligste forbeholdet ved privat bilsalg og signaliserer at bilen selges uten garanti. Mange kjøpere tror dette fratar dem alle rettigheter — men slik er det ikke.\n\nKjøpsloven § 19 slår fast at selv ved 'som den er'-forbehold kan bilen ha mangel dersom: selger har gitt uriktige opplysninger om bilen, selger har holdt tilbake opplysninger som kjøper hadde grunn til å forvente å få, eller bilen er i vesentlig dårligere stand enn kjøper hadde grunn til å forvente.\n\nDette betyr at 'som den er' ikke hjelper selger dersom han visste om girkasse-havariet som skjedde to uker etter kjøpet, eller ikke opplyste om at bilen hadde gjennomgående rust. Forbeholdet senker bare terskelen noe — det fritar ikke fra ansvar for vesentlige feil.", faqs: [{ q: "Annonsen sa 'selges som den er, ingen klager'. Er det bindende?", a: "Det er gyldig som forbehold, men fritar ikke selger fra vesentlige skjulte feil han kjente til eller fra feil som gjør bilen vesentlig dårligere enn rimelig forventet." }, { q: "Hva er 'vesentlig dårligere enn rimelig forventet'?", a: "En skjønnsmessig vurdering basert på bilens pris, alder og fremstilling. En bil annonsert som 'kjørbar' med total motorhavari etter én uke er klart vesentlig dårligere." }, { q: "Kan selger skrive inn i kontrakten at 'som den er' fritar for alt ansvar?", a: "Nei, kjøpslovens § 19 er ufravikelig for forbrukerkjøp og kan ikke avtalefestes bort. Ved næringskjøp er det mer fleksibilitet." }]},
  { slug: "bil-prisavvik-annonsert", title: "Bilen koster mer enn annonsert pris", lawRef: "KL § 18", cat: "bilkjop", desc: "Selger er bundet av annonsert pris — avvik er kontraktsbrudd.", bodyText: "Annonsert pris er bindende tilbud fra selger. Dersom selger ved kjøpstidspunktet krever mer enn annonsert pris uten saklig begrunnelse, er dette brudd på avtalen. Du har rett til å kjøpe bilen til annonsert pris eller heve kjøpet og kreve tilbake eventuell betaling.\n\nVanlige scenarioer: selger øker prisen etter at du har bestemt deg, legger til gebyrer som ikke var nevnt (dokumentasjonsgebyr, leveringsgebyr), eller krever betaling for utstyr som var inkludert i annonsen.\n\nDokumenter annonsen — ta skjermbilde med dato og pris. Finn.no-annonser kan fremlegges som bevis ved tvist. Selger kan ikke ensidig endre prisen etter at kjøper har akseptert tilbudet.", faqs: [{ q: "Forhandleren legger til 'dokumentasjonsgebyr' på 3 000 kr. Er det lovlig?", a: "Kun dersom gebyret var tydelig opplyst i annonsen eller ved inngåelse av avtalen. Gebyrer som overrasker kjøper ved signering er tvilsomme og kan bestrides." }, { q: "Annonseprisen var uten avgifter. Kan selger legge til moms?", a: "Dersom selger er næringsdrivende og prisen ikke er inkl. moms, skal dette tydelig fremgå av annonsen. Skjult moms-tillegg er villedende markedsføring." }, { q: "Selger vil trekke seg fra salget etter at jeg aksepterte annonseprisen. Kan han det?", a: "Nei, akseptert anbud er bindende avtale. Du kan kreve levering til avtalt pris eller erstatning for prisforskjell ved kjøp av tilsvarende bil." }]},
  { slug: "bil-ulovlig-modifisert", title: "Bil med ulovlige modifikasjoner etter kjøp", lawRef: "KL § 17", cat: "bilkjop", desc: "Ulovlige modifikasjoner selger ikke opplyste om er mangel og kan gjøre bilen uforsikrbar.", bodyText: "Ulovlig modifiserte biler — senkede biler under tillatt minste bakkeklaring, feilmonterte lyskastere, ulovlig chip-tuning, modifisert eksosanlegg — kan miste EU-godkjenningen og i verste fall være uforsikrede ved ulykke.\n\nDersom selger ikke opplyste om modifikasjonene, er dette brudd på opplysningsplikten. Kjøper hadde grunn til å forvente en lovlig, EU-godkjent bil. Kostnadene for å tilbakeføre bilen til lovlig stand — ny EU-kontroll, fjerne modifikasjoner — er selgers ansvar.\n\nI alvorlige tilfeller der modifikasjonene gjør bilen uforsikrbar eller ikke godkjennbar, er heving aktuelt.", faqs: [{ q: "Bilen besto EU-kontroll med modifikasjonene. Er de da lovlige?", a: "Ikke nødvendigvis. EU-kontrollens omfang varierer, og noen modifikasjoner oppdages ikke. Sjekk spesifikt med Statens vegvesen om modifikasjonene er godkjente." }, { q: "Bilen har chip-tuning som øker effekten vesentlig. Er det ulovlig?", a: "Chip-tuning som overskrider fabrikantens spesifikasjoner er ikke EU-godkjent og kan ugyldiggjøre forsikringsdekning ved ulykke. Selger pliktet å opplyse om dette." }, { q: "Vil ulovlige modifikasjoner alltid gi reklamasjonsrett?", a: "Ja, dersom de ikke ble opplyst om. Selv om modifikasjonene ikke er farlige i seg selv, er bilen i avvikende stand fra det kjøper hadde grunn til å forvente." }]},

  // BILKJØP (4 nye noder)
  { slug: "rust-understell-bruktbil", title: "Alvorlig rust i understell på bruktbil", lawRef: "KL § 19", cat: "bilkjop", desc: "Gjennomgående rust i bærende konstruksjoner er vesentlig mangel som gir hevingsrett.", bodyText: "Rust i understellet er en av de mest alvorlige feilene en bruktbil kan ha. Bærende konstruksjoner som sviller, tverrbjelker og gulvplater er kritiske for bilens strukturelle integritet og kollisjonssikkerhet. En bil med gjennomgående rust i disse delene vil normalt ikke bestå EU-kontroll og er teknisk sett ulovlig å kjøre.\n\nRust i understell utvikler seg over år — det er aldri en plutselig feil. Dersom selger ikke opplyste om rustomfanget, eller aktivt skjulte det med understellsbehandling, er dette brudd på opplysningsplikten etter kjøpsloven § 19. En rustinspeksjon fra et godkjent karosserisenter vil normalt kunne anslå rustens alder og omfang.\n\nUtbedring av alvorlig understellsrust koster typisk 30 000–100 000 kr, og i mange tilfeller er bilen totalskade. Dersom utbedringskostnaden overstiger bilens verdi etter reparasjon, er heving det eneste reelle kravet.", faqs: [{ q: "Selger sa understellet var 'normalt for alderen'. Holder det?", a: "Nei, dersom rusten er så omfattende at bilen ikke kan EU-godkjennes. 'Normalt for alderen' er ikke en gyldig ansvarsfraskrivelse for sikkerhetskritisk rust." }, { q: "Kan jeg kreve heving selv om bilen var billig?", a: "Ja. Lav kjøpesum reduserer nyttefradraget ved heving, men fritar ikke selger fra ansvar for vesentlige mangler." }, { q: "Hva hvis selger har behandlet understellet rett før salg for å skjule rust?", a: "Dette er svik etter kjøpsloven § 18 og gir deg rett til heving samt erstatning for dokumenterte tap." }]},
  { slug: "feilkode-p0420-katalysator", title: "Feilkode P0420 og defekt katalysator", lawRef: "FKL § 16", cat: "bilkjop", desc: "Defekt katalysator kort tid etter kjøp er reklamasjonsgrunnlag — utbedring kan koste 10-30 000 kr.", bodyText: "Feilkode P0420 indikerer at katalysatoren ikke renser eksosen effektivt nok. Katalysatoren er ikke en slitedel i tradisjonell forstand — den skal i prinsippet vare bilens levetid med normalt vedlikehold. Dersom den svikter på en relativt ny bil eller en bil med lav kilometerstand, er dette reklamasjonsgrunnlag.\n\nEn ny katalysator koster typisk 5 000–20 000 kr for delen alene, pluss arbeidsutgifter. For premium-merker som BMW, Mercedes og Volvo kan prisen være vesentlig høyere. P0420-feil kan i noen tilfeller utløses av andre problemer — slitte tennplugger, injektorfeil eller lambda-sonde — men en grundig diagnose fra verksted vil avklare dette.\n\nDersom feilkoden var til stede ved kjøpet (noe som er vanlig å nullstille før salg), har selger bevisst holdt tilbake informasjon om kjent feil. Be verkstedet sjekke feilkodehistorikk i ECU — mange biler lagrer tidsstempel for første gang feilkoden oppsto.", faqs: [{ q: "Selger nullstilte feilkoden før salg. Kan jeg bevise det?", a: "Verksted kan ofte lese feilkodehistorikk fra bilens ECU. Dersom P0420 dukker opp igjen kort tid etter nullstilling er det sterk indikasjon på at feilen var kjent." }, { q: "Bilen besto EU-kontrollen. Kan jeg likevel reklamere på katalysatoren?", a: "Ja. EU-kontroll er ikke en garanti mot skjulte feil. Bilen kan bestå EU-kontroll og likevel ha en katalysator som er nær slutten." }, { q: "Kan jeg kreve prisavslag i stedet for reparasjon?", a: "Ja, du kan velge mellom utbedring og prisavslag tilsvarende reparasjonskostnaden. Prisavslag er ofte enklere å gjennomføre i praksis." }]},
  { slug: "bil-solgt-som-reparasjonsobjekt", title: "Rettigheter når bil selges som reparasjonsobjekt", lawRef: "KL § 19", cat: "bilkjop", desc: "Selv reparasjonsobjekter har opplysningsplikt — selger kan ikke skjule kjente feil.", bodyText: "Når en bil selges som 'reparasjonsobjekt' eller 'til deler/rep' signaliserer selger at bilen har vesentlige feil. Dette reduserer kjøpers forventninger og senker terskelen for hva selger er ansvarlig for — men det fritar ikke selger fra opplysningsplikten.\n\nSelger plikter fortsatt å opplyse om alle kjente feil, også på reparasjonsobjekter. Dersom selger vet at bilen har motorhavari, vannskade eller skjult rammeknekk og ikke opplyser om dette eksplisitt, er det brudd på kjøpsloven § 19 uavhengig av 'reparasjonsobjekt'-betegnelsen.\n\nDersom du har betalt en pris som reflekterer antatt reparerbart omfang, og viser seg at bilen har skjulte feil som gjør den langt dyrere å utbedre enn forutsatt, kan du kreve prisavslag tilsvarende differansen. Heving kan også være aktuelt dersom skjulte feil er vesentlige.", faqs: [{ q: "Selger sa 'selges som den er, ingen reklamasjon'. Gjelder det for reparasjonsobjekter?", a: "Delvis. 'Som den er'-forbehold begrenser ansvaret, men gjelder ikke feil selger kjente til og ikke opplyste om." }, { q: "Jeg kjøpte bilen for 5 000 kr som reparasjonsobjekt. Har det noen hensikt å reklamere?", a: "Ja, dersom selger holdt tilbake vesentlig informasjon. Du kan kreve prisavslag ned mot null eller heving med full refusjon." }, { q: "Hva er forskjellen på kjøp fra privatperson og forhandler for reparasjonsobjekter?", a: "Ved forhandlerkjøp gjelder forbrukerkjøpsloven med sterkere vernt. Forhandler kan ikke fraskrive seg reklamasjonsretten gjennom 'reparasjonsobjekt'-betegnelse." }]},
  { slug: "feil-omregistrering-avgift", title: "Problemer med omregistrering eller avgifter ved bilkjøp", lawRef: "KL § 18", cat: "bilkjop", desc: "Selger som ikke har ordnet omregistrering eller har uoppgjorte heftelser bryter avtalen.", bodyText: "Kjøp av bruktbil inkluderer normalt en forventning om at bilen kan omregistreres uten problemer. Dersom bilen har uoppgjort pant, skyldig årsavgift, manglende EU-kontroll eller andre heftelser som hindrer omregistrering, er dette et avvik fra avtalen.\n\nPant i bil er særlig problematisk — dersom selger har lån på bilen uten å ha innfridd det, kan kreditor i prinsippet ta bilen selv etter salget. Sjekk alltid panteregisteret på Brønnøysundregistrene og årsavgiftstatus på Statens vegvesen sine nettsider før kjøpet.\n\nDersom problemet allerede er oppdaget etter kjøpet, reklamér skriftlig og gi selger en rimelig frist til å løse heftelsene. Dersom selger ikke løser dette innen fristen, kan du holde tilbake betaling (hvis ikke betalt) eller kreve heving.", faqs: [{ q: "Bilen har pant jeg ikke visste om. Hva gjør jeg?", a: "Reklamér til selger umiddelbart og krev at pantet innfris. Selger er ansvarlig for å levere bilen heftelsesfri med mindre annet eksplisitt ble avtalt." }, { q: "Kan jeg nekte å betale resten av kjøpesummen til pant er slettet?", a: "Ja, du har tilbakeholdsrett inntil selger oppfyller sin del av avtalen og leverer heftelsesfri bil." }, { q: "Skyldig årsavgift ble ikke betalt av selger. Hvem er ansvarlig?", a: "Selger er ansvarlig for avgifter påløpt i hans eiertid. Krev dokumentasjon på at avgiften er betalt, eller trekk beløpet fra kjøpesummen." }]},

  // FLYREISER — URL: /flyreiser/[slug]
  { slug: "sas-fly-kansellert", title: "Kansellert SAS-fly — slik krever du kompensasjon", lawRef: "EU 261/2004 art. 5", cat: "flyreiser", desc: "SAS er bundet av EU 261/2004 og plikter kompensasjon ved kansellering.", bodyText: "SAS Scandinavian Airlines er et av Norges mest brukte flyselskaper og er fullt ut bundet av EU 261/2004 for alle avganger fra EU/EØS-land og for avganger med EU/EØS-baseert flyselskap. SAS har et eget klagesystem, men mange passasjerer opplever at SAS initialt avviser gyldige krav.\n\nSAS har tidligere hatt perioder med høy kancelleringsrate — særlig under streiker og omstruktureringsperioder. Dersom kanselleringen skjedde under en SAS-pilotstreik, anses dette som ekstraordinær omstendighet kun for streiken blant flyselskapets egne ansatte hvis den var uforutsigbar — dette er juridisk omdiskutert.\n\nFremgangsmate: registrer krav direkte på SAS.no/refund, behold alle dokumenter og kvitteringer, og klag videre til Transportklagenemnda dersom SAS avviser kravet.", faqs: [{ q: "SAS avviser kravet mitt med 'ekstraordinære omstendigheter'. Hva gjør jeg?", a: "Krev skriftlig dokumentasjon på den spesifikke hendelsen. Dersom avvisningen ikke er tilstrekkelig begrunnet, klag til Transportklagenemnda — behandlingen er gratis." }, { q: "SAS-flyet mitt ble kansellert under pilotstreiken. Har jeg krav?", a: "Dette er juridisk omdiskutert. Streik blant egne ansatte regnes av noen domstoler som ekstraordinær omstendighet, andre ikke. Klag uansett — du kan vinne frem." }, { q: "SAS tilbyr EuroBonus-poeng i stedet for kontant kompensasjon. Må jeg akseptere?", a: "Nei, du har rett til kontant kompensasjon etter EU 261/2004. Du kan avslå poeng og kreve pengebeløpet utbetalt." }]},
  { slug: "norwegian-forsinkelse", title: "Norwegian forsinkelse over 3 timer — krav på erstatning", lawRef: "EU 261/2004 art. 7", cat: "flyreiser", desc: "Forsinkelse over 3 timer gir samme kompensasjonsrett som kansellering.", bodyText: "Norwegian er Norges nest største flyselskap og er fullt ut underlagt EU-forordning 261/2004 via EØS-avtalen. Ved forsinkelser over 3 timer ved ankomst har du krav på standardkompensasjon på 250–600 € avhengig av reisedistansen. I Sturgeon-dommen (C-402/07) fastslo EU-domstolen at passasjerer ved forsinkelse over 3 timer har samme rett til kompensasjon som ved kansellering — et prinsipp Norwegian er bundet av.\n\nKompensasjonssatsene er: 250 € for flygninger under 1 500 km, 400 € for flygninger mellom 1 500 og 3 500 km, og 600 € for flygninger over 3 500 km. Merk at dette er standardkompensasjon som kommer i tillegg til forpleining (mat, drikke, hotell). Norwegian avviser ofte krav med henvisning til teknisk feil, men EU-domstolen fastslo i Wallentin-Hermann (C-549/07) at teknisk feil normalt ikke er ekstraordinær omstendighet.\n\nSend kravet til Norwegian customer relations med flightnummer, dato, bookingkode og bevis for forsinkelsen. Dersom Norwegian avslår, kan du klage til Transportklagenemnda (flyklagenemnda.no) kostnadsfritt. Nelson-saken (C-581/10) bekrefter at tidsbruk er et selvstendig tap som gir rett til erstatning.", faqs: [{ q: "Norwegian tilbød matkupong. Mister jeg retten til kompensasjon?", a: "Nei. Matkupong er forpleining du har krav på uansett etter art. 9. Standardkompensasjon på 250–600 € er et separat krav etter art. 7 — bekreftet i Sturgeon-dommen (C-402/07)." }, { q: "Norwegian sier teknisk feil er ekstraordinært. Stemmer det?", a: "Nei. EU-domstolen fastslo i Wallentin-Hermann (C-549/07) at teknisk feil normalt er flyselskapets operative ansvar og ikke kvalifiserer som ekstraordinær omstendighet." }, { q: "Forsinkelsen var 2 timer og 50 minutter. Har jeg krav?", a: "Ikke på standardkompensasjon — grensen er 3 timer ved ankomst jf. Sturgeon-dommen. Men du har krav på mat og drikke ved forsinkelse over 2 timer etter art. 9." }] },
  { slug: "wideroe-mistet-tilslutning", title: "Widerøe: Mistet tilslutningsfly pga forsinkelse", lawRef: "EU 261/2004 art. 7", cat: "flyreiser", desc: "Mistet tilslutning som følge av forsinkelse gir full kompensasjonsrett.", bodyText: "Widerøe opererer et omfattende rutenett i Nord-Norge og distrikts-Norge, ofte med korte tilslutningsvinduer mellom flygninger. Dersom du mister et tilslutningsfly fordi det første flyet var forsinket, og begge flygningene var booket på samme billett, er Widerøe ansvarlig for hele reisen. I Flyklagenemndas sak 2022-118 ble det fastslått at mistet tilknytningsfly i utlandet gir krav på hotell og forpleining — prinsippet gjelder tilsvarende for innenlands tilslutning.\n\nEtter EU-forordning 261/2004 artikkel 7, bekreftet i Sturgeon-dommen (C-402/07), har du krav på kompensasjon dersom du ankommer endelig destinasjon mer enn 3 timer forsinket. Kompensasjonen beregnes basert på distansen til endelig destinasjon, ikke enkeltstrekningene. For innenlandsflygninger i Norge er satsen normalt 250 € (under 1 500 km).\n\nViktig: Dersom flygningene var booket separat (to uavhengige billetter), er Widerøe kun ansvarlig for forsinkelsen på den første flygningen. Men dersom du booket via Widerøes system og fikk én bookingkode, anses hele reisen som én sammenhengende reise med full beskyttelse.", faqs: [{ q: "Jeg hadde bare 30 minutter mellom flyene og rakk ikke. Er det Widerøes ansvar?", a: "Dersom du booket hele reisen i ett, ja. Widerøe satte tilslutningsvinduet og er ansvarlig. Sak 2022-118 bekrefter at mistet tilslutning gir krav på forpleining og hotell." }, { q: "Mistet tilslutning og måtte overnatte. Hvem betaler hotell?", a: "Widerøe plikter å tilby hotell og transport etter art. 9. I sak 2022-118 fikk passasjeren medhold i krav om hotell og forpleining etter mistet tilknytningsfly." }, { q: "Widerøe tilbød ny flyvning neste morgen. Har jeg likevel krav på kompensasjon?", a: "Ja, dersom du ankom endelig destinasjon mer enn 3 timer forsinket. Sturgeon-dommen (C-402/07) fastslår at forsinkelse over 3 timer gir kompensasjonsrett uansett omruting." }] },
  { slug: "ryanair-overbooking", title: "Nektet ombordstigning Ryanair (overbooking)", lawRef: "EU 261/2004 art. 4", cat: "flyreiser", desc: "Overbooking gir umiddelbar rett til kompensasjon og alternativ transport.", bodyText: "Ryanair er kjent for aggressiv overbooking — de selger flere billetter enn det er seter på flyet. Dersom du nektes ombordstigning fordi flyet er fullt, har du umiddelbar rett til kompensasjon etter EU 261/2004 artikkel 4. Overbooking gir den sterkeste rettigheten i forordningen — ingen unntaksregler gjelder. I Finnair-dommen (C-22/11) fastslo EU-domstolen at rett til erstatning gjelder selv når boarding nektes pga. omstendigheter selskapet ikke kontrollerer.\n\nKompensasjonen er 250 € for flygninger under 1 500 km, 400 € for flygninger mellom 1 500 og 3 500 km, og 600 € for flygninger over 3 500 km. I tillegg har du krav på omruting til endelig destinasjon med første tilgjengelige fly, eller full refusjon av billetten. Nelson-saken (C-581/10) bekrefter at tidsbruk er et selvstendig tap som skal kompenseres.\n\nDersom Ryanair ber frivillige om å gi opp setet sitt mot kompensasjon (typisk voucher), er dette forhandling — du er ikke pliktig til å akseptere. Velger du å beholde setet ditt og likevel nektes ombordstigning, har du rett til kontantkompensasjon pluss omruting og forpleining.", faqs: [{ q: "Ryanair tilbød voucher istedenfor kontantkompensasjon. Kan jeg kreve penger?", a: "Ja. Du har alltid rett til kontantkompensasjon etter art. 7. Finnair-dommen (C-22/11) bekrefter at nektet ombordstigning gir ubetinget rett til erstatning." }, { q: "Jeg ble nektet ombordstigning men fikk plass på fly 2 timer senere. Har jeg krav?", a: "Ja, du har krav på full kompensasjon. Beløpet kan halveres dersom forsinkelsen ved ankomst er under visse tidsgrenser, jf. art. 7 nr. 2." }, { q: "Ryanair sier det ikke var overbooking men 'operasjonelle årsaker'. Endrer det noe?", a: "Nei. Nektet ombordstigning uansett årsak (unntatt sikkerhet, helse, manglende dokumenter) gir rett til kompensasjon etter art. 4. Finnair (C-22/11) bekrefter dette." }] },
  { slug: "fly-streik-kompensasjon", title: "Flystreik: Har du krav på erstatning?", lawRef: "EU 261/2004 art. 5", cat: "flyreiser", desc: "Intern streik hos flyselskapet er ikke ekstraordinær omstendighet — du har krav.", bodyText: "Flystreik er et komplekst juridisk område der utfallet avhenger av hvem som streiker. EU-domstolen fastslo i Krüsemann-dommen (C-195/17) at intern streik hos flyselskapets egne ansatte — piloter, kabinpersonale — ikke er ekstraordinær omstendighet. Flyselskapet er ansvarlig og du har krav på standardkompensasjon på 250–600 €.\n\nDerimot kan ekstern streik — for eksempel streik hos flygeledere, bakkemannskap ansatt hos tredjeparter, eller generell transportstreik — kvalifisere som ekstraordinær omstendighet som fritar fra kompensasjonsplikten. Men selv ved ekstern streik har du krav på forpleining (mat, drikke, hotell) og omruting etter art. 9. Finnair-dommen (C-22/11) bekrefter at rett til erstatning gjelder selv om boarding nektes som følge av streik.\n\nSend kravet med henvisning til Krüsemann (C-195/17) dersom det gjelder intern streik. Flyselskapet må bevise at streiken var utenfor deres kontroll og at de tok alle rimelige tiltak for å unngå den. Nelson-saken (C-581/10) fastslår at tidsbruk er et tap som skal erstattes.", faqs: [{ q: "Pilotstreik kansellerte flyet mitt. Har jeg krav på kompensasjon?", a: "Ja. EU-domstolen fastslo i Krüsemann (C-195/17) at intern streik hos egne ansatte ikke er ekstraordinær omstendighet. Du har krav på 250–600 € i standardkompensasjon." }, { q: "Flyselskapet sier streiken var 'ulovlig'. Endrer det mine rettigheter?", a: "Nei. Krüsemann-dommen (C-195/17) skiller ikke mellom lovlig og ulovlig intern streik. Flyselskapet er uansett ansvarlig for egne ansattes arbeidsforhold." }, { q: "Flygelederstreik kansellerte flyet. Har jeg krav?", a: "Flygelederstreik regnes typisk som ekstraordinær omstendighet og fritar fra kompensasjon. Men du har likevel krav på forpleining og omruting etter art. 9." }] },
  { slug: "fly-teknisk-feil", title: "Erstatning når flyet kanselleres pga teknisk feil", lawRef: "EU 261/2004 art. 5", cat: "flyreiser", desc: "Teknisk feil er sjelden ekstraordinær omstendighet. Du har normalt krav på kompensasjon.", bodyText: "Teknisk feil på flyet er den vanligste årsaken til kanselleringer og forsinkelser, og flyselskaper forsøker systematisk å avvise krav med henvisning til ekstraordinære omstendigheter. EU-domstolen har imidlertid gjentatte ganger fastslått at teknisk feil er flyselskapets ansvar. I Wallentin-Hermann-dommen (C-549/07) fastslo domstolen at tekniske feil som oppdages under vedlikehold eller som skyldes manglende vedlikehold ikke er ekstraordinære omstendigheter.\n\nVan der Lans-dommen (C-257/14) gikk enda lenger: selv uforutsette tekniske svikt som oppstår plutselig er flyselskapets operative risiko. Kun svært sjeldne hendelser som skjulte produksjonsfeil som rammer hele flytypen kan kvalifisere som ekstraordinære. Sturgeon-dommen (C-402/07) bekrefter at forsinkelse over 3 timer gir samme kompensasjonsrett som kansellering.\n\nDersom flyselskapet avviser kravet ditt med teknisk feil som begrunnelse, henvis til Wallentin-Hermann (C-549/07) og Van der Lans (C-257/14). Be om spesifikk dokumentasjon av feilen — generelle påstander er ikke tilstrekkelig. Du har krav på 250–600 € avhengig av reisedistanse.", faqs: [{ q: "Flyselskapet sier teknisk feil er ekstraordinært. Stemmer det?", a: "Nei. Wallentin-Hermann (C-549/07) fastslår at teknisk feil normalt er flyselskapets ansvar. Van der Lans (C-257/14) bekrefter at selv uforutsette svikt er operativ risiko." }, { q: "Kan jeg kreve kompensasjon for teknisk feil oppdaget rett før avgang?", a: "Ja. Van der Lans-dommen (C-257/14) fastslår at tidspunktet for oppdagelse ikke endrer ansvarsspørsmålet — teknisk vedlikehold er flyselskapets risiko." }, { q: "Teknisk feil førte til 5 timers forsinkelse. Hva kan jeg kreve?", a: "Standardkompensasjon 250–600 € jf. Sturgeon (C-402/07), pluss forpleining (mat, drikke) under ventetiden etter art. 9, og hotell dersom du måtte overnatte." }] },
  { slug: "klm-forsinkelse", title: "KLM fly forsinket til/fra Norge — dine krav", lawRef: "EU 261/2004 art. 7", cat: "flyreiser", desc: "KLM er omfattet av EU 261/2004 på alle flygninger til/fra EU/EØS.", bodyText: "KLM (Royal Dutch Airlines) er et EU-basert flyselskap med base i Nederland, og er fullt underlagt EU-forordning 261/2004 på alle flygninger til og fra EU/EØS-området. Sturgeon-dommen (C-402/07) fastslår at forsinkelse over 3 timer ved ankomst gir samme kompensasjonsrett som kansellering — 250–600 € avhengig av reisedistanse.\n\nKLM opererer mange flygninger via Amsterdam Schiphol som knutepunkt. Dersom du har en gjennomgående billett og mister tilslutningsflyet i Amsterdam pga. forsinkelse, beregnes kompensasjonen ut fra total forsinkelse ved endelig destinasjon. Nelson-saken (C-581/10) bekrefter at tidsbruk er et selvstendig tap. I sak 2022-118 fra Flyklagenemnda fikk en passasjer medhold i krav om hotell og forpleining etter mistet tilknytningsfly — prinsippet gjelder tilsvarende for KLM-tilslutninger.\n\nKLM har et online klagesystem, men avviser ofte krav i første omgang. Send skriftlig reklamasjon med flightnummer, dato, bookingkode og bevis for forsinkelsen. Dersom KLM avslår, kan du klage til det nederlandske tilsynet (ILT) eller Transportklagenemnda i Norge.", faqs: [{ q: "KLM-flyet fra Amsterdam var forsinket. Gjelder norsk klagenemnd?", a: "Ja, du kan klage til Transportklagenemnda i Norge dersom flygningen hadde avgang fra eller ankomst til norsk flyplass. Sturgeon (C-402/07) gir rett til kompensasjon ved forsinkelse over 3 timer." }, { q: "Mistet tilslutning i Amsterdam pga. KLM-forsinkelse. Hva kan jeg kreve?", a: "Kompensasjon basert på total forsinkelse ved endelig destinasjon, pluss mat, drikke og hotell. Sak 2022-118 bekrefter krav på forpleining ved mistet tilknytning." }, { q: "KLM sier forsinkelsen skyldtes teknisk feil. Fritar det dem?", a: "Nei. Wallentin-Hermann (C-549/07) fastslår at teknisk feil normalt er operativ risiko. Van der Lans (C-257/14) bekrefter dette — selv uforutsette tekniske svikt fritar ikke." }] },
  { slug: "lufthansa-kansellert", title: "Lufthansa kansellert fly: Slik klager du", lawRef: "EU 261/2004 art. 7", cat: "flyreiser", desc: "Lufthansa-kansellering gir deg rett til 250–600 € avhengig av reisedistanse.", bodyText: "Lufthansa er et tysk EU-basert flyselskap som er fullt underlagt EU-forordning 261/2004. Ved kansellering har du krav på kompensasjon dersom du ble varslet mindre enn 14 dager før avgang. Satsen er 250–600 € avhengig av reisedistansen. Sturgeon-dommen (C-402/07) og Nelson-saken (C-581/10) bekrefter at dette er standardiserte beløp som kompenserer for tidsbruk — et selvstendig tap.\n\nLufthansa opererer et omfattende nettverk via Frankfurt og München. Dersom hele reisen er på én billett og tilslutningsflyet kanselleres, gjelder kompensasjonsretten for hele reisen. Lufthansa er også forpliktet til å tilby alternativ transport med første tilgjengelige fly — også med andre flyselskap. Avviser Lufthansa med henvisning til teknisk feil, er dette normalt ikke ekstraordinært jf. Wallentin-Hermann (C-549/07).\n\nLufthansa svarer ofte med standardavslag. Vær spesifikk i kravet: oppgi flightnummer, dato, bookingkode, kanselleringstidspunkt og krev eksakt beløp. Dersom Lufthansa avslår uten god begrunnelse, kan du eskalere til SÖP (tysk klageorgan) eller Transportklagenemnda i Norge.", faqs: [{ q: "Lufthansa kansellerte 10 dager før avgang. Har jeg krav?", a: "Ja, varsel under 14 dager gir kompensasjonsrett etter art. 5. Sturgeon (C-402/07) og Nelson (C-581/10) bekrefter at kompensasjon gis for tapt tid." }, { q: "Lufthansa sier kanselleringen skyldes teknisk feil. Fritar det dem?", a: "Nei. Wallentin-Hermann (C-549/07) fastslår at teknisk feil normalt er operativ risiko. Be Lufthansa dokumentere at feilen var ekstraordinær — generelle påstander holder ikke." }, { q: "Kan jeg klage til tysk klagenemnd fra Norge?", a: "Ja, SÖP tar imot klager fra alle EU/EØS-borgere. Du kan også bruke norsk Transportklagenemnd — begge er gratis." }] },
  { slug: "fly-mat-hotell-krav", title: "Krav på mat og hotell ved lang forsinkelse", lawRef: "EU 261/2004 art. 9", cat: "flyreiser", desc: "Ved forsinkelse over 2 timer har du rett på forpleining uavhengig av årsak.", bodyText: "Ved forsinkelse over 2 timer har du rett på mat og drikke uavhengig av forsinkelsens årsak — selv ved ekstraordinære omstendigheter som fritar flyselskapet fra standardkompensasjon. Denne retten følger av EU-forordning 261/2004 artikkel 9 og gjelder absolutt. EU-domstolen bekreftet i EU-sak C-315/15 at selv fuglekollisjon (som er ekstraordinært) ikke fritar fra plikten til forpleining.\n\nViktig å skille mellom standardkompensasjon og dekning av faktiske utlegg: Kompensasjon (250–600 €) er et fast beløp for tapt tid jf. Sturgeon (C-402/07). Forpleining (mat, drikke, hotell) dekker dine faktiske utgifter og gjelder alltid — uansett årsak til forsinkelsen. Hotell og transport skal tilbys ved overnatting.\n\nTidsfristene for forpleining er: 2 timer for flygninger under 1 500 km, 3 timer for flygninger mellom 1 500 og 3 500 km, og 4 timer for flygninger over 3 500 km. Dersom flyselskapet ikke tilbyr forpleining, kan du ordne det selv og kreve refusjon. Ta vare på alle kvitteringer.", faqs: [{ q: "Flyselskapet ga ingen mat eller drikke under 6 timers forsinkelse. Hva gjør jeg?", a: "Kjøp mat og drikke selv og ta vare på kvitteringer. Flyselskapet plikter å refundere etter art. 9. EU-sak C-315/15 bekrefter at forpleining gjelder uansett årsak." }, { q: "Har jeg krav på hotell ved forsinkelse til neste dag?", a: "Ja, flyselskapet plikter å tilby hotell og transport etter art. 9. Sak 2022-118 fra Flyklagenemnda bekrefter at mistet tilslutning gir krav på overnatting." }, { q: "Hva er forskjellen på kompensasjon og forpleining?", a: "Kompensasjon (250–600 €) er standardbeløp for tapt tid jf. Sturgeon (C-402/07) — gjelder kun ved ikke-ekstraordinære årsaker. Forpleining (mat, hotell) dekker faktiske utlegg og gjelder alltid, uansett årsak." }] },
  { slug: "mistet-bagasje-erstatning", title: "Erstatning for mistet bagasje på flyreise", lawRef: "Montreal-konvensjonen art. 17", cat: "flyreiser", desc: "Mistet bagasje gir krav på opptil ca. 1 700 SDR i erstatning.", bodyText: "Mistet bagasje på flyreise er regulert av Montrealkonvensjonen, som gir deg rett til erstatning opptil ca. 1 700 SDR (ca. 22 000 kr). Flyselskapet er objektivt ansvarlig for innsjekket bagasje fra det tidspunktet den leveres til flyselskapet til du mottar den ved ankomst. Montrealkonvensjonen setter en absolutt frist på 21 dager for å melde forsinket bagasje — etter dette mister du kravgrunnlaget.\n\nDet første du må gjøre er å fylle ut PIR-skjema (Property Irregularity Report) på flyplassen umiddelbart. Uten PIR er det svært vanskelig å fremme erstatningskrav i etterkant. Bagasje regnes som tapt dersom den ikke leveres innen 21 dager etter PIR-registreringen. For ødelagt bagasje er reklamasjonsfristen kun 7 dager etter mottak.\n\nFor erstatningskravet trenger du dokumentasjon på innholdet og verdien. Bilder av innholdet, kjøpskvitteringer og kontoutskrifter er nyttig. Flyselskapet vil normalt gjøre fradrag for alder og slitasje (avskrivning). Merk: Montrealkonvensjonen dekker faktisk tap — dette er separat fra standardkompensasjon etter EU 261/2004.", faqs: [{ q: "Hva er det første jeg må gjøre når bagasjen er borte?", a: "Fyll ut PIR-skjema på flyplassen umiddelbart. Montrealkonvensjonen krever melding innen 21 dager for forsinket bagasje og 7 dager for skadet bagasje — uten PIR mister du kravgrunnlaget." }, { q: "Hva er makserstatningen for mistet bagasje?", a: "Ca. 1 700 SDR (ca. 22 000 kr) etter Montrealkonvensjonen. Dette dekker faktisk tap — dokumenter innholdet med bilder og kvitteringer for å maksimere kravet." }, { q: "Kan jeg kreve både bagasjeerstatning og flykompensasjon?", a: "Ja. Bagasjeerstatning etter Montrealkonvensjonen (faktiske tap) og standardkompensasjon etter EU 261/2004 (tapt tid) er to separate krav som kan fremmes parallelt." }] },

  // FLYREISER (10 nye noder med FAQs)
  { slug: "forsinket-crew-mangel", title: "Erstatning ved mangel på crew eller besetning", lawRef: "EU 261/2004 art. 5", cat: "flyreiser", desc: "Sykdom hos personell regnes ikke som ekstraordinær omstendighet. Du har krav på kompensasjon.", bodyText: "Mangel på crew eller besetning er et internt operasjonelt problem som flyselskapet er ansvarlig for. I Flyklagenemndas sak 2023-012 ble det fastslått at crew-mangel gir full kompensasjon — passasjeren fikk 600 EUR fordi flyselskapet ikke kunne dokumentere at mangelen var ekstraordinær. Bemanningsplanlegging er en del av normal drift, og sykdom blant personell er en forventet del av driften.\n\nEU-domstolen har i flere avgjørelser presisert at kun omstendigheter helt utenfor flyselskapets kontroll er ekstraordinære. Van der Lans (C-257/14) fastslår at operative utfordringer — inkludert uforutsette hendelser — er flyselskapets risiko dersom de er knyttet til normal drift. Bemanningsproblemer faller klart i denne kategorien. Kompensasjonssatsene er 250 €, 400 € eller 600 € avhengig av reisedistanse.\n\nI tillegg til standardkompensasjon har du krav på forpleining (mat, drikke) under ventetiden og hotell dersom du må overnatte. Disse faktiske utleggene dekkes uansett årsak — også dersom flyselskapet mot formodning skulle få medhold i at crew-mangelen var ekstraordinær.", faqs: [{ q: "Flyet ble kansellert fordi crew ikke møtte opp. Er det ekstraordinær omstendighet?", a: "Nei. I Flyklagenemndas sak 2023-012 ble crew-mangel ansett som internt operasjonelt problem som ga full kompensasjon på 600 EUR." }, { q: "Flyselskapet sier piloten ble akutt syk. Fritar det dem?", a: "Normalt nei. Van der Lans (C-257/14) fastslår at operative utfordringer er flyselskapets risiko. Selskapet skal ha beredskapsplaner for sykdom hos personell." }, { q: "Jeg fikk ny flyvning neste dag. Hva kan jeg kreve totalt?", a: "Standardkompensasjon 250–600 € jf. sak 2023-012, pluss dekning av faktiske utlegg til mat, drikke og hotell etter art. 9. Dette er to separate krav." }]},
  { slug: "finnair-forsinkelse", title: "Erstatning ved forsinkelse med Finnair", lawRef: "EU 261/2004 art. 7", cat: "flyreiser", desc: "Finnair er EU-basert og fullt ut dekket av forordning 261/2004.", bodyText: "Finnair er et finsk EU-basert flyselskap som er fullt underlagt EU-forordning 261/2004. Sturgeon-dommen (C-402/07) fastslår at forsinkelse over 3 timer ved ankomst gir rett til standardkompensasjon — 250–600 € avhengig av reisedistanse. I Finnair-dommen (C-22/11) fastslo EU-domstolen dessuten at rett til erstatning gjelder selv om boarding nektes pga. omstendigheter selskapet ikke kontrollerer.\n\nFinnair opererer mange ruter via Helsinki som knutepunkt. Dersom du har gjennomgående billett og mister tilslutning i Helsinki, beregnes kompensasjonen ut fra total forsinkelse til endelig destinasjon. For ruter Oslo–Helsinki er satsen normalt 250 € (under 1 500 km), mens for lengre ruter via Helsinki kan den være 400 € eller 600 €. Nelson-saken (C-581/10) bekrefter at tidsbruk er et selvstendig tap.\n\nFinnair avviser mange krav med standardformuleringer. Dersom de påberoper teknisk feil, henvis til Wallentin-Hermann (C-549/07) som fastslår at dette normalt er operativ risiko. Klag til Transportklagenemnda i Norge (gratis) eller det finske tilsynsorganet Traficom.", faqs: [{ q: "Finnair-flyet mitt fra Oslo var 4 timer forsinket. Hva kan jeg kreve?", a: "250–400 € avhengig av reisedistanse jf. Sturgeon (C-402/07), pluss mat og drikke under ventetiden etter art. 9. Finnair-dommen (C-22/11) bekrefter sterk passasjerbeskyttelse." }, { q: "Finnair avviste kravet mitt med 'ekstraordinære omstendigheter'. Hva gjør jeg?", a: "Be dem dokumentere den spesifikke årsaken. Wallentin-Hermann (C-549/07) fastslår at teknisk feil ikke er ekstraordinært. Klag til Transportklagenemnda gratis." }, { q: "Mistet tilslutning i Helsinki pga. Finnair-forsinkelse. Hva dekkes?", a: "Standardkompensasjon basert på total forsinkelse ved endelig destinasjon, pluss faktiske utlegg til mat og hotell. Sak 2022-118 bekrefter krav ved mistet tilknytning." }]},
  { slug: "british-airways-kansellert", title: "British Airways kansellert fly: Dine rettigheter", lawRef: "EU 261/2004 art. 7", cat: "flyreiser", desc: "BA er britisk men UK opprettholder EU-forordning 261 post-Brexit for flygninger fra EU/EØS.", bodyText: "British Airways (BA) er et britisk flyselskap som etter Brexit opererer under UK261 — den britiske versjonen av EU 261/2004 som er tilnærmet identisk. For flygninger fra EU/EØS med BA gjelder EU-forordningen direkte; for flygninger fra UK gjelder UK261 med samme satser og rettigheter. Sturgeon-dommen (C-402/07) og Nelson-saken (C-581/10) gjelder fullt ut for EU/EØS-avganger.\n\nVed kansellering har du krav på standardkompensasjon (250–600 €) dersom du ble varslet mindre enn 14 dager før avgang. Merk skillet mellom kompensasjon og refusjon: kompensasjon er fast beløp for tapt tid, mens refusjon er tilbakebetaling av billetten. Du har alltid rett til å kreve kontantrefusjon — du er ikke pliktig til å akseptere voucher. Wallentin-Hermann (C-549/07) fastslår at teknisk feil ikke fritar fra kompensasjonsplikten.\n\nBA har et online claim-system, men behandlingstiden kan være lang. Dersom BA avslår, kan du bruke CAA (UK Civil Aviation Authority) for flygninger fra UK, eller Transportklagenemnda for flygninger fra Norge.", faqs: [{ q: "BA kansellerte flyet mitt fra London til Oslo. Gjelder EU-reglene?", a: "Fra UK med BA gjelder UK261 som er identisk med EU 261/2004. Du har krav på 250–600 € standardkompensasjon jf. Sturgeon (C-402/07)." }, { q: "BA tilbød voucher istedet for kontanterstatning. Kan jeg kreve penger?", a: "Ja. Du har alltid rett til kontanterstatning etter art. 7. Voucher kan tilbys men du er aldri pliktig til å akseptere det." }, { q: "BA sier kanselleringen skyldes teknisk feil. Er jeg sjanseløs?", a: "Nei. Wallentin-Hermann (C-549/07) fastslår at teknisk feil normalt er operativ risiko. Van der Lans (C-257/14) bekrefter at selv uforutsette tekniske svikt ikke fritar." }]},
  { slug: "air-france-bagasje", title: "Erstatning for mistet bagasje hos Air France", lawRef: "Montreal-konvensjonen art. 17", cat: "flyreiser", desc: "Air France er ansvarlig for mistet eller ødelagt bagasje etter Montrealkonvensjonen.", bodyText: "Air France er ansvarlig for mistet, forsinket eller ødelagt bagasje etter Montrealkonvensjonen. Makserstatningen er ca. 1 700 SDR (ca. 22 000 kr), og Air France er objektivt ansvarlig — du trenger ikke bevise uaktsomhet, bare at bagasjen gikk tapt eller ble skadet under flyreisen. Montrealkonvensjonen setter strenge frister: 7 dager for skadet bagasje, 21 dager for forsinket bagasje.\n\nViktig å skille mellom to separate kravgrunnlag: Montrealkonvensjonen dekker dine faktiske tap (verdi av mistet innhold, nødkjøp ved forsinkelse). EU 261/2004 gir standardkompensasjon for tapt tid ved forsinkelse/kansellering. Du kan kreve begge dersom flyet også var forsinket. Sturgeon-dommen (C-402/07) bekrefter kompensasjon ved forsinkelse over 3 timer.\n\nFørste skritt er å fylle ut PIR-skjema (Property Irregularity Report) på flyplassen umiddelbart. Uten PIR er det svært vanskelig å fremme krav. For forsinket bagasje har du krav på dekning av nødvendige kjøp (klær, toalettartikler) for rimelige beløp — dokumenter alt med kvitteringer.", faqs: [{ q: "Air France mistet bagasjen min. Hva gjør jeg på flyplassen?", a: "Fyll ut PIR-skjema umiddelbart. Montrealkonvensjonen krever melding innen 21 dager for forsinket bagasje og 7 dager for skadet bagasje — uten PIR taper du kravgrunnlaget." }, { q: "Bagasjen dukket opp etter 5 dager. Kan jeg kreve erstatning for nødkjøp?", a: "Ja, dokumenterte utgifter til nødvendige klær og toalettartikler dekkes etter Montrealkonvensjonen art. 19. Hold utgiftene rimelige og ta vare på alle kvitteringer." }, { q: "Kan jeg kreve både bagasjeerstatning og flykompensasjon?", a: "Ja. Bagasjeerstatning (Montrealkonvensjonen) dekker faktisk tap. Standardkompensasjon (EU 261/2004 jf. Sturgeon C-402/07) dekker tapt tid. To separate kravgrunnlag." }]},
  { slug: "flyforsinkelse-it-feil", title: "Kompensasjon ved flyforsinkelse pga. IT-feil", lawRef: "EU 261/2004 art. 5", cat: "flyreiser", desc: "IT-feil hos flyselskapet er ikke ekstraordinær omstendighet — du har krav på kompensasjon.", bodyText: "IT-feil hos flyselskapet — som nedetid i bookingsystemer, innsjekkingssystemer eller flyoperasjonssystemer — er et internt operasjonelt problem som flyselskapet er ansvarlig for. Prinsippet fra Wallentin-Hermann (C-549/07) om at interne driftsproblemer ikke er ekstraordinære omstendigheter gjelder tilsvarende for IT-svikt. Van der Lans (C-257/14) bekrefter at uforutsette operative hendelser er flyselskapets risiko.\n\nFlyselskapet kan ikke fraskrive seg ansvar for egne datasystemer. Vedlikehold og robusthet i IT-infrastrukturen er en del av normal drift. Kun IT-feil forårsaket av eksterne aktører — som cyberangrep fra tredjeparter eller infrastrukturfeil hos flyplassoperatør — kan potensielt kvalifisere som ekstraordinært. Sturgeon-dommen (C-402/07) gir rett til 250–600 € ved forsinkelse over 3 timer.\n\nDersom flyselskapet avviser kravet med IT-feil som begrunnelse, henvis til Wallentin-Hermann og Van der Lans. Be om spesifikk dokumentasjon — generelle påstander holder ikke. Du har i tillegg alltid krav på forpleining (mat, drikke, hotell) etter art. 9, uansett årsak.", faqs: [{ q: "Flyselskapet sier IT-krasj er ekstraordinær omstendighet. Er det riktig?", a: "Nei. Wallentin-Hermann (C-549/07) fastslår at interne driftsproblemer ikke er ekstraordinære. Van der Lans (C-257/14) bekrefter at operative utfordringer er selskapets risiko." }, { q: "IT-feilen rammet hele flyplassen, ikke bare ett selskap. Endrer det noe?", a: "Muligens. Infrastrukturfeil utenfor selskapets kontroll kan kvalifisere som ekstraordinært. Men flyselskapet må dokumentere dette konkret — generelle påstander holder ikke." }, { q: "Hva kan jeg kreve ved IT-forsinkelse over 3 timer?", a: "Standardkompensasjon 250–600 € jf. Sturgeon (C-402/07), pluss faktiske utlegg til mat og drikke etter art. 9. Dette er to separate krav med ulike kravgrunnlag." }]},
  { slug: "easyjet-forsinkelse", title: "EasyJet forsinkelse over 3 timer: Krav på erstatning", lawRef: "EU 261/2004 art. 7", cat: "flyreiser", desc: "EasyJet er EU-basert og fullt dekket av forordning 261/2004.", bodyText: "EasyJet er et britisk lavprisselskap som er underlagt EU-forordning 261/2004 på alle flygninger fra EU/EØS-flyplasser. Sturgeon-dommen (C-402/07) fastslår at forsinkelse over 3 timer ved ankomst gir rett til standardkompensasjon på 250–600 € avhengig av reisedistansen — uavhengig av billettpris.\n\nEasyJet er kjent for å avvise mange krav med standardformuleringer om ekstraordinære omstendigheter. Ikke gi deg — de fleste avslag er ugrunnet. Wallentin-Hermann (C-549/07) fastslår at teknisk feil ikke er ekstraordinært, og Van der Lans (C-257/14) bekrefter at selv uforutsette tekniske svikt er operativ risiko. Nelson-saken (C-581/10) fastslår at tidsbruk er et selvstendig tap som gir rett til erstatning.\n\nDersom EasyJet avslår kravet, kan du klage til Transportklagenemnda i Norge (gratis) for flygninger fra norske flyplasser, eller CAA (UK Civil Aviation Authority) for flygninger fra UK. I tillegg til standardkompensasjon har du alltid krav på forpleining (mat, drikke, hotell) etter art. 9 — uavhengig av forsinkelsens årsak.", faqs: [{ q: "EasyJet-flyet var 3,5 timer forsinket. Hva kan jeg kreve?", a: "Standardkompensasjon 250–600 € jf. Sturgeon (C-402/07), pluss faktiske utlegg til mat og drikke etter art. 9. Dette er to separate krav — ikke la EasyJet blande dem." }, { q: "EasyJet tilbød 10€ matkupong. Er jeg ferdig da?", a: "Nei. Matkupong er forpleining etter art. 9 som du har krav på uansett. Standardkompensasjonen på 250–600 € er et separat krav som kommer i tillegg." }, { q: "EasyJet sier forsinkelsen skyldes teknisk feil. Mister jeg kravet?", a: "Nei. Wallentin-Hermann (C-549/07) og Van der Lans (C-257/14) fastslår at teknisk feil er flyselskapets operative risiko — ikke ekstraordinær omstendighet." }]},
  { slug: "turkish-airlines-kansellert", title: "Turkish Airlines kansellert fly via Istanbul", lawRef: "EU 261/2004 art. 7", cat: "flyreiser", desc: "Flygninger fra EU/EØS med Turkish Airlines er dekket av EU 261/2004.", bodyText: "Turkish Airlines er et tyrkisk flyselskap som er underlagt EU-forordning 261/2004 på alle flygninger fra EU/EØS-flyplasser — uavhengig av at Tyrkia ikke er med i EU. Sturgeon-dommen (C-402/07) gir rett til standardkompensasjon (250–600 €) ved forsinkelse over 3 timer, og Nelson-saken (C-581/10) bekrefter at tidsbruk er et selvstendig tap som skal erstattes.\n\nVed kansellering eller forsinkelse fra norsk eller annen EU/EØS-flyplass har du krav på standardkompensasjon dersom du ble varslet mindre enn 14 dager før avgang. Merk skillet mellom standardkompensasjon og faktiske utlegg: kompensasjonen er et fast beløp for tapt tid, mens forpleining (mat, drikke, hotell) dekker dine faktiske kostnader og gjelder alltid — bekreftet i EU-sak C-315/15.\n\nTurkish Airlines behandler krav via e-post eller online-skjema. Behandlingstiden kan være lang. Dersom de avslår, kan du klage til Transportklagenemnda i Norge. For flygninger fra Istanbul til EU/EØS er du kun dekket dersom du har gjennomgående billett fra en EU/EØS-flyplass.", faqs: [{ q: "Turkish Airlines kansellerte flyet mitt fra Oslo til Istanbul. Gjelder EU-reglene?", a: "Ja. Flygninger fra Norge (EØS) med ethvert flyselskap er dekket av EU 261/2004. Sturgeon (C-402/07) gir rett til 250–600 € ved forsinkelse over 3 timer." }, { q: "Layoveren min i Istanbul ble 18 timer. Har jeg krav på hotell?", a: "Ja, ved forsinkelse som medfører overnatting plikter flyselskapet å tilby hotell etter art. 9. EU-sak C-315/15 bekrefter at forpleining gjelder uansett årsak til forsinkelsen." }, { q: "Turkish sier kanselleringen skyldes politisk uro. Er det ekstraordinært?", a: "Politisk uro kan kvalifisere som ekstraordinær omstendighet som fritar fra standardkompensasjon. Men du har likevel krav på forpleining og omruting etter art. 8 og 9." }]},
  { slug: "nektet-ombordstigning-lojalitetsprogram", title: "Nektet ombordstigning pga. bonuspoeng-billett", lawRef: "EU 261/2004 art. 4", cat: "flyreiser", desc: "Også bonusbilletter gir full rett til kompensasjon ved nektet ombordstigning.", bodyText: "Å bli nektet ombordstigning fordi du reiser på en bonusbillett er ikke lovlig grunnlag for å frata deg rettigheter. EU-forordning 261/2004 artikkel 4 skiller ikke mellom billetttyper. I Finnair-dommen (C-22/11) fastslo EU-domstolen at rett til erstatning gjelder selv om boarding nektes pga. omstendigheter selskapet ikke kontrollerer — det gjelder i aller høyeste grad ved ren overbooking av bonusseter.\n\nFlyselskaper praktiserer tidvis lavere prioritet for bonusbilletter ved overbooking, men dette er i strid med forordningen. Nelson-saken (C-581/10) bekrefter at tidsbruk er et selvstendig tap som gir rett til standardkompensasjon: 250 € for flygninger under 1 500 km, 400 € mellom 1 500–3 500 km, og 600 € over 3 500 km. I tillegg har du krav på omruting og forpleining.\n\nDokumenter hendelsen: ta bilder av gate-skjermen, noter tidspunkt og eventuell muntlig begrunnelse fra personalet. Referer til Finnair-dommen (C-22/11) og art. 4 som ikke gjør unntak for bonusbilletter. Send skriftlig krav med boardingkort og bookingbekreftelse.", faqs: [{ q: "Bonusbillettsetet mitt ble gitt til en betalende passasjer. Er det lovlig?", a: "Nei. Finnair-dommen (C-22/11) fastslår at rett til erstatning gjelder uavhengig av billetttype. Nektet ombordstigning gir ubetinget krav på 250–600 €." }, { q: "Flyselskapet sier bonusbillett er lavere prioritet. Endrer det mine rettigheter?", a: "Nei. EU 261/2004 art. 4 skiller ikke mellom billetttyper. Nelson (C-581/10) bekrefter at kompensasjon gis for tidsbruk, ikke billettverdi." }, { q: "Kan jeg kreve både kompensasjon og omruting med bonusbillett?", a: "Ja. Du har rett til standardkompensasjon (250–600 €) pluss omruting med første tilgjengelige fly og forpleining under ventetiden — nøyaktig som med ordinær billett." }]},
  { slug: "bagasje-forsinket-feriestart", title: "Forsinket bagasje ved feriestart: Erstatning for nødkjøp", lawRef: "Montreal-konvensjonen art. 19", cat: "flyreiser", desc: "Flyselskapet er ansvarlig for dokumenterte nødkjøp når bagasjen er forsinket.", bodyText: "Å stå uten bagasje ved starten av en ferie er frustrerende, men flyselskapet er økonomisk ansvarlig for konsekvensene. Etter Montrealkonvensjonen artikkel 19 har du krav på dekning av rimelige og nødvendige nødkjøp — klær, toalettartikler og andre daglige nødvendigheter — inntil bagasjen leveres. Montrealkonvensjonen setter en absolutt frist: reklamasjon innen 21 dager etter at du mottok bagasjen.\n\nViktig å skille mellom nødvendige og unødvendige kjøp — og mellom faktiske utlegg og standardkompensasjon. Nødkjøp (klær, undertøy, toalettartikler, solkrem) dekkes etter Montrealkonvensjonen som faktisk tap. Dersom også selve flyet var forsinket over 3 timer, har du i tillegg krav på standardkompensasjon (250–600 €) etter Sturgeon (C-402/07). Dette er to separate krav.\n\nFyll ut PIR-skjema på flyplassen umiddelbart. Dersom bagasjen ikke er levert innen 21 dager, anses den som tapt og du kan kreve full erstatning opptil ca. 1 700 SDR (ca. 22 000 kr). Send krav til flyselskapet med PIR-nummer og alle kvitteringer for nødkjøp.", faqs: [{ q: "Bagasjen kom tre dager forsinket. Kan jeg kreve alle klær jeg kjøpte?", a: "Du kan kreve rimelige og nødvendige nødkjøp etter Montrealkonvensjonen art. 19. Designerklær dekkes ikke — hold utgiftene på et rimelig nivå og behold alle kvitteringer." }, { q: "Bagasjen kom aldri. Hva er makserstatningen?", a: "Ca. 1 700 SDR (ca. 22 000 kr) etter Montrealkonvensjonen. Reklamasjonsfrist er 21 dager. Dokumenter innholdet med bilder og kvitteringer for å maksimere kravet." }, { q: "Kan jeg kreve erstatning for ødelagt ferie i tillegg?", a: "Montrealkonvensjonen dekker faktisk økonomisk tap. Standardkompensasjon etter EU 261/2004 (Sturgeon C-402/07) gis ved flyforsinkelse over 3 timer — men ikke for ferieulemper utover dette." }]},
  { slug: "innlandsflyging-rettigheter", title: "Rettigheter ved kansellert innenlandsfly i Norge", lawRef: "EU 261/2004 / Luftfartsloven", cat: "flyreiser", desc: "Innenlandsfly i Norge er delvis dekket av EU 261/2004 via EØS-avtalen.", bodyText: "Innenlandsflygninger i Norge er dekket av EU-forordning 261/2004 via EØS-avtalen. Sturgeon-dommen (C-402/07) gir rett til standardkompensasjon ved forsinkelse over 3 timer — for innenlandsflygninger er satsen normalt 250 € (flygninger under 1 500 km). Nelson-saken (C-581/10) bekrefter at tidsbruk er et selvstendig tap som gir rett til erstatning.\n\nWiderøe og SAS er de største operatørene på innenlandsruter, og begge er underlagt forordningen. Ved kansellering har du rett til omruting med første tilgjengelige transport — inkludert buss, tog eller taxi dersom det er raskere enn neste fly. I Flyklagenemndas sak 2023-012 ble crew-mangel ansett som grunnlag for full kompensasjon — et prinsipp som gjelder uavhengig av rutetype.\n\nI distrikts-Norge der flyruteflyet kan være eneste praktiske reisemulighet, er omrutingsplikten særlig viktig. Flyselskapet kan ikke bare kansellere uten å tilby alternativ transport. I tillegg til standardkompensasjon har du alltid krav på forpleining (mat, drikke, hotell) etter art. 9 — uansett årsak til forsinkelsen, bekreftet i EU-sak C-315/15.", faqs: [{ q: "Widerøe kansellerte innenlandsflyet mitt. Har jeg krav på EU-kompensasjon?", a: "Ja. Sturgeon (C-402/07) gir rett til 250 € for flygninger under 1 500 km. Sak 2023-012 bekrefter full kompensasjon selv ved operative problemer som crew-mangel." }, { q: "Ruteflyet er eneste transportmulighet til øya min. Har jeg ekstra rettigheter?", a: "Flyselskapet plikter å tilby alternativ transport eller full refusjon etter art. 8. Kan du dokumentere ekstra kostnader (f.eks. leiebil), kan disse kreves dekket." }, { q: "Hva er forskjellen på kompensasjon og forpleining for innenlandsfly?", a: "Kompensasjon (250 €) er standardbeløp for tapt tid jf. Sturgeon (C-402/07). Forpleining (mat, hotell) dekker faktiske utlegg og gjelder alltid — bekreftet i EU-sak C-315/15." }]},

  // FLYREISER (2 nye noder)
  { slug: "bagasje-forsinket-ferie", title: "Forsinket bagasje på feriereise", lawRef: "Montreal-konvensjonen art. 19", cat: "flyreiser", desc: "Flyselskapet dekker nødvendige kjøp når bagasjen er forsinket.", bodyText: "Forsinket bagasje er regulert av Montreal-konvensjonen, som alle EU/EØS-flyselskaper er bundet av. Dersom bagasjen ikke ankommer ved landing, har du rett til å kjøpe nødvendige gjenstander på flyselskapets regning — typisk klær, toalettartikler og medisiner du ikke hadde i håndbagasjen.\n\nRapportér bagasjeforsinkelsen umiddelbart ved ankomst til flyselskapets bagasjeskranke og få en Property Irregularity Report (PIR). Uten denne rapporten er det svært vanskelig å fremme krav i ettertid. Ta vare på alle kvitteringer for nødkjøp — flyselskapet dekker rimelige og nødvendige utgifter, ikke luksusvarer.\n\nDersom bagasjen ikke er returnert innen 21 dager fra planlagt ankomst, regnes den som tapt og du kan kreve erstatning opp til SDR 1 288 (ca. 17 000 kr) under Montreal-konvensjonen.", faqs: [{ q: "Flyselskapet sier de dekker maks 50 EUR per dag. Er det riktig?", a: "Dette er flyselskapets interne policy, ikke en rettslig grense. Du har rett til dekning av rimelige og nødvendige utgifter etter Montreal-konvensjonen, uten fast dagsgrense." }, { q: "Jeg hadde reiseforsikring. Skal jeg bruke den eller kreve av flyselskapet?", a: "Krev alltid av flyselskapet først. Reiseforsikringen kan dekke det som flyselskapet eventuelt ikke dekker, men forsikringsselskapet vil regresskrve flyselskapet uansett." }, { q: "Bagasjen kom etter 4 dager. Kan jeg kreve kompensasjon for ødelagt ferie?", a: "Du kan kreve dokumenterte utgifter til nødkjøp. Kompensasjon for tapt ferieverdi er ikke dekket under Montreal-konvensjonen, men kan vurderes under EU 261/2004 i kombinerte forsinkelsessaker." }]},
  { slug: "nedgradert-business-economy", title: "Nedgradert fra Business til Economy på fly", lawRef: "EU 261/2004 art. 10", cat: "flyreiser", desc: "Nedgradering gir rett på refusjon av 30-75% av billettsummen.", bodyText: "EU 261/2004 artikkel 10 gir deg eksplisitt rett til refusjon dersom flyselskapet plasserer deg i en lavere klasse enn du har betalt for. Refusjonssatsen avhenger av flyvningens lengde: 30% for flyvninger under 1 500 km, 50% for flyvninger mellom 1 500 og 3 500 km, og 75% for flyvninger over 3 500 km.\n\nRefusjonen beregnes av den totale billettsummen for den aktuelle strekningen — ikke nødvendigvis hele reisens pris. Flyselskapet plikter å tilby denne refusjonen innen 7 dager, enten kontant, som bankoverforing eller sjekk.\n\nFlyselskaper prøver noen ganger å gi 'oppgradering' på et annet flyselskaps flight som kompensasjon, eller tilby vouchers. Du er ikke forpliktet til å akseptere dette i stedet for kontant refusjon etter forordningen.", faqs: [{ q: "Flyselskapet tilbyr voucher i stedet for refusjon. Kan jeg insistere på penger?", a: "Ja. EU 261/2004 gir deg rett til kontant refusjon. Du kan avslå voucher og kreve betaling innen 7 dager." }, { q: "Jeg ble nedgradert på grunn av teknisk feil på flyet. Endrer det noe?", a: "Nei. Årsaken til nedgraderingen er irrelevant — retten til refusjon gjelder uavhengig av om flyselskapet har gyldig grunn." }, { q: "Kan jeg i tillegg kreve standardkompensasjon etter EU 261/2004?", a: "Nedgradering gir rett til refusjon etter art. 10, men ikke nødvendigvis standardkompensasjon etter art. 7. De to rettighetene gjelder for ulike situasjoner." }]},

  // FLYREISER (20 nye noder med bodyText og FAQs)
  { slug: "fly-kansellert", title: "Kansellert fly — dine rettigheter etter EU 261/2004", lawRef: "EU 261/2004 art. 5", cat: "flyreiser", desc: "Kansellert fly gir rett til standardkompensasjon på 250–600 EUR avhengig av distanse.", bodyText: "EU 261/2004 er en av Europas sterkeste forbrukervernlover og gir deg klare rettigheter ved kansellerte fly. Dersom flyselskapet kansellerer flyet ditt med kortere varsling enn 14 dager, har du rett til standardkompensasjon på 250 EUR (under 1 500 km), 400 EUR (1 500–3 500 km) eller 600 EUR (over 3 500 km).\n\nFlyselskapet kan unngå kompensasjonsplikten ved å bevise at kanselleringen skyldtes ekstraordinære omstendigheter — typisk ekstremvær, politisk uro eller streik blant lufthavnansatte. Teknisk feil på flyet regnes normalt ikke som ekstraordinær omstendighet og gir deg full kompensasjonsrett.\n\nI tillegg til kompensasjon har du alltid rett til valget mellom full refusjon av billetten eller ombooking til neste ledige avgang, samt mat og drikke under ventetiden og overnatting dersom du må vente til neste dag.", faqs: [{ q: "Flyselskapet sier kanselleringen skyldtes 'teknisk feil'. Har jeg krav på kompensasjon?", a: "Ja, teknisk feil regnes normalt ikke som ekstraordinær omstendighet. Flyselskapet må bevise at feilen var uforutsigbar og ikke kunne vært unngått ved normal vedlikehold." }, { q: "Flyet ble kansellert 10 dager før avgang. Fikk tilbud om ombooking — mister jeg kompensasjonen?", a: "Nei, retten til kompensasjon består selv om du aksepterer ombooking. Ombooking og kompensasjon er separate rettigheter." }, { q: "Kanselleringen skjedde for 2 år siden. Er det for sent å kreve?", a: "Foreldelsesfristen varierer per land — i Norge er den 3 år. Du kan fortsatt fremme kravet direkte til flyselskapet eller via klagenemnd." }]},
  { slug: "fly-forsinket", title: "Forsinket fly — kompensasjon fra 3 timers forsinkelse", lawRef: "EU 261/2004 art. 6", cat: "flyreiser", desc: "Forsinkelse over 3 timer gir rett til samme kompensasjon som ved kansellering.", bodyText: "EU-domstolen fastslo i Sturgeon-saken at forsinkelse på 3 timer eller mer ved ankomst gir rett til samme standardkompensasjon som kansellering. Dette gjelder uavhengig av årsaken til forsinkelsen — med unntak for ekstraordinære omstendigheter.\n\nDet er ankomsttidspunktet som teller, ikke avgangstidspunktet. Dersom flyet lander 2 timer og 55 minutter forsinket åpnes ikke kompensasjonsretten. Dersom det lander 3 timer og 1 minutt forsinket, har du fullt krav.\n\nVed forsinkelse har du i tillegg rett til forpleining — mat og drikke i rimelig omfang etter 2 timers forsinkelse, og overnatting dersom forsinkelsen strekker seg til neste dag.", faqs: [{ q: "Flyet var 3,5 timer forsinket pga. sein innkommende fly. Har jeg krav?", a: "Ja, dersom den innkommende forsinkelsen ikke skyldtes ekstraordinære omstendigheter. Flyselskapets operative problemer er normalt ikke ekstraordinære." }, { q: "Vi ble tilbudt voucher på 15 EUR til mat. Er det tilstrekkelig?", a: "Dersom forsinkelsen var over 2 timer har du rett til rimelig forpleining. 15 EUR kan være utilstrekkelig — krev kvitteringsdekning for rimelige måltider." }, { q: "Forsinkelsen skyldtes streik blant kabinansatte. Gir det kompensasjonsrett?", a: "Streik blant flyselskapets egne ansatte regnes normalt ikke som ekstraordinær omstendighet. Streik blant lufthavnansatte eller flygeledere kan derimot frita flyselskapet." }]},
  { slug: "innsjekking-nektet", title: "Nektet ombordstigning — boardingvegring", lawRef: "EU 261/2004 art. 4", cat: "flyreiser", desc: "Boardingvegring mot din vilje gir rett til kompensasjon og full refusjon.", bodyText: "Boardingvegring (denied boarding) oppstår når flyselskapet nekter deg å gå ombord på et fly du har gyldig billett til, typisk fordi flyet er overbooket. Dette er en av de situasjonene EU 261/2004 gir sterkest vern mot.\n\nFørst plikter flyselskapet å spørre om frivillige som mot kompensasjon er villig til å gi fra seg plassen. Dersom ingen melder seg frivillig og flyselskapet nekter deg ombordstigning mot din vilje, utløses full kompensasjonsrett — 250, 400 eller 600 EUR avhengig av distanse.\n\nDu har i tillegg rett til valget mellom full refusjon eller ombooking, samt forpleining under ventetiden. Aksepter aldri bare en voucher som kompensasjon — du har rett til kontant betaling.", faqs: [{ q: "Jeg meldte meg frivillig til å gi fra meg plassen mot voucher. Har jeg fortsatt rettigheter?", a: "Frivillig boardingvegring inngår du en avtale om. Sjekk nøye hva voucheren dekker — du kan forhandle om bedre betingelser eller kontantbetaling." }, { q: "Flyselskapet sier overbookingen skyldes en feil i systemet. Endrer det noe?", a: "Nei, årsaken til overbookingen er irrelevant. Boardingvegring mot din vilje utløser alltid kompensasjonsretten." }, { q: "Boardingvegringen ga meg 6 timers forsinkelse til destinasjonen. Kan jeg kreve begge deler?", a: "Du har rett til boardingvegringskompensasjonen. Eventuell ytterligere kompensasjon for forsinkelse er normalt inkludert i dette — ikke en separat rettighet." }]},
  { slug: "bagasje-skadet", title: "Skadet bagasje på fly — krav mot flyselskapet", lawRef: "Montreal-konvensjonen art. 17", cat: "flyreiser", desc: "Skadet innsjekket bagasje gir rett til erstatning opptil 17 000 kr.", bodyText: "Flyselskapet er ansvarlig for skader på innsjekket bagasje som oppstår under transport. Ansvaret er regulert av Montreal-konvensjonen og er begrenset oppad til SDR 1 288 — tilsvarende ca. 17 000 kr per passasjer.\n\nDu må rapportere skaden umiddelbart ved ankomst til flyselskapets bagasjeskranke og fylle ut en Property Irregularity Report (PIR). Uten PIR er det svært vanskelig å fremme krav i ettertid. Fotografer skaden grundig og behold den skadede bagasjen — kast den ikke.\n\nFlyselskapet vil normalt tilby reparasjon, erstatning eller kompensasjon. Dersom de tilbyr et for lavt beløp, kan du dokumentere gjenstandenes verdi med kvitteringer eller verdivurdering og kreve høyere erstatning.", faqs: [{ q: "Kofferten er knust men flyselskapet tilbyr bare 50 EUR. Kan jeg kreve mer?", a: "Ja, dersom kofferten har høyere verdi. Dokumenter med kjøpskvittering eller tilsvarende pris for ny koffert og krev full erstatning opptil grensen på ca. 17 000 kr." }, { q: "Innholdet i kofferten er skadet, ikke selve kofferten. Er det dekket?", a: "Ja, ansvaret gjelder alt innsjekket gods. Dokumenter innholdets verdi med kvitteringer og fotografier tatt ved pakking dersom du har det." }, { q: "Jeg oppdaget ikke skaden før dagen etter. Er det for sent å rapportere?", a: "Du har 7 dager på å rapportere skade på bagasje etter Montreal-konvensjonen. Meld fra skriftlig til flyselskapet umiddelbart selv om du ikke er ved flyplassen lenger." }]},
  { slug: "flybillett-refusjon", title: "Refusjon av flybillett — regler og rettigheter", lawRef: "EU 261/2004 art. 8", cat: "flyreiser", desc: "Ved kansellering har du alltid rett til full refusjon — uavhengig av billetttype.", bodyText: "Mange reisende er ikke klar over at retten til full refusjon ved kansellering gjelder uavhengig av om billetten er ikke-refunderbar. 'Ikke-refunderbar' gjelder kun ved frivillig avbestilling — ikke ved flyselskapets kansellering.\n\nVed kansellering kan du velge mellom: full refusjon av hele billettpakken (ikke bare den kansellerte strekningen), ombooking til neste ledige avgang på tilsvarende betingelser, eller ombooking på et senere tidspunkt du velger.\n\nVær oppmerksom på at dersom du aksepterer ombooking, mister du normalt retten til refusjon. Velg med omhu — dersom du ikke lenger trenger reisen er full refusjon ofte bedre enn ombooking.", faqs: [{ q: "Kjøpte ikke-refunderbar billett og flyselskapet kansellerte. Kan jeg få pengene tilbake?", a: "Ja, 'ikke-refunderbar' gjelder kun frivillig avbestilling. Ved flyselskapets kansellering har du alltid rett til full refusjon etter EU 261/2004 art. 8." }, { q: "Flyselskapet refunderer bare skatter og avgifter, ikke hele billettsummen. Er det riktig?", a: "Nei, du har krav på full refusjon av billettprisen inkludert alle avgifter og gebyrer du betalte. Delvis refusjon er ikke tilstrekkelig." }, { q: "Reisen gikk via mellomstopp og bare siste strekning ble kansellert. Kan jeg kreve refusjon for hele reisen?", a: "Ja, dersom kanselleringen gjør at du ikke lenger ønsker å gjennomføre reisen, kan du kreve refusjon for hele den ubrukte delen av billetten." }]},
  { slug: "ekstraordinaere-omstendigheter-fly", title: "Når kan flyselskapet nekte kompensasjon?", lawRef: "EU 261/2004 art. 5(3)", cat: "flyreiser", desc: "Ekstraordinære omstendigheter fritar flyselskapet fra kompensasjon — men bevisbyrden er deres.", bodyText: "Flyselskapet kan nekte kompensasjon ved å påberope seg 'ekstraordinære omstendigheter' — hendelser utenfor selskapets kontroll som ikke kunne vært unngått selv med alle rimelige tiltak. Bevisbyrden ligger alltid hos flyselskapet.\n\nGodkjente ekstraordinære omstendigheter inkluderer typisk: ekstremvær (storm, orkan, tykk tåke), politisk uro eller terroranslag, streik blant flygeledere eller lufthavnansatte (ikke flyselskapets egne), og luftromsrestriksjoner pålagt av myndighetene.\n\nIkke godkjente omstendigheter: teknisk feil på flyet (med mindre den skyldtes en uforutsigbar fabrikasjonsfeil), bemanningsproblemer, kommersielle beslutninger og overbooking. Dersom flyselskapet påberoper seg ekstraordinære omstendigheter, krev skriftlig dokumentasjon på hva som skjedde.", faqs: [{ q: "Flyselskapet sier forsinkelsen skyldtes 'dårlig vær' uten å spesifisere. Er det godt nok?", a: "Nei, flyselskapet må dokumentere spesifikt hvilke værforhold som oppsto, og at disse var så alvorlige at de ikke kunne vært håndtert. Vage væranførsler holder ikke." }, { q: "Flyet mitt ble forsinket fordi forrige flytur med samme fly var forsinket pga. vær. Gir det fritak?", a: "Kun dersom den opprinnelige værhendelsen var ekstraordinær og forsinkelsen var uunngåelig. Flyselskapet må bevise den direkte årsakssammenhengen." }, { q: "Flyselskapet sender standardbrev om ekstraordinære omstendigheter. Hva gjør jeg?", a: "Krev spesifikk dokumentasjon: hvilken hendelse, dato, tid og flightnummer. Vag standardtekst er ikke tilstrekkelig bevis for fritak fra kompensasjonsplikten." }]},
  { slug: "norwegian-kansellert", title: "Kansellert Norwegian-fly — rettigheter og klageprosess", lawRef: "EU 261/2004 art. 5", cat: "flyreiser", desc: "Norwegian plikter kompensasjon ved kansellering — slik fremmer du kravet.", bodyText: "Norwegian Air Shuttle er Norges største lavprisselskap og er bundet av EU 261/2004 for alle avganger fra EU/EØS-land. Norwegian har et stort volum kansjelleringer og forsinkelser og har et eget kravskjema på norwegian.com.\n\nNorwegian har historisk sett hatt lavere utbetalingsrate på kompensasjonskrav enn mange andre selskaper og avviser gjerne med tekniske begrunnelser. Erfaringsmessig er det nødvendig for mange passasjerer å eskalere til Transportklagenemnda.\n\nNorwegian opererer med ulike selskapsstrukturer i ulike land — sjekk at du henvender deg til riktig enhet (Norwegian Air Shuttle ASA for norske avganger). Behold all dokumentasjon: boardingkort, booking-bekreftelse og eventuell melding om kansellering.", faqs: [{ q: "Norwegian kansellerte og tilbyr ombooking 2 dager senere. Kan jeg kreve refusjon i stedet?", a: "Ja, du kan alltid velge refusjon fremfor ombooking. Norwegian kan ikke tvinge deg til å akseptere sen ombooking." }, { q: "Norwegian er konkurs/under restrukturering. Kan jeg fortsatt kreve kompensasjon?", a: "Krav kan meldes i konkursboet. For fremtidige avganger — sjekk reiseforsikringen og kredittkortforsikringen din for dekning ved flyselskapskonkurs." }, { q: "Bestilte via reisebyrå. Skal jeg klage til Norwegian eller byrået?", a: "Klag direkte til Norwegian — de er ansvarlig etter EU 261/2004 uavhengig av hvor billetten ble kjøpt. Reisebyrået er kun mellomledd." }]},
  { slug: "forsinkelse-tilkobling", title: "Mistet tilkoblingsflyging pga. forsinkelse", lawRef: "EU 261/2004 art. 6", cat: "flyreiser", desc: "Mistet tilkobling gir rett til kompensasjon dersom hele reisen er booket på én billett.", bodyText: "Dersom du mister et tilkoblingsflyging fordi det første flyet var forsinket, avhenger rettighetene dine av om reisen er booket på én sammenhengende billett eller som to separate bestillinger.\n\nEr alt booket på én billett: flyselskapet er ansvarlig for å bringe deg til endelig destinasjon og kompensasjon beregnes basert på total forsinkelse til endelig bestemmelsessted — ikke til mellomlandingsstedet. Dette er den viktigste regelen mange ikke kjenner til.\n\nEr billettene separate: du har ingen automatisk rettighet mot flyselskapet for mistet tilkobling. Du må kjøpe ny billett for siste strekning for egen regning. Sjekk om reiseforsikringen dekker dette.", faqs: [{ q: "Hadde to separate billetter og mistet tilkoblingen. Hva gjør jeg?", a: "Kjøp ny billett til endelig destinasjon og krev dekning fra reiseforsikringen. Flyselskapet for det forsinkede flyet har intet ansvar for separate billetter." }, { q: "Alt var på én billett og jeg mistet tilkoblingen. Flyselskapet sier jeg må kjøpe ny billett selv.", a: "Feil. Med én billett plikter flyselskapet å booke deg om til neste ledige avgang vederlagsfritt og kompensere for forsinkelsen til endelig destinasjon." }, { q: "Hadde 3 timers mellomlandingstid og mistet likevel tilkoblingen. Er det flyselskapets feil?", a: "Dersom alt var på én billett og flyselskapet solgte tilkoblingen som gyldig, ja. Flyselskapet er ansvarlig selv om mellomlandingstiden var lang." }]},
  { slug: "flyplass-rettigheter", title: "Rettigheter på flyplassen ved forsinkelse og kansellering", lawRef: "EU 261/2004 art. 9", cat: "flyreiser", desc: "Du har rett til mat, drikke og overnatting ved lange forsinkelser.", bodyText: "EU 261/2004 artikkel 9 gir deg rett til forpleining uavhengig av om du har rett til standardkompensasjon. Disse rettighetene gjelder fra det øyeblikket flyselskapet vet om forsinkelsen eller kanselleringen.\n\nVed forsinkelse over 2 timer (kortdistanse) eller 3 timer (langdistanse): rett til mat og drikke i rimelig omfang. Ved forsinkelse til neste dag: rett til hotellovernatting og transport til/fra hotellet. Du har også alltid rett til å ringe to telefonsamtaler eller sende to e-poster på flyselskapets regning.\n\nDersom flyselskapet ikke tilbyr dette, kan du ordne det selv og kreve rimelige utgifter refundert. Ta vare på alle kvitteringer. 'Rimelig' betyr normalt ikke luksusmiddag — hold deg til normale priser for stedet.", faqs: [{ q: "Flyselskapet tilbød bare en voucher på 10 EUR til mat under 5 timers forsinkelse. Er det nok?", a: "Sannsynligvis ikke. Krev dekning for rimelige faktiske utgifter til mat og drikke. Behold kvitteringer og krev differansen refundert." }, { q: "Flyselskapet nekter å betale hotellet og sier jeg skal ordne det selv og søke refusjon. Er det lovlig?", a: "Ja, flyselskapet kan velge denne løsningen. Bestill rimelig hotell, ta vare på kvitteringen, og krev refusjon med en gang du er hjemme." }, { q: "Forsinkelsen skyldes ekstraordinære omstendigheter. Har jeg fortsatt rett til mat og overnatting?", a: "Ja, retten til forpleining (mat, overnatting) gjelder uavhengig av årsaken til forsinkelsen — selv om kompensasjonsretten bortfaller." }]},
  { slug: "pakketour-rettigheter", title: "Rettigheter ved flyproblemer på pakketur", lawRef: "Pakkereiseloven § 26", cat: "flyreiser", desc: "Pakkereiser gir sterkere rettigheter — du forholder deg til turoperatøren, ikke flyselskapet.", bodyText: "Dersom flyet inngår i en pakkereise kjøpt hos et reisebyrå eller turoperatør, er det pakkereiseloven som gir deg det sterkeste vernet — ikke bare EU 261/2004. Turoperatøren er ansvarlig for hele pakken, inkludert fly, hotell og transfer.\n\nVed kansellert fly på pakkereise har du rett til alternativ transport, og dersom turoperatøren ikke kan skaffe dette, kan du heve kjøpet og kreve full refusjon av hele pakkens pris. Du kan i tillegg kreve erstatning for dokumenterte tap.\n\nHenvend deg alltid til turoperatøren, ikke flyselskapet, ved problemer på pakkereise. Turoperatøren har ansvar for å koordinere løsninger og kan ikke sende deg videre til flyselskapet.", faqs: [{ q: "Flyselskapet kansellerte flyet på pakketuren min. Skal jeg kontakte flyselskapet eller reisebyrået?", a: "Reisebyrået/turoperatøren. De har totalansvar for pakken og plikter å løse problemet for deg." }, { q: "Turoperatøren tilbyr alternativt fly som ankommer 2 dager etter opprinnelig plan. Kan jeg avslå?", a: "Ja, dersom avviket er vesentlig kan du heve pakken og kreve full refusjon. 2 dager kortere ferie er normalt vesentlig avvik." }, { q: "Kan jeg kreve kompensasjon etter EU 261/2004 i tillegg til erstatning etter pakkereiseloven?", a: "Ja, rettighetene er kumulative. Du kan kreve EU 261/2004-kompensasjon fra flyselskapet og erstatning fra turoperatøren for det samme hendelsesforløpet." }]},
  { slug: "transportklagenemnda", title: "Slik klager du til Transportklagenemnda", lawRef: "EU 261/2004 art. 16", cat: "flyreiser", desc: "Transportklagenemnda behandler flyklager gratis og gir bindende avgjørelser.", bodyText: "Transportklagenemnda (TKN) er det norske klageorganet for fly-, tog-, buss- og båtreiser. For flyreiser behandler TKN klager gratis og gir avgjørelser som flyselskaper bundet av norsk regulering er forpliktet til å følge.\n\nFør du kan klage til TKN må du ha klaget direkte til flyselskapet og fått avslag eller ikke hørt noe på 8 uker. Ha klar: booking-bekreftelse, boardingkort, korrespondanse med flyselskapet, kvitteringer for utgifter og dokumentasjon på forsinkelse/kansellering.\n\nKlagen sendes digitalt via TKNs nettside. Saksbehandlingstiden er typisk 3–6 måneder. TKNs avgjørelser er bindende for flyselskaper som er tilsluttet nemnda — de aller fleste store selskaper er det.", faqs: [{ q: "Flyselskapet er ikke norsk. Kan jeg klage til Transportklagenemnda?", a: "Ja, dersom avgangen gikk fra norsk flyplass. For avganger til Norge med ikke-EU-selskap kan det hende du må klage i avreiselandet." }, { q: "TKN ga meg medhold men flyselskapet betaler ikke. Hva gjør jeg?", a: "TKNs avgjørelse kan tvangsfullbyrdes via namsmannen uten ny rettssak. Kontakt namsmannen med avgjørelsen som grunnlag." }, { q: "Kan jeg klage til TKN selv om jeg brukte en kompensasjonstjeneste?", a: "Dersom du har overdratt kravet til kompensasjonstjenesten, kan de klage på dine vegne. Dersom du ikke har overdratt kravet kan du klage selv." }]},
  { slug: "flystreik-rettigheter", title: "Rettigheter ved flystreik og arbeidskonflikter", lawRef: "EU 261/2004 art. 5(3)", cat: "flyreiser", desc: "Flyselskapets egne streiker gir normalt ikke fritak fra kompensasjonsplikten.", bodyText: "Streik er et av de mest omdiskuterte temaene i flypassasjerrettigheter. EU-domstolen har slått fast at streik blant flyselskapets egne ansatte — piloter, kabinpersonale — ikke nødvendigvis er en ekstraordinær omstendighet som fritar fra kompensasjonsplikt.\n\nStandpunktet er at flyselskaper bør forutse risikoen for arbeidskonflikter og treffe tiltak for å minimere konsekvensene for passasjerene. Streik varslet i god tid er særlig vanskelig å bruke som fritaksgrunn.\n\nDerimot anses streik blant flygeledere, lufthavnansatte (security, bakketjeneste) og andre aktører utenfor flyselskapets kontroll normalt som ekstraordinære omstendigheter. Flyselskapet må under enhver omstendighet dokumentere og bevise at streiken var ekstraordinær — generell påstand holder ikke.", faqs: [{ q: "SAS/Norwegian streiker og mitt fly er kansellert. Har jeg krav på kompensasjon?", a: "Muligens ja. Streik blant egne ansatte er juridisk omdiskutert men anses av mange domstoler ikke som ekstraordinær omstendighet. Klag uansett — du kan vinne frem." }, { q: "Flygelederstreik kansellerte flyet mitt. Gir det kompensasjonsrett?", a: "Normalt nei, da dette er utenfor flyselskapets kontroll. Men du har fortsatt rett til refusjon eller ombooking, samt forpleining." }, { q: "Streiken var kjent 3 uker før avgangen. Hvorfor varslet ikke flyselskapet meg?", a: "Flyselskapet plikter å varsle om kansellering senest 14 dager før for å unngå kompensasjonsplikt. Kansellering med kortere varsel utløser kompensasjonsrett uavhengig av årsak." }]},
  { slug: "covid-kansellering-fly", title: "Kansellert fly pga. Covid-19 — utestående refusjoner", lawRef: "EU 261/2004 art. 8", cat: "flyreiser", desc: "Covid-kanselleringer gir rett til refusjon — ikke bare voucher.", bodyText: "Mange flyselskaper tilbød under pandemien vouchers i stedet for kontantrefusjon ved Covid-kansjelleringer. Vouchers er ikke tilstrekkelig etter EU 261/2004 — du hadde og har rett til kontant refusjon.\n\nDersom du aksepterte en voucher under press eller uten å forstå at du hadde rett til penger, kan du i mange tilfeller fortsatt kreve kontant utbetaling — særlig dersom voucheren ennå ikke er utløpt. EU-kommisjonen har presisert at flyselskaper ikke kan erstatte lovfestede refusjonsrettigheter med vouchers.\n\nDersom flyselskapet er konkurs (f.eks. Flybe, Air Berlin, WOW Air) er situasjonen vanskeligere — krav meldes i konkursboet. Sjekk om du betalte med kredittkort og om kortselskapet kan tilbakeføre betalingen (chargeback).", faqs: [{ q: "Aksepterte voucher under Covid. Kan jeg nå kreve penger i stedet?", a: "Muligens, dersom voucheren ennå ikke er utløpt og du kan argumentere for at du ikke forstod at du hadde rett til kontant refusjon. Krev det skriftlig av flyselskapet." }, { q: "Flyselskapet som kansellerte er nå konkurs. Hva gjør jeg?", a: "Meld kravet i konkursboet. Betalte du med kredittkort, kontakt kortselskapet umiddelbart for chargeback — dette er ofte raskere og mer effektivt." }, { q: "Fikk ikke refusjon for over 2 år siden. Er det foreldet?", a: "I Norge er foreldelsesfristen 3 år. Dersom det er gått under 3 år siden kanselleringen kan du fortsatt fremme kravet — gjør det umiddelbart." }]},
  { slug: "eu261-tredjeland", title: "Gjelder EU 261/2004 for fly utenfor Europa?", lawRef: "EU 261/2004 art. 3", cat: "flyreiser", desc: "EU 261/2004 gjelder fra EU/EØS-flyplasser og med EU-selskaper til Europa.", bodyText: "EU 261/2004 gjelder for alle avganger fra flyplasser i EU/EØS-land, uavhengig av flyselskap. Den gjelder også for EU/EØS-baserte flyselskaper på flyvninger til EU/EØS fra tredjeland.\n\nPraktisk betyr dette: Alle avganger fra Oslo, Bergen, Stockholm, London osv. er dekket uavhengig av om du flyr med SAS, Norwegian, Emirates eller Ryanair. Men en Emirates-flight fra Dubai til Oslo er ikke dekket — fordi avgangen er fra utenfor EU/EØS og Emirates er ikke EU-basert.\n\nFor flyvninger utenfor EU/EØS gjelder Montreal-konvensjonen for bagasje og forsinkelse, men den gir ikke standardkompensasjon. Sjekk om landet du flyr fra har egne forbrukervernlover for flypassasjerer.", faqs: [{ q: "Flyr med Turkish Airlines fra Istanbul til Oslo. Gjelder EU 261/2004?", a: "Nei, avgangen er fra utenfor EU/EØS og Turkish Airlines er ikke EU-basert. Montreal-konvensjonen gjelder for bagasje, men ikke standardkompensasjon." }, { q: "Flyr med British Airways fra London til New York. Gjelder EU 261/2004?", a: "Ja for avgangen fra London (EU/EØS), og British Airways er EU-basert. EU 261/2004 gjelder for denne avgangen." }, { q: "Har jeg rettigheter i USA ved kansellert innenriksfly?", a: "USA har egne regler som delvis ligner EU 261/2004 for boardingvegring, men ikke for kansellering og forsinkelse. Sjekk DOT (Department of Transportation) sine regler." }]},
  { slug: "bagasje-tapt", title: "Tapt bagasje på fly — erstatning og prosess", lawRef: "Montreal-konvensjonen art. 17", cat: "flyreiser", desc: "Bagasje erklært tapt etter 21 dager gir rett til erstatning opptil 17 000 kr.", bodyText: "Bagasje som ikke ankommer innen 21 dager etter planlagt ankomst regnes som tapt etter Montreal-konvensjonen. Da endres statusen fra 'forsinket' til 'tapt' og erstatningsretten øker tilsvarende.\n\nFor å dokumentere tapets omfang bør du lage en detaljert liste over alt innholdet med estimert verdi. Kvitteringer er ideelle, men ikke alltid nødvendige — flyselskapet kan ikke kreve kvittering for hvert enkelt plagg. En rimelig verdivurdering basert på alder og tilstand er tilstrekkelig.\n\nErstatningsgrensen er SDR 1 288 (ca. 17 000 kr) per passasjer — ikke per koffert. Dersom du reiste to stykker med tapt bagasje kan dere kreve opptil 34 000 kr til sammen.", faqs: [{ q: "Bagasjen er borte etter 10 dager. Er den erklært tapt?", a: "Ikke ennå — tapt-status inntrer etter 21 dager. Du kan allerede nå kjøpe nødvendige gjenstander på flyselskapets regning og dokumentere utlegg." }, { q: "Flyselskapet tilbyr 200 EUR for tapt koffert med innhold verdt 800 EUR. Kan jeg kreve mer?", a: "Ja, dokumenter innholdets verdi og krev høyere erstatning opptil konvensjonsgrensen på ca. 17 000 kr." }, { q: "Bagasjen ble tapt på transferflyplassen. Hvilket flyselskap er ansvarlig?", a: "Det siste flyselskapet som sjekket inn bagasjen er primæransvarlig. Krev PIR-rapport ved ankomst og klag til det opererende flyselskapet på siste strekning." }]},
  { slug: "fly-overbooket", title: "Overbooket fly — dine rettigheter og kompensasjon", lawRef: "EU 261/2004 art. 4", cat: "flyreiser", desc: "Overbooking gir rett til kompensasjon på 250–600 EUR ved ufrivillig boardingvegring.", bodyText: "Overbooking er en bevisst kommersiell praksis der flyselskaper selger flere billetter enn flyet har seter, basert på statistikk over no-shows. EU 261/2004 gir deg sterk beskyttelse dersom du rammes.\n\nFlyselskapet plikter alltid først å spørre om frivillige som mot kompensasjon vil gi fra seg plassen. Dersom ikke nok frivillige melder seg, og flyselskapet nekter deg ombordstigning, utløses full kompensasjonsrett — 250, 400 eller 600 EUR — pluss valget mellom refusjon og ombooking.\n\nVed overbooking kan du forhandle godt ved frivillig avgåelse — flyselskapet er motivert til å tilby gode betingelser for å unngå tvungen boardingvegring. Be om kontant kompensasjon, ikke bare voucher, og sørg for skriftlig bekreftelse av avtalen.", faqs: [{ q: "Flyselskapet ga meg ny avgang 4 timer senere pga. overbooking. Har jeg krav på kompensasjon?", a: "Ja, dersom du ble nektet ombordstigning mot din vilje. Selv med ombooking har du rett til kompensasjon — de to er separate rettigheter." }, { q: "Meldte meg frivillig og fikk voucher på 200 EUR. Kan jeg kreve mer?", a: "Dersom du frivillig aksepterte voucheren er det normalt bindende. Neste gang — forhandle om kontant kompensasjon og be om høyere beløp, de ønsker frivillige." }, { q: "Flyselskapet sier det var en 'teknisk overbooking'. Endrer det noe?", a: "Nei, årsaken til overbookingen er irrelevant. Ufrivillig boardingvegring utløser alltid kompensasjonsretten uavhengig av hva flyselskapet kaller det." }]},
  { slug: "reiseforsikring-fly", title: "Reiseforsikring og flyrettigheter — hva dekkes?", lawRef: "EU 261/2004 art. 8", cat: "flyreiser", desc: "Reiseforsikring og EU 261/2004 er komplementære — bruk begge.", bodyText: "Mange reisende vet ikke at de har dobbelt vern ved flyproblemer: EU 261/2004 og reiseforsikringen. Disse rettighetene er ikke gjensidig utelukkende — du kan bruke begge.\n\nEU 261/2004 dekker: standardkompensasjon ved forsinkelse/kansellering, forpleining under ventetid, og refusjon/ombooking. Reiseforsikringen kan dekke: tap utover EU-kompensasjonen, utgifter ved kansellering av andre årsaker (sykdom, familiedød), forsinkelseskostnader som ikke dekkes av EU-reglene og bagasjeproblemer.\n\nVed krav — fremme alltid EU 261/2004-kravet direkte mot flyselskapet først. Forsikringsselskapet vil uansett regresskrve flyselskapet for det EU 261/2004 skal dekke. Forsikringen er relevant for det EU-regelverket ikke dekker.", faqs: [{ q: "Reiseforsikringen krever at jeg legger ut og søker refusjon. Er det riktig?", a: "Ja, for forsikringsdekning er det normalt krav om at du dokumenterer utgiftene og søker refusjon. Behold alle kvitteringer og fremme krav innen forsikringens frister." }, { q: "Flyselskapet betalte 400 EUR kompensasjon men jeg tapte 1 000 EUR totalt. Dekker forsikringen resten?", a: "Avhenger av forsikringsvilkårene. Mange reiseforsikringer dekker dokumenterte tap utover det flyselskapet betaler — sjekk vilkårene dine." }, { q: "Brukte kredittkort til å kjøpe billetten. Har kortet reiseforsikring?", a: "Mange kredittkort inkluderer reiseforsikring — sjekk vilkårene for ditt kort. Kortforsikring kan dekke forsinkelse, kansellering og bagasjetap." }]},
  { slug: "flyselskap-konkurs", title: "Flyselskapet gikk konkurs — hva gjør du?", lawRef: "Montreal-konvensjonen art. 19", cat: "flyreiser", desc: "Ved flyselskapskonkurs — sjekk kredittkort, reiseforsikring og ATOL-dekning.", bodyText: "Dersom flyselskapet ditt går konkurs er situasjonen krevende — du har normalt ikke rett til EU 261/2004-kompensasjon fordi selskapet ikke lenger kan betale. Men du har andre muligheter.\n\nBetalte du med kredittkort: kontakt kortselskapet umiddelbart og be om chargeback (tilbakeføring av betaling). Dette er svært effektivt og kan gi deg pengene tilbake raskt. Fristen for chargeback varierer — normalt 120 dager fra kjøpet.\n\nATOL-dekning (for UK-kjøpte pakker) og andre garantiordninger kan gi dekning. Norske pakker kan ha tilsvarende reisegaranti. Meld krav i konkursboet for fullstendig refusjon — men dette er en langsom prosess.", faqs: [{ q: "Flyselskapet er konkurs og jeg har ubrukte billetter. Hva gjør jeg umiddelbart?", a: "1) Kontakt kortselskapet for chargeback umiddelbart. 2) Sjekk reiseforsikringen. 3) Meld krav i konkursboet. Gjør alt parallelt — ikke vent." }, { q: "Er allerede på destinasjonen og flyselskapet gikk konkurs. Hvordan kommer jeg hjem?", a: "Kjøp ny hjemreise og behold kvitteringen. Krev refusjon fra reiseforsikring og konkursboet. EU-flyplasser har beredskapsordninger — sjekk med flyplassadministrasjonen." }, { q: "Reiseforsikringen dekker ikke flyselskapskonkurs. Hva da?", a: "Kredittkort-chargeback er da det viktigste alternativet. Meld krav i konkursboet, men forvent lang ventetid og muligens bare delvis refusjon." }]},
  { slug: "spesielle-behov-fly", title: "Rettigheter for passasjerer med nedsatt funksjonsevne", lawRef: "EU 1107/2006", cat: "flyreiser", desc: "Passasjerer med nedsatt funksjonsevne har rett til gratis assistanse på flyplassen.", bodyText: "EU-forordning 1107/2006 gir passasjerer med nedsatt funksjonsevne rett til gratis assistanse på flyplasser og om bord i fly. Dette inkluderer rullestolbrukere, blinde, hørselshemmede og alle som trenger hjelp til å bevege seg gjennom flyplassen.\n\nAssistansen er flyplassens ansvar — ikke flyselskapets — og finansieres gjennom et gebyr på alle passasjerer. Du trenger ikke betale ekstra for assistansen. Meld fra til flyselskapet om behovet senest 48 timer før avgang, og bekreft ved innsjekking.\n\nDersom flyplassen eller flyselskapet nekter å gi assistanse, eller skader hjelpemidler som rullestol, har du rett til erstatning og kan klage til Luftfartstilsynet eller Transportklagenemnda.", faqs: [{ q: "Flyplassen hadde ikke rullestol tilgjengelig og vi mistet flyet. Hvem er ansvarlig?", a: "Flyplassen er ansvarlig for assistansen. Klag til flyplassoperatøren og Luftfartstilsynet. Du kan i tillegg ha krav mot flyselskapet for mistet avgang." }, { q: "Rullestolen ble skadet under transport. Hva kan jeg kreve?", a: "Erstatning for reparasjon eller erstatning av rullestolen etter Montreal-konvensjonen. Rapporter skaden umiddelbart ved ankomst og dokumenter med bilder." }, { q: "Flyselskapet nektet å ta med min elektriske rullestol. Er det lovlig?", a: "Kun dersom det er legitime sikkerhetsårsaker knyttet til batteriet. Flyselskapet må begrunne avvisningen konkret. Vag sikkerhetsanføring er ikke tilstrekkelig." }]},
  { slug: "fly-dokumentasjon", title: "Slik dokumenterer du flykravet ditt", lawRef: "EU 261/2004 art. 5", cat: "flyreiser", desc: "God dokumentasjon er avgjørende for å vinne frem med flykravet ditt.", bodyText: "De fleste tapte flykrav skyldes mangelfull dokumentasjon, ikke manglende rettslig grunnlag. Flyselskaper vet at passasjerer uten dokumentasjon sjelden vinner frem, og avviser krav de egentlig er forpliktet til å betale.\n\nDette bør du alltid ta vare på: boardingkort (fysisk eller skjermbilde av digital), booking-bekreftelse med flightnummer og tidspunkt, melding om kansellering/forsinkelse fra flyselskapet (ta skjermbilde), kvitteringer for alle utlegg på flyplassen (mat, overnatting, transport) og korrespondanse med flyselskapet.\n\nFoto av avgangstavlen som viser forsinkelse med tidsstempel er verdifullt. Skjermbilde av Flightradar24 eller lignende app som bekrefter faktisk ankomsttid er ofte avgjørende dokumentasjon i klagesaker.", faqs: [{ q: "Kastet boardingkortet etter reisen. Kan jeg fortsatt dokumentere forsinkelsen?", a: "Ja, booking-bekreftelsen og flightdata fra Flightradar24 kan erstatte boardingkortet. Flyselskapet har også plikt til å fremlegge informasjon om sin egen flight." }, { q: "Flyselskapet sier flyet ikke var forsinket. Jeg vet det var det. Hva gjør jeg?", a: "Hent faktisk ankomstdata fra Flightradar24.com eller lignende tjeneste. Disse dataene er offentlig tilgjengelige og bindende som bevis." }, { q: "Har ingen kvitteringer fra flyplassen. Kan jeg kreve forpleiningsutgifter?", a: "Det er vanskelig uten kvitteringer. Uten dokumentasjon kan du bare kreve standardkompensasjonen — ikke refusjon av faktiske utgifter. Behold alltid kvitteringer." }]},

  // MC-KJØP (18 noder) — URL: /mc-kjop/[slug]
  { slug: "mc-rammeskade-skjult", title: "Skjult rammeskade på motorsykkel", lawRef: "KL § 18", cat: "mc-kjop", desc: "Skjult rammeskade etter velt er svik og gir rett til heving.", bodyText: "Rammeskader på MC er sikkerhetskritiske — en sykkel med skadet ramme kan oppføre seg uforutsigbart og forårsake alvorlige ulykker. Dersom selger skjulte en rammeskade etter velt, er det svik etter kjøpsloven § 18 og gir deg ubetinget rett til heving.\n\nTegn på skjult rammeskade: sykkelen trekker til siden ved kjøring, skjev styring, unormal dekkslitasje, spor etter sveising eller reparasjon på rammen og skjeve overensstemmelsesindikatorer mellom front og bakhjul. En MC-mekaniker med rammemålingsutstyr kan fastslå om rammen er rett.\n\nRammeskader kan også ha konsekvenser for typegodkjenningen — en MC med skadet ramme kan miste EU-godkjenningen og være ulovlig å registrere. Dette forsterker hevingsgrunnlaget ytterligere.", faqs: [{ q: "Selger nekter for rammeskade. Hvordan beviser jeg det?", a: "En MC-mekaniker med lasermålingsutstyr kan dokumentere rammeskjevhet. Spor etter sveising og reparasjoner er også bevis. Be om skriftlig rapport." }, { q: "MC-en er EU-godkjent. Betyr det at rammen er rett?", a: "Ikke nødvendigvis. EU-kontroll kontrollerer ikke alltid rammegeometri i detalj. En faglig inspeksjon er mer pålitelig." }, { q: "Kan jeg kreve heve kjøpet selv om MC-en kjører greit?", a: "Ja, skjult skadehistorikk som selger ikke opplyste om er svik uavhengig av sykkelen nåværende kjøreadferd. Verdien er redusert og hevingsretten er klar." }]},
  { slug: "mc-ulovlig-trimmet", title: "Kjøpt ulovlig trimmet MC uten å vite det?", lawRef: "KL § 18", cat: "mc-kjop", desc: "Ulovlig trimming som ikke ble opplyst om er svik og gir hevingsrett.", bodyText: "Å kjøpe en motorsykkel som viser seg å være ulovlig trimmet uten at dette ble opplyst om, er et alvorlig kjøpsrettslig problem. Ulovlig trimming kan gjøre MC-en uregistrerbar, uforsikringsbar og ulovlig å kjøre på vei. I tillegg kan det ugyldiggjøre garantier og typegodkjenning.\n\nEtter kjøpsloven § 18 foreligger mangel dersom selger har gitt uriktige opplysninger eller holdt tilbake opplysninger som kjøper hadde grunn til å forvente. Ulovlig trimming er informasjon selger plikter å opplyse om — det er svik å selge en MC som lovlig når den ikke er det.\n\nFå en verkstedrapport som dokumenterer trimmingen og omfanget. Kontakt Statens vegvesen for å avklare om MC-en kan tilbakeføres til lovlig stand og hva dette koster. Dersom tilbakeføring er umulig eller uforholdsmessig dyrt, er heving det naturlige kravet.", faqs: [{ q: "MC-en er trimmet men selger sa den var original. Kan jeg heve kjøpet?", a: "Ja, dette er brudd på opplysningsplikten og muligens svik. Ulovlig trimming som gjør MC-en ulovlig å kjøre er en vesentlig mangel." }, { q: "Kan jeg lovliggjøre MC-en og kreve kostnadene av selger?", a: "Ja, du kan kreve utbedringskostnadene dekket. Dersom kostnadene er uforholdsmessige, kan du isteden kreve heving." }, { q: "Trimmet MC uten at det er registrert hos Vegvesenet. Kan jeg bli straffet?", a: "Du kan i utgangspunktet ikke straffes for å kjøre en MC du ikke visste var ulovlig trimmet. Men når du har fått kunnskap, må du slutte å kjøre den på vei inntil den er lovliggjort." }] },
  { slug: "mc-motorbank-ulyd", title: "Ulyd og motorbank på MC: Reklamasjon", lawRef: "KL § 39", cat: "mc-kjop", desc: "Motorbank kort tid etter kjøp presumeres å være skjult mangel.", bodyText: "Motorbank eller ulyd fra en MC-motor er et bekymringsfullt tegn som kan indikere alt fra slitte ventiler og kamkjede til alvorlige lagerskader. Motorskader på MC kan koste fra 5 000 kr for enkle justeringer til 30 000+ kr for lagerskifte eller motoroverhaul.\n\nEtter kjøpsloven § 39 presumeres feil som viser seg kort tid etter kjøpet å ha eksistert ved overlevering. En motor som banker etter noen dagers bruk har med all sannsynlighet hatt latente skader ved salget. Selger kan ikke avvise reklamasjonen med henvisning til at MC-motorer alltid lager litt lyd.\n\nFå en MC-mekaniker til å lytte på motoren og gi en skriftlig vurdering av lydkilden og estimert utbedringskostnad. Et stethoskop eller elektronisk lydinstrument kan lokalisere kilden presist. Reklamér skriftlig til selger med vedlagt verkstedrapport.", faqs: [{ q: "Motoren tikker på kald motor. Er det normalt?", a: "Noe ventiltikking på kald motor kan være normalt for visse MC-typer. Men kraftig banking som ikke forsvinner ved driftstemperatur er en mangel." }, { q: "Selger sier motorlyd er 'sjarm' på denne MC-typen. Har han rett?", a: "Noen MC-er har karakteristisk motorlyd, men unormal banking eller ulyd er en mangel. Sammenlign med tilsvarende MC-er for å vurdere om lyden er avvikende." }, { q: "Verkstedet sier motoren trenger full overhaul. Kan jeg heve kjøpet?", a: "Ja, dersom overhaul-kostnaden er vesentlig i forhold til kjøpesummen, oppfylles vesentlighetskravet for heving." }] },
  { slug: "mc-simmerringer-lekkasje", title: "Lekkasje i dempere (simmerringer) etter MC-kjøp", lawRef: "KL § 17", cat: "mc-kjop", desc: "Lekkende simmerringer som ikke ble opplyst om er reklamasjonsgrunnlag.", bodyText: "Simmerringer i MC-ens forgaffel og dempere sørger for at olje holdes inne i dempersystemet. Lekkende simmerringer fører til dårligere demping, oljeflekkete gaffelrør og potensielt farlige kjøreegenskaper. Utbedring koster typisk 3 000–8 000 kr avhengig av MC-type og om det er forgaffel eller bakdempere.\n\nEtter kjøpsloven § 17 foreligger mangel dersom MC-en ikke har de egenskaper kjøper hadde grunn til å forvente. Lekkende simmerringer er en synlig defekt som selger burde ha oppdaget og opplyst om. Selv om simmerringer er slitedeler, forventes det at de er i akseptabel stand ved levering.\n\nDokumenter lekkasjen med bilder av oljerester på gaffelrør og dempere. Få verkstedrapport som bekrefter at simmerringene er utslitte og at lekkasjen var til stede ved kjøpet. Reklamér skriftlig og krev utbedring for selgers regning.", faqs: [{ q: "Forgaffelen lekker litt olje. Er det nok til å reklamere?", a: "Ja, enhver lekkasje er en mangel. Selv liten lekkasje forverres raskt og påvirker demperfunksjonen." }, { q: "Selger sier simmerringer er slitedeler og mitt ansvar. Stemmer det?", a: "Slitedeler skal likevel være i akseptabel stand ved levering. Lekkende simmerringer som ikke ble opplyst om er selgers ansvar." }, { q: "Kan lekkende simmerringer være farlig?", a: "Ja, olje på gaffelrør kan sprute på bremseskive eller dekk og redusere bremsekraft og veigrep drastisk. Det er et sikkerhetsanliggende." }] },
  { slug: "mc-elektrisk-feil", title: "Gjentatte elektriske feil på MC etter kjøp", lawRef: "KL § 39", cat: "mc-kjop", desc: "Elektriske feil som var latente ved kjøp gir rett til reklamasjon.", bodyText: "Elektriske feil på MC kan manifestere seg som startproblemer, lyssvikt, uregelmessig tenning, defekte instrumenter eller sporadisk strømtap. Slike feil er vanskelige å diagnostisere og kan koste 3 000–15 000 kr å utbedre avhengig av om det er kablage, styringsenhet eller generator/regulator.\n\nEtter kjøpsloven § 39 presumeres feil som viser seg kort tid etter kjøpet å ha vært latente ved overlevering. Elektriske feil som viser seg innen de første månedene etter kjøpet er med overveiende sannsynlighet feil som forelå — om enn skjult — ved salget.\n\nFå en MC-elektriker til å feilsøke systematisk og dokumentere funnene skriftlig. OBD-utlesning (dersom MC-en har dette) kan gi verdifull informasjon om feilhistorikk. Reklamér skriftlig med vedlagt feilsøkingsrapport og krev utbedring for selgers regning.", faqs: [{ q: "MC-en stopper tilfeldig under kjøring. Er det en mangel?", a: "Ja, sporadisk motorstopp er sikkerhetskritisk og en klar mangel. Reklamér umiddelbart og krev feilsøking for selgers regning." }, { q: "Lyset flimrer av og på. Er det reklamasjonsgrunnlag?", a: "Ja, ustabilt lys kan skyldes defekt generator/regulator, dårlige koblinger eller slitt kabelstamme — alt er reklamasjonsgrunnlag." }, { q: "Elektrisk feil oppstår bare når det regner. Hva gjør jeg?", a: "Fuktrelaterte elektriske feil tyder på dårlig tetting eller skadet kablage. Dokumenter sammenhengen mellom regn og feil, og reklamér." }] },
  { slug: "mc-abs-feil", title: "Defekt ABS-system på brukt MC", lawRef: "KL § 17", cat: "mc-kjop", desc: "ABS-feil er sikkerhetskritisk og gir sterk reklamasjonsrett.", bodyText: "ABS-systemet (blokkeringsfritt bremsesystem) er sikkerhetsutstyr som hindrer hjulene i å låse seg under hard bremsing. En MC med defekt ABS er farligere å kjøre, og feilen er spesielt kritisk i vått føre og nødsituasjoner. ABS-feil kan skyldes defekte sensorer, hydraulikkproblemer eller elektronikkfeil.\n\nEtter kjøpsloven § 17 har MC-en en mangel dersom ABS-systemet ikke fungerer som det skal. ABS er sikkerhetskritisk utstyr som er lovpålagt på nye MC-er fra 2017, og en defekt er en alvorlig mangel som gir sterk reklamasjonsrett — potensielt hevingsrett.\n\nDokumenter ABS-feilen med bilder av eventuell varsellampe og få verkstedrapport med feilkodeutlesning og estimert utbedringskostnad. ABS-reparasjoner kan koste 5 000–20 000 kr avhengig av om det er sensor, pumpe eller styreenhet som er defekt.", faqs: [{ q: "ABS-lampen lyser. Er MC-en trygg å kjøre?", a: "Nei, ABS-systemet kan være deaktivert. Bremsene fungerer trolig fortsatt men uten blokkeringshindring, noe som øker ulykkesrisikoen." }, { q: "Er defekt ABS nok til å heve kjøpet?", a: "Ja, ABS er sikkerhetskritisk utstyr. Dersom feilen er kostbar å utbedre og ikke ble opplyst om, er heving aktuelt." }, { q: "Selger sier MC-en ikke hadde ABS originalt. Hvordan sjekker jeg?", a: "Sjekk typegodkjenningen eller kontakt importøren med chassisnummer. Dersom ABS er oppført i spesifikasjonene, skal det fungere." }] },

  // MC-KJØP (9 nye noder med FAQs)
  { slug: "mc-clutch-sluring", title: "Clutch-sluring på brukt MC: Reklamasjon", lawRef: "KL § 39", cat: "mc-kjop", desc: "Clutch som slipper for tidlig er slitasjerelatert men kan være skjult mangel ved kjøp.", bodyText: "ABS-systemet (blokkeringsfritt bremsesystem) er sikkerhetsutstyr som hindrer hjulene i å låse seg under hard bremsing. En MC med defekt ABS er farligere å kjøre, og feilen er spesielt kritisk i vått føre og nødsituasjoner. ABS-feil kan skyldes defekte sensorer, hydraulikkproblemer eller elektronikkfeil.\n\nEtter kjøpsloven § 17 har MC-en en mangel dersom ABS-systemet ikke fungerer som det skal. ABS er sikkerhetskritisk utstyr som er lovpålagt på nye MC-er fra 2017, og en defekt er en alvorlig mangel som gir sterk reklamasjonsrett — potensielt hevingsrett.\n\nDokumenter ABS-feilen med bilder av eventuell varsellampe og få verkstedrapport med feilkodeutlesning og estimert utbedringskostnad. ABS-reparasjoner kan koste 5 000–20 000 kr avhengig av om det er sensor, pumpe eller styreenhet som er defekt.", faqs: [
    { q: "Clutchen slurer etter 200 km. Selger sier det er normal slitasje. Har han rett?", a: "Ikke uten videre. Clutch som slurer etter 200 km er unormalt og presumeres å ha vært slitt ved kjøpet, med mindre selger kan dokumentere at den ble skiftet nylig." },
    { q: "Kan jeg kreve ny clutch dekket av selger?", a: "Ja, dersom clutchen var i unormalt dårlig stand ved kjøpet. Krev skriftlig reklamasjon og få verkstedets vurdering på skriftlig." },
  ]},
  { slug: "mc-startproblemer", title: "Startvansker og batteriproblemer på brukt MC", lawRef: "KL § 17", cat: "mc-kjop", desc: "MC som ikke starter pålitelig er en klar mangel dersom problemet forelå ved kjøpet.", bodyText: "En MC som ikke starter pålitelig er ubrukelig og utgjør en mangel. Årsaken kan være alt fra svakt batteri og defekt starter til karburator- eller innsprøytningsproblemer, tenningsfeil eller kompresjonsproblemer. Diagnostikken er avgjørende for å identifisere riktig feilkilde.\n\nEtter kjøpsloven § 17 har MC-en en mangel dersom den ikke samsvarer med det kjøper hadde grunn til å forvente. En MC skal starte når du trykker på startknappen. Selger kan ikke avvise reklamasjonen med at MC-en er gammel eller at startproblemer er normalt — startproblemer er per definisjon en feil.\n\nSystematisk feilsøking er nødvendig: sjekk batteri (ladespenning og kapasitet), tenningssystem (gnisttest), kompresjon (kompresjonsmåler) og drivstoffystem (karburator eller innsprøyting). Få skriftlig rapport fra MC-verksted og reklamér til selger med vedlagt dokumentasjon.", faqs: [
    { q: "MC-en starter ikke om morgenen. Selger sier jeg bare må lade batteriet. Holder det?", a: "Et batteri som ikke holder lading er en mangel. Dersom batteriet svikter kort tid etter kjøp, er det selgers ansvar å bytte det." },
    { q: "Startvansker skyldes karburatorfeil ifølge verkstedet. Er det reklamasjonsgrunnlag?", a: "Ja, karburatorfeil som gir startproblemer er en skjult mangel dersom selger ikke opplyste om dette." },
  ]},
  { slug: "mc-kjolersystem-feil", title: "Overoppheting og kjølesystemfeil på MC", lawRef: "KL § 39", cat: "mc-kjop", desc: "MC som overopphetes kan ha alvorlig motorskade — reklamasjon er aktuelt.", bodyText: "Overoppheting på MC kan forårsake alvorlig motorskade — deformerte sylindere, sprukket toppakning eller ødelagte ventiler. Årsaken til kjølesystemfeil kan være defekt termostat, lekk kjølevæskepumpe, tilstoppet radiator eller sviktende vifte. Motorskade som følge av overoppheting kan koste 10 000–40 000 kr.\n\nEtter kjøpsloven § 39 presumeres feil som oppstår kort tid etter kjøpet å ha eksistert ved overlevering. Et kjølesystem som svikter etter noen dager eller uker har med all sannsynlighet hatt latente problemer ved salget. Selger kan ikke skylde på kjøpers bruk når svikten kommer så raskt.\n\nStopp MC-en umiddelbart dersom temperaturmåleren viser for høyt — videre kjøring kan forverre skaden dramatisk. Få MC-en fraktet til verksted på henger og krev feilsøking som identifiserer årsaken til overopphetingen skriftlig.", faqs: [
    { q: "MC-en koker over etter 20 minutter. Kan jeg heve kjøpet?", a: "Overoppheting er alvorlig og kan indikere defekt termostat, pumpe eller tetting. Dersom feilen ikke lar seg utbedre rimelig, kan heving være aktuelt." },
    { q: "Selger sier jeg bare må sjekke kjølevæsken selv. Er det riktig?", a: "Å sjekke kjølevæskenivå er ditt ansvar, men en defekt kjølepumpe eller termostat er selgers ansvar å utbedre." },
  ]},
  { slug: "mc-bremser-feil", title: "Defekte bremser på brukt MC: Sikkerhetsmangel", lawRef: "KL § 17", cat: "mc-kjop", desc: "Bremsesvikt på MC er sikkerhetskritisk og gir sterk reklamasjonsrett.", bodyText: "Bremsesvikt på MC er den mest sikkerhetskritiske mangelen og kan være direkte livsfarlig. Typiske problemer inkluderer svampete bremsefølelse, lekkasje i bremsehydraulikk, slitte bremseklosser under minimum, sprukne bremseskiver eller defekt ABS-system. Utbedringskostnaden varierer fra 2 000 kr for klosser til 15 000+ kr for hydraulikk og skiver.\n\nEtter kjøpsloven § 17 er defekte bremser en mangel som gir sterk reklamasjonsrett. Bremser er det viktigste sikkerhetssystemet på en MC, og mangler i bremsesystemet oppfyller normalt vesentlighetskravet for heving dersom selger ikke utbedrer innen rimelig tid.\n\nIkke kjør MC-en med defekte bremser. Reklamér umiddelbart skriftlig til selger og krev feilsøking og utbedring for selgers regning. Dokumenter symptomene (svamp, lekkasje, lyd) og få verkstedrapport som bekrefter feilens art og estimert utbedringskostnad.", faqs: [
    { q: "Bremsene kjennes svampete. Selger sier det er luft i systemet. Er det hans ansvar?", a: "Ja, luft i bremsesystemet er en mangel selger plikter å utbedre eller opplyse om ved salg. Svampete bremser er et sikkerhetsanliggende." },
    { q: "Bremseskivene er under minimum tykkelse. Hvem betaler?", a: "Dersom dette ikke ble opplyst og bilen nylig passerte tilstandskontroll, er det selgers ansvar. Be om dokumentasjon på siste verkstedbesøk." },
  ]},
  { slug: "mc-rammeskjevhet", title: "Skjult rammeskjevhet på brukt MC", lawRef: "KL § 19", cat: "mc-kjop", desc: "Rammeskjevhet som ikke ble opplyst om er vesentlig mangel og hevingsgrunnlag.", bodyText: "Rammeskjevhet på MC er en alvorlig mangel som påvirker kjøreegenskaper og sikkerhet fundamentalt. En skjev ramme fører til at MC-en trekker til siden, har ustabilt retningshold og kan gi farlige situasjoner ved høy fart. Årsaken er nesten alltid et tidligere velt eller kollisjon som selger ikke opplyste om.\n\nEtter kjøpsloven § 19 foreligger mangel dersom selger har holdt tilbake opplysninger om kjente skader. Rammeskjevhet er en vesentlig mangel som normalt gir hevingsrett — utbedring krever spesialverktøy og er ofte uforholdsmessig dyrt sammenlignet med MC-ens verdi.\n\nFå en MC-verksted med jig (rammemåler) til å dokumentere skjevheten med nøyaktige mål. Sammenlign med fabrikkmål og få skriftlig rapport. Denne dokumentasjonen er avgjørende for reklamasjonskravet. Dersom rammen er så skjev at MC-en er usikker å kjøre, er heving det naturlige kravet.", faqs: [
    { q: "MC-en trekker til siden. Verkstedet mistenker rammeskjevhet. Hva gjør jeg?", a: "Få skriftlig rapport fra verksted. Rammeskjevhet er vesentlig mangel og gir normalt hevingsrett, da det er kostbart å rette og påvirker sikkerheten." },
    { q: "Selger nekter for å ha visst om rammeskjevheten. Endrer det min rett?", a: "Nei. Selger er ansvarlig for skjulte mangler selv uten kunnskap. Det er tilstrekkelig at mangelen forelå ved kjøpet." },
  ]},
  { slug: "mc-girkasse-feil", title: "Feil på girkasse eller girskift på MC", lawRef: "KL § 39", cat: "mc-kjop", desc: "Girkasse som hopper ut av gir eller ikke kan legges inn er alvorlig mangel.", bodyText: "Girkasse som hopper ut av gir eller ikke kan legges inn er en alvorlig mangel som kan være direkte farlig i trafikk. Årsaker inkluderer slitte girklør, brukne fjærer, slitte skiftgaffler eller defekt girvalse. Girkassereparasjon på MC krever ofte at motoren deles, noe som gjør det kostbart — typisk 8 000–25 000 kr.\n\nEtter kjøpsloven § 39 presumeres feil som oppstår kort tid etter kjøpet å ha eksistert ved overlevering. En girkasse som hopper ut av gir etter noen hundre kilometer har med sikkerhet hatt latente slitasjeskader ved salget. Selger kan ikke skylde på kjøpers girskifteteknikk.\n\nDokumenter feilen nøyaktig: hvilke gir er berørt, under hvilke forhold (akselerasjon, retardasjon, konstant fart)? En detaljert beskrivelse hjelper verkstedet med diagnostikken. Få skriftlig rapport og reklamér umiddelbart. Ved høye utbedringskostnader relativt til kjøpesummen er heving aktuelt.", faqs: [
    { q: "MC-en hopper ut av 3. gir under akselerasjon. Er det en mangel?", a: "Ja, girkasse som ikke holder gir er en klar mangel. Dette kan skyldes slitte girklør eller fjærer som selger burde kjent til." },
    { q: "Kan jeg heve kjøpet pga. girkassefeil?", a: "Avhenger av utbedringskostnaden. Dersom girkasse-reparasjon er vesentlig i forhold til kjøpesummen, kan heving være aktuelt." },
  ]},
  { slug: "mc-forgaffel-lekkasje", title: "Lekkasje fra forgaffel eller bakdempere på MC", lawRef: "KL § 17", cat: "mc-kjop", desc: "Oljelekkasje fra forgaffel er vanlig men skal opplyses om ved salg.", bodyText: "Oljelekkasje fra forgaffel er et vanlig problem på brukte MC-er, men det er ikke normalt og skal opplyses om ved salg. Lekkende forgaffel gir dårligere demping, kan forårsake oljeflekkete bremseskive og er et sikkerhetsanliggende — spesielt ved hard bremsing der gaffelen komprimeres maksimalt.\n\nEtter kjøpsloven § 17 foreligger mangel dersom MC-en ikke har de egenskaper kjøper hadde grunn til å forvente. En MC med lekkende forgaffel er ikke i den stand kjøper kan forvente, selv om MC-en er brukt. Simmerringskifte i forgaffel koster typisk 3 000–6 000 kr, men dersom gaffelrørene er risset kreves nye rør (5 000–15 000 kr).\n\nSjekk gaffelrørene for synlige riper og riss — dette er den vanligste årsaken til simmerring-svikt. Ta bilder av oljerestene og eventuelle riss. Få verkstedrapport og reklamér skriftlig. Dersom lekkasjen var synlig ved overlevering, er det et klart brudd på selgers opplysningsplikt.", faqs: [
    { q: "Forgaffelen lekker olje. Selger sier alle gamle MC-er gjør det. Stemmer det?", a: "Noe slitasje er normalt, men aktiv lekkasje er en mangel selger plikter å opplyse om. 'Alle gjør det' er ikke et gyldig forsvar." },
    { q: "Simmerringer i forgaffelen er dyre å bytte. Kan jeg kreve dette dekket?", a: "Ja, dersom lekkasjen var til stede ved kjøpet og ikke ble opplyst om. Krev skriftlig reklamasjon og legg ved verkstedkostnadsestimat." },
  ]},
  { slug: "mc-dekk-utslitt", title: "Utslitte dekk ved levering av brukt MC", lawRef: "KL § 17", cat: "mc-kjop", desc: "MC med dekk under minsteprofil ved levering er en mangel selger må svare for.", bodyText: "MC-dekk med profildybde under lovlig minimum (1 mm) ved levering er en sikkerhetskritisk mangel og en åpenbar feil selger burde ha oppdaget. Utslitte dekk gir drastisk redusert veigrep, spesielt i vått føre, og øker bremselengden vesentlig. Et sett nye MC-dekk koster typisk 4 000–10 000 kr med montering.\n\nEtter kjøpsloven § 17 foreligger mangel dersom MC-en ikke har de egenskaper kjøper hadde grunn til å forvente. Lovlige dekk er en grunnleggende forutsetning for at MC-en kan brukes. Selger kan ikke hevde at dekk er forbruksmateriell og dermed kjøpers ansvar — ved levering skal dekkene være over lovlig minimum.\n\nMål profildybden med en profildybdemåler (billig å anskaffe) og dokumenter med bilder. Sjekk også dekkenes alder (DOT-kode på dekksideveggen) — dekk over 5 år er i praksis utslitte uavhengig av profildybde. Reklamér skriftlig med dokumentasjon og krev nye dekk for selgers regning.", faqs: [
    { q: "MC-dekkene var under 1mm profil da jeg fikk den. Er det en mangel?", a: "Ja, dekk under lovlig minsteprofil (1mm for MC) er en mangel. Selger pliktet å opplyse om eller utbedre dette før levering." },
    { q: "Selger sier dekk er forbruksmateriell og mitt ansvar. Er det riktig?", a: "Nei, ikke ved levering. Dekk som allerede er under minsteprofil ved overtakelse er en mangel, uavhengig av at de normalt er forbruksmateriell." },
  ]},
  { slug: "mc-originaldeler-bytta", title: "Originaldeler byttet ut uten opplysning ved MC-salg", lawRef: "KL § 18", cat: "mc-kjop", desc: "Bytte til ikke-originale deler uten opplysning kan gi prisavslag eller heving.", bodyText: "Dersom en MC er annonsert som original men viser seg å ha ikke-originale deler — enten mekaniske komponenter eller estetiske deler — er dette brudd på opplysningsplikten. Ikke-originale deler kan påvirke ytelse, holdbarhet, garanti og ikke minst videresalgsverdien av MC-en.\n\nEtter kjøpsloven § 18 foreligger mangel dersom MC-en ikke svarer til opplysningene selger ga. Dersom MC-en ble presentert som original og det viser seg at motor, eksosanlegg, dempere eller andre vesentlige deler er byttet til ettermarkedsprodukter, har du krav på prisavslag eller heving avhengig av omfanget.\n\nFå et MC-verksted til å gjennomgå MC-en og identifisere ikke-originale deler med delnumre og sammenligning mot fabrikkspesifikasjoner. Dokumentasjonen bør inkludere hvilke deler som er byttet, kvalitetsforskjellen og eventuell påvirkning på ytelse og sikkerhet.", faqs: [
    { q: "Verkstedet oppdaget at motoren har ikke-originale deler. Selger opplyste ikke om dette. Hva kan jeg kreve?", a: "Uoriginale deler som påvirker motorens levetid eller ytelse er brudd på opplysningsplikten. Du kan kreve prisavslag eller heving avhengig av omfanget." },
    { q: "Er ettermarkedsdeler alltid en mangel?", a: "Ikke alltid, men dersom de er av dårligere kvalitet enn originalt eller påvirker garantier, og dette ikke ble opplyst, er det en mangel." },
  ]},

  // MC-KJØP (3 nye noder)
  { slug: "mc-girboks-problem", title: "Problemer med girboks eller clutch på MC", lawRef: "KL § 39", cat: "mc-kjop", desc: "Girboks som hopper ut av gir er sikkerhetskritisk mangel og klar reklamasjonssak.", bodyText: "En girboks som hopper ut av gir under kjøring er ikke bare plagsomt — det er en sikkerhetskritisk feil som kan føre til alvorlige ulykker. På motorsykkel, der balanseringen er avgjørende, er uforutsigbar kraftoverføring særlig farlig. Slike feil reklamasjonsbehandles normalt som vesentlige mangler.\n\nGirboksfeil på MC kan skyldes slitte girhaker, slitt girstang, feil justering av clutch eller skader etter fall. En MC-mekaniker kan ved inspeksjon normalt fastslå om feilen skyldes slitasje som var til stede ved kjøpet, eller om den skyldes kjøremåte etter overtakelse.\n\nDersom feilen oppstår innen 6 måneder etter kjøpet presumeres den å ha eksistert ved overlevering. Dokumenter feilen skriftlig, ta opp video dersom mulig, og reklamér til selger umiddelbart.", faqs: [{ q: "Selger sier jeg har kjørt feil og skadet girboksen. Hva gjør jeg?", a: "Selger må dokumentere dette konkret. Innen 6 måneder etter kjøpet er bevisbyrden hos selger. En uavhengig MC-mekaniker kan gi faglig vurdering." }, { q: "MC-en har vært i velt tidligere. Kan det ha skadet girboksen?", a: "Det er mulig, men selger pliktet å opplyse om veltet. Skjult velteskade er uansett selgers ansvar etter kjøpsloven § 18." }, { q: "Hva koster det å reparere en girboks på MC?", a: "Avhengig av modell koster girboksreparasjon typisk 5 000–25 000 kr. Dersom det er en mangel skal selger dekke dette." }]},
  { slug: "mc-registerreim-brudd", title: "Brudd i registerreim på motorsykkel", lawRef: "KL § 39", cat: "mc-kjop", desc: "Registerreim som ryker før oppgitt skifteintervall kan indikere skjult mangel ved kjøpet.", bodyText: "Mange motorcykler — særlig sportssykler og paralleltwin-motorer — bruker registerreim i stedet for kjede. Registerreimen har et oppgitt skifteintervall fra produsenten, og dersom den ryker lenge før dette intervallet er nådd, er det sterk indikasjon på at den var i dårlig stand ved kjøpet.\n\nEt registerreim-brudd på MC fører nesten alltid til motorhavari — ventiler og stempel kolliderer med katastrofale følger. En ny motor til en MC koster typisk 20 000–60 000 kr, og mange sykler er totalskade etter et slikt havari.\n\nDokumenter service-historikk og be selger fremlegge bevis for siste registerreim-skifte. Dersom selger hevdet at service var utført uten å kunne dokumentere det, er dette brudd på opplysningsplikten og styrker reklamasjonen.", faqs: [{ q: "Selger sa at service var utført. Kan han ikke bare si det uten dokumentasjon?", a: "Nei. Påstand om utført service uten dokumentasjon er ikke tilstrekkelig. Krev faktura fra verksted. Manglende dokumentasjon taler mot selger." }, { q: "Registerreimen ryket etter 2 000 km. Er det nok til å reklamere?", a: "Ja, 2 000 km er langt under normalt skifteintervall for en registerreim. Dette er sterk indikasjon på at reimen var nær slutt ved kjøpet." }, { q: "Forsikringsselskapet avviser dekning fordi det er en mekanisk feil. Hva gjør jeg?", a: "Forsikring dekker normalt ikke mekanisk havari. Din rettighet er mot selger gjennom kjøpsloven, ikke mot forsikringsselskapet." }]},
  { slug: "mc-skjult-velteskade", title: "Skjulte skader etter velt på motorsykkel", lawRef: "KL § 18", cat: "mc-kjop", desc: "Skjult velteskade selger ikke opplyste om er brudd på opplysningsplikten.", bodyText: "Velt på motorsykkel kan påføre skjulte skader på ramme, gaffel, styrehode og drivverk som ikke er synlige ved vanlig inspeksjon. Dersom selger oppga at sykkelen aldri hadde vært i velt — eller ikke opplyste om kjente velteskader — er dette brudd på opplysningsplikten etter kjøpsloven § 18.\n\nEn MC-mekaniker med erfaring i skadeanalyse kan undersøke om rammen er rett, om gaffelen har spor etter støt og om styrehodet har vært utsatt for kraftig belastning. Slike undersøkelser avdekker ofte velter som selger hevder ikke har skjedd.\n\nSkjeve rammer og skadet gaffelkryss er sikkerhetskritiske feil. En MC med skjev ramme er ustabil ved høy hastighet og kan forårsake ulykker. Dette gir normalt grunnlag for heving.", faqs: [{ q: "Sykkelen trekker til siden. Kan det skyldes velteskade?", a: "Ja, trekk til siden er klassisk symptom på skjev gaffel eller ramme etter velt. Få en MC-mekaniker til å undersøke dette umiddelbart." }, { q: "Selger nekter for at sykkelen har vært i velt. Hvordan beviser jeg det?", a: "En faglig inspeksjon av ramme og gaffel kan avdekke spor etter støt og reparasjoner. Skadesporets alder og karakter vil normalt avsløre om selger lyver." }, { q: "Kan jeg kreve erstatning for tort og svie ved bevisst skjult velteskade?", a: "Erstatning for ikke-økonomisk tap er normalt ikke aktuelt i kjøpsrettslige saker. Du kan kreve heving og erstatning for dokumenterte kostnader." }]},

  // MC-KJØP (9 nye noder med bodyText og FAQs)
  { slug: "mc-motorhavari", title: "Motorhavari på motorsykkel etter kjøp", lawRef: "KL § 39", cat: "mc-kjop", desc: "Motorhavari kort tid etter kjøp presumeres å skyldes mangel ved overlevering.", bodyText: "Motorhavari på MC er en av de mest alvorlige feilene som kan oppstå, og reparasjonskostnadene er svært høye — typisk 20 000–80 000 kr for revidering eller bytte av MC-motor. Dersom havariet inntreffer kort tid etter kjøpet, er utgangspunktet at feilen forelå ved overlevering.\n\nVanlige årsaker til MC-motorhavari som selger burde kjent til: for lite motorolje ved salg, forurenset olje, slitte stempelringer, ventilslitasje eller tidligere kompresjonsproblemer som ble skjult. En MC-mekaniker kan ved inspeksjon fastslå om havariet skyldes akutt skade eller langvarig slitasje.\n\nKrev verkstedrapport som beskriver havariet og sannsynlig årsak. Dersom rapporten indikerer langvarig slitasje eller manglende vedlikehold, er det sterkt grunnlag for reklamasjon mot selger.", faqs: [{ q: "Motoren havarerte etter 500 km. Selger sier jeg har kjørt for hardt. Kan han ha rett?", a: "Han må dokumentere dette konkret. Motorhavari etter 500 km presumeres å skyldes forhold ved kjøpet. Selger har bevisbyrden innen de første 6 månedene." }, { q: "MC-en ble solgt med 'nylig service'. Kan jeg kreve dokumentasjon?", a: "Ja, krev faktura fra verksted med dato og km-stand. Kan selger ikke dokumentere service, er påstanden uten bevisverdi og styrker reklamasjonen." }, { q: "Kan jeg kreve ny motor eller må jeg akseptere reparasjon?", a: "Du kan kreve utbedring — selger velger mellom reparasjon og bytte. Dersom kostnadene er uforholdsmessige i forhold til MC-ens verdi, kan du kreve heving." }]},
  { slug: "mc-reklamasjon-privat", title: "Reklamasjon på MC kjøpt fra privatperson", lawRef: "KL § 39", cat: "mc-kjop", desc: "Privat MC-kjøp gir reklamasjonsrett ved vesentlige mangler.", bodyText: "Kjøp av motorsykkel fra privatperson reguleres av kjøpsloven, som stiller høyere krav til mangelens alvorlighetsgrad enn forbrukerkjøpsloven. Mangelen må være 'vesentlig' for at du kan heve et privatkjøp — men retten til prisavslag ved ikke-vesentlige mangler er den samme.\n\n'Som den er'-forbehold er vanlig ved private MC-salg og er lovlig, men det fritar ikke selger fra skjulte feil han kjente til. En MC annonsert som 'alt fungerer' med motorhavari to uker etter kjøpet er klart mangelfull uavhengig av forbehold.\n\nVed privatkjøp er det ekstra viktig å dokumentere tilstanden ved levering — ta bilder og video av sykkelen fra alle vinkler, test alle funksjoner og noter eventuelle opplysninger fra selger skriftlig. Dette er bevisgrunnlaget ditt dersom tvist oppstår.", faqs: [{ q: "Kjøpte MC privat og den har en feil selger ikke opplyste om. Hva gjør jeg?", a: "Reklamér skriftlig umiddelbart etter at feilen ble oppdaget. Beskriv feilen nøyaktig og krev utbedring eller prisavslag. Krev svar innen rimelig frist." }, { q: "Selger er ikke imøtekommende og nekter ansvar. Hvilke muligheter har jeg?", a: "Ta saken til Forbrukertvistutvalget (dersom selger er næringsdrivende) eller tingretten (privatperson). Forliksrådet er et gratis første steg ved private tvister." }, { q: "Hva er rimelig tid å reklamere på MC-feil?", a: "Reklamér innen 2–3 måneder etter at feilen ble oppdaget. Venter du for lenge kan du miste retten selv om du er innenfor den absolutte 2-årsfristen." }]},
  { slug: "mc-feil-opplysninger", title: "Feilaktige opplysninger ved MC-salg", lawRef: "KL § 18", cat: "mc-kjop", desc: "Feilaktige opplysninger om MC i annonse eller ved salg er brudd på opplysningsplikten.", bodyText: "Selger av MC er bundet av opplysningene som ble gitt i annonsen og ved visning. Dersom oppgitt km-stand, årsmodell, service-historikk, utstyr eller tilstand ikke stemmer, er dette brudd på kjøpsloven § 18 — uavhengig av om selger bevisst løy eller bare tok feil.\n\nTypiske feilopplysninger ved MC-salg: feil km-stand (et svært vanlig problem), påstand om nylig service uten dokumentasjon, oppgitt utstyr som mangler (f.eks. oppvarmet sete, ABS), og feil informasjon om at sykkelen aldri har vært i velt.\n\nTa alltid skjermbilde av annonsen ved kjøpet — Finn.no-annonser slettes etter salg. Lagre alle skriftlige og digitale kommunikasjon med selger. Dette er bevisgrunnlaget ditt ved tvist.", faqs: [{ q: "Selger oppga 30 000 km men service-historikken viser 55 000 km. Hva gjør jeg?", a: "Dette er kilometerstandmanipulering som er svik etter kjøpsloven § 18. Dokumenter avviket med service-historikk og krev heving og erstatning." }, { q: "MC-en hadde ikke ABS som annonsert. Kan jeg kreve prisavslag?", a: "Ja, manglende utstyr som ble oppgitt i annonsen er avvik fra avtalen. Krev prisavslag tilsvarende kostnaden for å installere ABS eller differansen i markedsverdi." }, { q: "Selger sier annonsen var skrevet av en bekjent og han visste ikke om feilen. Fritar det ham?", a: "Nei, selger er ansvarlig for innholdet i sin annonse uavhengig av hvem som skrev den." }]},
  { slug: "mc-heving", title: "Heve MC-kjøp — vilkår og fremgangsmåte", lawRef: "KL § 39", cat: "mc-kjop", desc: "Heving av MC-kjøp krever vesentlig mangel — her er fremgangsmåten.", bodyText: "Heving av MC-kjøp innebærer at du leverer sykkelen tilbake og får kjøpesummen refundert, minus nyttefradrag for den bruken du har hatt. For å heve kreves en vesentlig mangel — en feil som gjør at du ikke ville kjøpt sykkelen dersom du hadde kjent til den, eller som er så alvorlig at beholde av sykkelen er urimelig.\n\nVesentlige mangler ved MC som normalt gir hevingsrett: motorhavari, rammeskade, girkassefeil, skjult velteskade med sikkerhetskonsekvenser og kilometerfusk. Ikke-vesentlige feil som normalt ikke gir heving: slitt clutch, defekt elektronikk, slitte dekk.\n\nFremgangsmåte: 1) Reklamér skriftlig til selger med krav om heving. 2) Gi selger mulighet til å utbedre feilen én gang. 3) Dersom utbedring mislykkes eller avvises, gjenta hevingskravet skriftlig. 4) Dersom selger nekter, ta saken til Forbrukertvist eller tingrett.", faqs: [{ q: "Selger nekter å heve. Kan jeg bare levere tilbake sykkelen?", a: "Nei, du kan ikke ensidig levere tilbake sykkelen uten at heving er akseptert eller kjent gyldig av domstol. Fortsett å bruke sykkelen forsiktig mens tvisten pågår." }, { q: "Hvor mye nyttefradrag kan selger trekke ved heving?", a: "Nyttefradrag beregnes per kjørte km — normalt 1–3 kr/km avhengig av sykkelens verdi. En lav kjøresum gir lite fradrag og gjør heving mer lønnsomt for deg." }, { q: "Kan jeg kreve erstatning i tillegg til heving?", a: "Ja, dersom du har hatt dokumenterte utgifter — verkstedkostnader, leiemotorsykkel, diagnostikk — kan du kreve disse erstattet i tillegg til hevingsoppgjøret." }]},
  { slug: "mc-kjop-forhandler", title: "MC-kjøp fra forhandler — forbrukerkjøpslovens vern", lawRef: "FKL § 32", cat: "mc-kjop", desc: "Kjøp fra MC-forhandler gir sterkere rettigheter enn privatkjøp.", bodyText: "Kjøper du motorsykkel fra en næringsdrivende MC-forhandler gjelder forbrukerkjøpsloven, som gir vesentlig sterkere vern enn kjøpsloven ved privatkjøp. Reklamasjonsfristen er alltid 5 år, terskelen for heving er lavere og forhandler kan ikke fraskrive seg reklamasjonsretten.\n\nForhandler plikter å kjenne sykkelens tilstand og opplyse om kjente feil. En forhandler som selger en MC med kjent motorproblem uten å opplyse om det, har et strengere ansvar enn en privatperson i samme situasjon.\n\nVed forhandlerkjøp presumeres feil som oppstår innen 12 måneder å ha eksistert ved overlevering. Forhandler har bevisbyrden for at feilen ikke forelå — ikke du. Dette gjør det vesentlig enklere å hevde reklamasjonskrav innen det første året.", faqs: [{ q: "MC-forhandleren sier 1 års garanti er utløpt og de ikke hjelper. Er det lovlig?", a: "Nei, reklamasjonsfristen er 5 år etter forbrukerkjøpsloven og kan ikke avkortes av forhandleren. Krev skriftlig begrunnelse for avvisningen og klag til Forbrukerrådet." }, { q: "Forhandleren har reparert sykkelen to ganger uten å løse problemet. Hva nå?", a: "Etter to mislykkede utbedringsforsøk for samme feil har du rett til å heve kjøpet etter forbrukerkjøpsloven § 32." }, { q: "Kan jeg kreve leiemotorsykkel mens sykkelen er til reparasjon hos forhandler?", a: "Du kan kreve dekning for dokumenterte transportkostnader i reparasjonstiden dersom feilen er forhandlerens ansvar. Leiemotorsykkel bør avtales på forhånd." }]},
  { slug: "mc-dokumentasjon-krav", title: "Dokumentasjon du trenger for MC-reklamasjon", lawRef: "KL § 17", cat: "mc-kjop", desc: "God dokumentasjon er nøkkelen til å vinne frem med MC-reklamasjon.", bodyText: "De fleste tapte MC-reklamasjonssaker skyldes mangelfull dokumentasjon, ikke manglende juridisk grunnlag. Selgere vet at passivitet og dårlig dokumentasjon fra kjøpers side gjør kravene vanskeligere å hevde.\n\nDette bør du sikre ved kjøpet: skjermbilde av annonsen med dato, skriftlig kjøpekontrakt med km-stand og tilstandsbeskrivelse, kvittering for betaling, dokumentasjon av service-historikk og registreringsbevis. Ta bilder og video av sykkelen fra alle vinkler ved levering.\n\nNår feil oppstår: noter dato og symptomer, ta bilder og video av feilen, innhent skriftlig verkstedrapport med diagnose og sannsynlig årsak, og send reklamasjon skriftlig (e-post er tilstrekkelig) umiddelbart etter at feilen ble oppdaget.", faqs: [{ q: "Har ingen kvittering fra kjøpet. Kan jeg fortsatt reklamere?", a: "Ja, men det er vanskeligere. Bankoverføring, SMS-korrespondanse og vitner kan erstatte kvittering. Finn.no-annonsen bekrefter salgstidspunktet." }, { q: "Verkstedet vil ikke gi skriftlig vurdering av feilens årsak. Hva gjør jeg?", a: "Be eksplisitt om en skriftlig rapport med mekanikernes vurdering av årsak og sannsynlig opprinnelse. De aller fleste verksteder tilbyr dette mot betaling." }, { q: "Selger bestrider at feilen forelå ved kjøpet. Hva er det sterkeste beviset jeg kan ha?", a: "Verkstedrapport som konkluderer med at feilen er av eldre dato enn kjøpstidspunktet er det sterkeste beviset. Be spesifikt om dette i rapporten." }]},
  { slug: "mc-importert", title: "Importert motorsykkel — rettigheter og risiko", lawRef: "KL § 17", cat: "mc-kjop", desc: "Importert MC har samme reklamasjonsrett ved norsk kjøp, men dokumentasjon kan mangle.", bodyText: "Importerte motorsykler — særlig fra Tyskland, Japan og USA — er populære i Norge. Reklamasjonsreglene er de samme som for norskregistrerte sykler dersom du kjøper av norsk selger, men det kan være praktisk vanskeligere å innhente service-historikk og verifisere oppgitte opplysninger.\n\nVanlige problemer ved importerte MC: km-stand i miles som konverteres feil, manglende service-historikk på norsk, biler tilpasset andre klimasoner (rustbeskyttelse, frostsikring) og modifikasjoner som er ulovlige i Norge.\n\nDersom du kjøper direkte fra utlandet — enten privat eller fra utenlandsk forhandler — gjelder det aktuelle landets lover og håndhevelse kan være svært krevende. Norsk selger er alltid tryggere juridisk sett.", faqs: [{ q: "MC er importert fra USA med km-stand i miles. Selger oppga feil km. Hva gjør jeg?", a: "Krev dokumentasjon på originalt km-tall. Feil konvertering — enten bevisst eller uaktsomt — er brudd på opplysningsplikten. Krev prisavslag eller heving." }, { q: "MC-en har amerikanske modifikasjoner som ikke er godkjent i Norge. Er det selgers problem?", a: "Dersom selger ikke opplyste om dette, ja. En MC som ikke kan godkjennes i Norge har en vesentlig mangel dersom dette ikke ble eksplisitt kommunisert." }, { q: "Selger hevdet full service-historikk men historikken er på japansk og uleselig. Er det godt nok?", a: "Nei. Påstand om service-historikk som ikke kan verifiseres er ikke tilstrekkelig dokumentasjon. Krev oversettelse eller at selger bekrefter innholdet skriftlig." }]},
  { slug: "mc-sikkerhetsutstyr", title: "Manglende eller feil sikkerhetsutstyr på MC", lawRef: "KL § 17", cat: "mc-kjop", desc: "MC uten lovpålagt sikkerhetsutstyr er mangelfull og kan ikke brukes lovlig.", bodyText: "Motorsykler må ha visse sikkerhetssystemer for å være lovlige å bruke på norske veier — godkjente lykter, horn, reflekser, bremser som oppfyller kravene og i nyere modeller ABS der dette er påbudt. Dersom sykkelen mangler lovpålagt utstyr eller utstyr som ble oppgitt i annonsen, er det mangel.\n\nABS er påbudt på nye MC over 125cc fra 2016. Eldre sykler er ikke berørt, men dersom ABS ble annonsert som utstyr på en eldre sykkel og mangler, er det avvik fra avtalen.\n\nSikkerhetsutstyr som var oppgitt men mangler gir rett til prisavslag tilsvarende kostnaden for å installere utstyret eller differansen i markedsverdi mellom sykkel med og uten utstyret.", faqs: [{ q: "ABS virker ikke på MC-en som ble annonsert med ABS. Er det en mangel?", a: "Ja, dersom ABS var oppgitt som fungerende utstyr i annonsen er defekt ABS en klar mangel. Krev utbedring eller prisavslag." }, { q: "Lykten på MC-en er ikke godkjent for norsk vei. Er det selgers problem?", a: "Ja, dersom selger ikke opplyste om dette. En MC som ikke er lovlig å bruke i Norge har en vesentlig mangel." }, { q: "Selger sa han nettopp hadde gjort sykkelen klar for EU-kontroll. Kan han bevise det?", a: "Krev dokumentasjon — kvittering fra verksted eller bestått EU-kontroll med dato. Udokumentert påstand om EU-klargjøring er ikke tilstrekkelig." }]},
  { slug: "mc-feil-reklamasjonsfrist", title: "Reklamasjonsfrister ved MC-kjøp", lawRef: "KL § 32 / FKL § 27", cat: "mc-kjop", desc: "Reklamasjonsfristen er 2 år ved privatkjøp og 5 år ved forhandlerkjøp av MC.", bodyText: "Reklamasjonsreglene for MC er de samme som for bil — kjøpsloven ved privatkjøp og forbrukerkjøpsloven ved forhandlerkjøp. Fristene er henholdsvis 2 og 5 år fra leveringsdatoen.\n\nI tillegg til den absolutte fristen må du reklamere innen 'rimelig tid' etter at du oppdaget feilen — normalt 2–3 måneder. Mange taper reklamasjonssaker fordi de vet om feilen men venter for lenge med å klage.\n\nFor MC som er sesongbasert — de aller fleste nordmenn bruker ikke MC på vinterstid — åpnes spørsmålet om når reklamasjonsfristen begynner å løpe. Feil oppdaget ved første oppstart om våren etter at MC var lagret kan reklameres, men selger kan argumentere for at feilen burde vært oppdaget ved levering.", faqs: [{ q: "Kjøpte MC i oktober, la den i garasjen og oppdaget feil ved oppstart i april. Er jeg innenfor fristen?", a: "Ja, men reklamér umiddelbart ved oppstart. Oppbevaringsperioden teller ikke nødvendigvis som 'tid du burde ha oppdaget feilen' dersom feilen ikke var synlig ved levering." }, { q: "Har ventet 5 måneder med å reklamere fordi jeg håpet feilen ville forsvinne. Er det for sent?", a: "5 måneder er i grenseland for 'rimelig tid'. Reklamér umiddelbart. Jo lenger du venter etter oppdagelse, jo større risiko for at selger hevder passiv aksept." }, { q: "Selger sier 2 år er gått siden kjøpet og reklamasjonsfristen er ute. Er det riktig?", a: "Kun ved privatkjøp er fristen 2 år. Ved forhandlerkjøp er den 5 år. Sjekk hva slags kjøp du gjorde — dette er avgjørende for fristen." }]},

  // HÅNDVERKERE — URL: /handverkere/[slug]
  { slug: "bad-lekkasje-oppussing", title: "Lekkasje på bad etter oppussing", lawRef: "HTL § 5", cat: "handverkere", desc: "Lekkasje på bad etter håndverkerarbeid er mangel og gir rett til utbedring.", bodyText: "Lekkasje på bad etter oppussing er en av de hyppigste og alvorligste reklamasjonssakene mot håndverkere. Vann som trenger gjennom gulv eller vegger kan forårsake enorme skader på underliggende konstruksjoner, etasjer under og naboers leiligheter. Ansvaret kan raskt bli på hundretusenvis av kroner.\n\nÅrsaker til lekkasje inkluderer: feil membranlegging, manglende eller feil utførelse av sluk, feil fuging, manglende fall mot sluk og feil produkt for våtrom. Alle disse forholdene er håndverkerens ansvar — de plikter å levere fagmessig utført arbeid etter håndverkertjenesteloven § 5.\n\nReklamér skriftlig umiddelbart. Dokumenter lekkasjen med foto og fuktmålinger. Steng vannet dersom nødvendig. Håndverkeren har rett til å utbedre én gang — dersom utbedringen mislykkes kan du engasjere andre og kreve kostnadene dekket.", faqs: [{ q: "Håndverkeren sier lekkasjen skyldes feil bruk av badet. Kan han ha rett?", a: "Han må dokumentere dette konkret. Normal bruk av bad — dusj, badekar — er ikke misbruk. Håndverkeren har ansvar for at arbeidet tåler normal fuktbelastning." }, { q: "Naboens leilighet under er skadet av lekkasjen min. Hvem er ansvarlig?", a: "Primæransvaret er håndverkerens. Du kan bli holdt ansvarlig overfor naboen, men har regresskrav mot håndverkeren for hele skaden." }, { q: "Det er gått 3 år siden badet ble pusset opp. Er det for sent å reklamere?", a: "Nei, reklamasjonsfristen er 5 år på arbeid på fast eiendom. Reklamér skriftlig umiddelbart etter at lekkasjen ble oppdaget." }]},
  { slug: "forsinket-handverker-dagmulkt", title: "Håndverker er forsinket: Krav på dagmulkt", lawRef: "HTL § 11", cat: "handverkere", desc: "Ved forsinkelse utover avtalt tid kan du kreve dagmulkt uten å bevise tap.", bodyText: "Forsinkelse er blant de vanligste problemene ved håndverkertjenester. Håndverkertjenesteloven § 11 gir deg rett til dagmulkt dersom arbeidet ikke ferdigstilles innen avtalt tid — uten at du trenger å bevise at forsinkelsen har medført økonomisk tap. Dagmulkt-prinsippet gir normalt 1 promille av vederlaget per virkedag forsinkelsen varer, i inntil 100 dager.\n\nI Forbrukerklageutvalgets sak 116596 ble det gitt prisavslag på 250 000 kr for totalrenovering med omfattende mangler — forsinkelse var ett av flere momenter som ble vektlagt. Dersom dagmulkt ikke er eksplisitt avtalt i kontrakten, kan du likevel kreve erstatning for dokumentert tap som følge av forsinkelsen, for eksempel ekstra boutgifter eller tapt arbeidsinntekt.\n\nFor å kreve dagmulkt må du kunne dokumentere avtalt ferdigstillelsesdato og faktisk ferdigstillelsesdato. Hold all kommunikasjon skriftlig (e-post, SMS) og dokumenter fremdriften med bilder og tidsangivelser. Håndverkertjenesteloven § 32 (HTL § 32) begrenser også prisoverskridelser til 15 % over estimat — forsinkelser og overskridelser går ofte hånd i hånd.", faqs: [{ q: "Håndverkeren har ikke avtalt dagmulkt i kontrakten. Kan jeg likevel kreve noe?", a: "Du kan kreve erstatning for dokumentert tap etter HTL § 11. Dagmulkt-prinsippet (1 promille per dag, maks 100 dager) gjelder ved avtale. I sak 116596 ble forsinkelse vektlagt i prisavslaget." }, { q: "Hva er rimelig dagmulktsats?", a: "Dagmulkt-prinsippet tilsier 1 promille av vederlaget per virkedag, i inntil 100 dager. Ved en kontrakt på 500 000 kr tilsvarer det 500 kr per dag — maks 50 000 kr totalt." }, { q: "Kan jeg holde tilbake sluttbetaling pga. forsinkelse?", a: "Ja, du kan holde tilbake et beløp tilsvarende dagmulktkravet. HTL § 32 beskytter deg også mot prisoverskridelser over 15 % av estimat uten forhåndsgodkjenning." }] },
  { slug: "samsvarserklaring-mangler", title: "Mangler samsvarserklæring på el-arbeid", lawRef: "HTL § 5", cat: "handverkere", desc: "Manglende samsvarserklæring er mangel som gir rett til utbedring uten kostnad.", bodyText: "En samsvarserklæring er et lovpålagt dokument som bekrefter at elektrisk arbeid er utført i henhold til norsk regelverk. Elektrikeren er pliktig til å sende kopi til det lokale eltilsynet (DLE) og til deg som oppdragsgiver. I Forbrukerklageutvalgets sak 135048 ble det fastslått at manglende samsvarserklæring i seg selv utgjør en mangel etter håndverkertjenesteloven — uavhengig av om det elektriske arbeidet ellers er korrekt utført.\n\nUten samsvarserklæring er det elektriske arbeidet formelt ikke godkjent, noe som kan gi problemer ved boligsalg, forsikringsoppgjør og tilsyn. Du risikerer også at forsikringsselskapet avviser et krav dersom brann oppstår i den ikke-dokumenterte installasjonen. Reklamasjonsfristen er 5 år etter ferdigstillelse.\n\nKrev samsvarserklæring skriftlig fra elektrikeren med rimelig frist for levering. Dersom elektrikeren ikke leverer, kan du melde forholdet til det lokale eltilsynet. Du kan holde tilbake sluttbetaling inntil samsvarserklæringen er levert — dette er lovlig tilbakeholdsrett etter HTL. I sak 116596 ble mangler ved totalrenovering — inkludert manglende dokumentasjon — vektlagt i et prisavslag på 250 000 kr.", faqs: [{ q: "Elektrikeren har sluttet i firmaet. Hvem leverer samsvarserklæringen?", a: "Firmaet er ansvarlig. Sak 135048 fastslår at manglende samsvarserklæring er en mangel i seg selv. Kontakt DLE dersom firmaet er nedlagt." }, { q: "Kan jeg selge boligen uten samsvarserklæring?", a: "Du kan, men kjøper vil sannsynligvis kreve dokumentasjon. Sak 135048 bekrefter at manglende samsvarserklæring er en mangel — kjøper kan kreve prisavslag." }, { q: "Er manglende samsvarserklæring nok til å holde tilbake betaling?", a: "Ja. Samsvarserklæring er en del av leveransen etter HTL § 5. Sak 135048 fastslår at mangel foreligger selv om det elektriske arbeidet ellers er korrekt utført." }] },
  { slug: "tak-utett-lekkasje", title: "Utett tak etter taktekking: Reklamasjon", lawRef: "HTL § 5", cat: "handverkere", desc: "Taklekkasje etter nytt tak er klar mangel med lang reklamasjonsfrist.", bodyText: "Et nytt tak som lekker er en åpenbar mangel — formålet med taket er nettopp å holde bygningen tett. Taklekkasje kan forårsake omfattende følgeskader: fukt i isolasjon, mugg, råte i bærekonstruksjoner og vannskader på inventar. I Forbrukerklageutvalgets sak 116596 ble det gitt prisavslag på 250 000 kr for totalrenovering med omfattende mangler — lekkasje og fuktskader var sentrale momenter i vurderingen.\n\nEtter håndverkertjenesteloven § 5 skal arbeidet utføres fagmessig. Et tak som lekker er per definisjon ikke fagmessig utført. Reklamasjonsfristen for arbeid på fast eiendom er 5 år, og du kan reklamere så snart du oppdager mangelen. I sak 2021-554 ble en entreprenør holdt ansvarlig for feil på utvendig arbeid flere år etter ferdigstillelse — prinsippet gjelder tilsvarende for takarbeid.\n\nDokumenter lekkasjen umiddelbart med bilder og video. Begrens skadeomfanget ved å sette opp oppsamlingskar og varsle forsikringsselskapet. Reklamér skriftlig til håndverkeren og krev utbedring uten ekstra kostnad — inkludert utbedring av følgeskader som er håndverkerens ansvar.", faqs: [{ q: "Taket lekker etter to år. Er det for sent å reklamere?", a: "Nei. Reklamasjonsfristen er 5 år etter HTL. I sak 2021-554 ble entreprenør holdt ansvarlig flere år etter ferdigstillelse. Reklamér innen rimelig tid etter oppdagelse." }, { q: "Håndverkeren sier det er en naturlig svakhet i taket. Har han rett?", a: "Et fagmessig utført tak skal ikke lekke under normale norske værforhold. Sak 116596 bekrefter at mangelfullt arbeid gir prisavslag — selger/håndverker bærer risikoen." }, { q: "Kan jeg kreve erstatning for vannskader inne?", a: "Ja. Følgeskader er håndverkerens ansvar etter HTL. I sak 116596 ble prisavslaget beregnet ut fra totale mangler inkludert følgeskader. Dokumenter alt med bilder." }] },
  { slug: "prisestimat-overskridet", title: "Håndverker krever mer enn estimat (15 %-regelen)", lawRef: "HTL § 32", cat: "handverkere", desc: "Overskridelse over 15 % av estimat er ulovlig uten forhåndsvarsel.", bodyText: "Håndverkertjenesteloven § 32 beskytter deg mot uventede kostnadsoverskridelser. Dersom håndverkeren ga et prisestimat (prisoverslag), kan det endelige kravet ikke overstige estimatet med mer enn 15 % uten at du ble varslet og ga samtykke til merarbeidet på forhånd. HTL § 32 er ufravikelig — håndverkeren kan ikke avtale seg bort fra denne regelen.\n\nSkillet mellom prisestimat og fastpris er avgjørende. Et prisestimat er en kvalifisert vurdering av sannsynlig pris med 15 %-grense, mens en fastpris er bindende — risikoen for overskridelse ligger hos håndverkeren. I Forbrukerklageutvalgets sak 116596 ble det gitt prisavslag på 250 000 kr for totalrenovering med omfattende mangler — overpris og manglende varsling var sentrale momenter.\n\nDersom håndverkeren krever vesentlig mer enn estimatet, krev skriftlig dokumentasjon for merarbeidet. Dagmulkt-prinsippet (1 promille per dag, maks 100 dager) kan også komme til anvendelse dersom overskridelsen skyldes forsinkelser. Hold tilbake det overskytende beløpet og henvis til HTL § 32.", faqs: [{ q: "Håndverkeren sendte faktura 40 % over estimatet. Må jeg betale?", a: "Nei. HTL § 32 begrenser overskridelse til 15 % uten forhåndsgodkjenning. Betal estimat pluss 15 % og henvis til loven. I sak 116596 ble overskridelser sanksjonert med prisavslag." }, { q: "Hva er forskjellen på prisestimat og fastpris?", a: "Prisestimat gir 15 %-regelen etter HTL § 32. Fastpris er bindende — håndverkeren bærer all risiko for overskridelse. Sjekk kontrakten nøye for hvilken prisform som er avtalt." }, { q: "Håndverkeren sier han varslet muntlig om merarbeid. Holder det?", a: "Muntlig varsel er vanskelig å bevise. Bevisbyrden for at det ble varslet og godkjent ligger hos håndverkeren. Skriftlig kommunikasjon er avgjørende." }] },

  // HÅNDVERKERE (10 nye noder med FAQs)
  { slug: "drenering-svikter", title: "Drenering som svikter etter legging: Reklamasjon", lawRef: "HTL § 5", cat: "handverkere", desc: "Sviktende drenering etter ferdigstilt arbeid er mangel etter håndverkertjenesteloven.", bodyText: "Sviktende drenering etter ferdigstilt arbeid er en alvorlig mangel som kan forårsake fukt i kjeller, setningsskader og sopp i konstruksjonen. Utbedringskostnaden for feilaktig drenering kan løpe opp i flere hundre tusen kroner, og følgeskadene kan være enda dyrere. I Forbrukerklageutvalgets sak 2021-554 ble en entreprenør holdt ansvarlig for dreneringsfeil flere år etter ferdigstillelse — reklamasjonsfristen på 5 år gjelder fullt ut.\n\nEtter håndverkertjenesteloven § 5 skal dreneringsarbeid utføres fagmessig i henhold til byggteknisk forskrift og NBI-anvisninger. Korrekt drenering krever riktig fallretning, filterlag, drensrør av riktig type, og tilkobling til avløp eller infiltrasjon. Feil på ett av disse punktene kan gjøre hele dreneringen virkningsløs.\n\nDokumenter fuktproblemer med bilder, fuktmålinger og eventuelt graving for å avdekke dreneringsløsningen. En takstmann kan vurdere om dreneringen er fagmessig. I sak 116596 ble prisavslag på 250 000 kr gitt for totalrenovering med omfattende mangler — dreneringsfeil ble tilsvarende vektlagt i sak 2021-554.", faqs: [{ q: "Kjelleren er fuktig etter ny drenering. Hva gjør jeg?", a: "Reklamér skriftlig umiddelbart. I sak 2021-554 ble entreprenør holdt ansvarlig for dreneringsfeil flere år etter ferdigstillelse. Krev uavhengig takstvurdering." }, { q: "Dreneringen ble lagt for 4 år siden. Er det for sent å reklamere?", a: "Nei, reklamasjonsfristen er 5 år etter HTL. Sak 2021-554 bekrefter at dreneringsfeil kan reklameres flere år etter ferdigstillelse — reklamér innen rimelig tid etter oppdagelse." }, { q: "Håndverkeren sier fukt skyldes feil jeg har gjort. Hvem har bevisbyrden?", a: "Håndverkeren har bevisbyrden for at feilen skyldes noe utenfor hans kontroll. En uavhengig takstvurdering vil normalt avklare om dreneringen er fagmessig utført." }]},
  { slug: "maling-flasser-av", title: "Maling som flasser av etter kort tid: Reklamasjon", lawRef: "HTL § 5", cat: "handverkere", desc: "Maling som flasser av innen kort tid er ikke fagmessig utført og gir reklamasjonsrett.", bodyText: "Maling som flasser av kort tid etter malearbeid er et klassisk tegn på mangelfullt grunnarbeid. Årsaken er nesten alltid at overflaten ikke ble tilstrekkelig rengjort, slipt eller primet før maling — eller at det ble malt under ugunstige forhold. I Forbrukerklageutvalgets sak 64908 ble det gitt prisavslag for feilmontert gulv med knirk og gliper — prinsippet om at mangelfullt håndverk gir rett til prisavslag gjelder tilsvarende for dårlig malearbeid.\n\nEtter håndverkertjenesteloven § 5 skal malearbeid utføres fagmessig. En profesjonell maler plikter å vurdere underlagets egnethet og ta forbehold dersom underlaget er problematisk. Dersom maleren ikke tok forbehold og malingen likevel flasser, er det hans ansvar. Reklamasjonsfristen er 5 år for arbeid på fast eiendom.\n\nDokumenter problemet med bilder og reklamér skriftlig. Krev at maleren utfører arbeidet på nytt for egen regning, inkludert nødvendig grunnarbeid. I sak 116596 ble prisavslag på 250 000 kr gitt for totalrenovering med omfattende mangler — kumulative småfeil kan samlet gi betydelig prisavslag.", faqs: [{ q: "Malingen flasser av etter 6 måneder. Håndverkeren sier det er underlaget. Hvem har rett?", a: "Håndverkeren plikter å vurdere underlagets egnethet etter HTL § 5. I sak 64908 ble tilsvarende mangelfullt håndverk gitt prisavslag. Maleren bærer risikoen." }, { q: "Kan jeg kreve at alt males om for håndverkerens regning?", a: "Ja. Krev full utbedring. Dersom håndverkeren nekter, kan du engasjere andre — sak 116596 bekrefter at omfattende mangler gir rett til prisavslag eller utbedringskostnader." }, { q: "Malerarbeidet kostet 80 000 kr og resultatet er elendig. Kan jeg kreve pengene tilbake?", a: "Du kan kreve prisavslag tilsvarende utbedringskostnaden, eller at maleren retter arbeidet. HTL § 32 begrenser også overskridelser til 15 % over estimat." }]},
  { slug: "varmepumpe-stoy", title: "Varmepumpe som støyer etter installasjon", lawRef: "HTL § 5", cat: "handverkere", desc: "Støyende varmepumpe kan skyldes feil montering — reklamasjon er aktuelt.", bodyText: "En varmepumpe som støyer unormalt etter installasjon kan skyldes feil montering, manglende vibrasjonsdempere, feiljustert kompressor eller installasjon for nær nabogrense. Støyen kan påvirke både deg og naboene, og kan i verste fall føre til naboklager og pålegg om fjerning. I Forbrukerklageutvalgets sak 116596 ble det gitt prisavslag på 250 000 kr for totalrenovering med omfattende mangler — feil installasjon av tekniske systemer var et sentralt moment.\n\nEtter håndverkertjenesteloven § 5 skal installatøren utføre arbeidet fagmessig, noe som inkluderer korrekt montering med vibrasjonsdempere, riktig plassering i henhold til støykrav, og kontroll av at enheten fungerer innenfor spesifikasjonene. Sak 135048 fastslår at manglende dokumentasjon (samsvarserklæring) i seg selv er en mangel — dette gjelder tilsvarende for manglende ferdigdokumentasjon på varmepumpeinstallasjon.\n\nDokumenter støyen med lydopptak og be om en uavhengig støymåling. Sammenlign resultatene med produsentens spesifikasjoner. Dersom støyen overskrider spesifikasjonene, er det sterk indikasjon på feil montering. Reklamér skriftlig og krev utbedring innen rimelig tid.", faqs: [{ q: "Varmepumpen lager metallisk lyd etter montering. Er det en mangel?", a: "Ja, dersom støyen skyldes feil montering etter HTL § 5. I sak 116596 ble feil installasjon av tekniske systemer vektlagt i prisavslaget. Krev utbedring." }, { q: "Installatøren sier støyen er normalt for denne modellen. Hva gjør jeg?", a: "Be om dokumentasjon fra produsenten. Dersom produsenten ikke bekrefter støynivået, er installatørens påstand ikke holdbar. Uavhengig støymåling avklarer." }, { q: "Naboen klager på varmepumpestøy. Kan jeg holde installatøren ansvarlig?", a: "Ja, installatøren plikter å plassere og montere enheten i henhold til støykrav. Feilplassering er mangel etter HTL § 5 og sak 135048 om dokumentasjonskrav." }]},
  { slug: "kjokken-montering-skjev", title: "Skjev kjøkkenmontering: Reklamasjon på håndverker", lawRef: "HTL § 5", cat: "handverkere", desc: "Skjevt montert kjøkken er ikke fagmessig utført og gir krav på utbedring.", bodyText: "Et skjevt montert kjøkken er ikke bare estetisk skjemmende — det kan påvirke funksjonaliteten til skap, skuffer og dører, og kan tyde på at håndverkeren manglet kompetanse eller arbeidet for raskt. I Forbrukerklageutvalgets sak 64908 ble det gitt prisavslag for feilmontert gulv med knirk og gliper — prinsippet om at montering som ikke holder fagmessig standard gir rett til prisavslag, gjelder tilsvarende for kjøkkenmontering.\n\nEtter håndverkertjenesteloven § 5 skal kjøkkenmontering utføres fagmessig. Skap som ikke henger i vater, dører som ikke lukkes ordentlig, og benkeplate som ikke ligger plant er alle tegn på mangelfullt arbeid. En vater og vinkelmåler kan dokumentere avvikene objektivt. HTL § 32 begrenser dessuten prisoverskridelser til 15 % over estimat.\n\nReklamér skriftlig med bilder og målinger som viser avvikene. I sak 116596 ble prisavslag på 250 000 kr gitt for totalrenovering med omfattende mangler — kumulative monteringsfeil kan samlet utgjøre grunnlag for betydelig prisavslag. Gi håndverkeren rimelig mulighet til å utbedre før du engasjerer andre.", faqs: [{ q: "Kjøkkenskap henger ikke rett og dørene slår igjen av seg selv. Er det reklamasjonsgrunnlag?", a: "Ja. I sak 64908 ga feilmontering prisavslag. Skjev montering er mangel etter HTL § 5 som håndverkeren plikter å utbedre vederlagsfritt." }, { q: "Håndverkeren nekter å komme tilbake. Hva gjør jeg?", a: "Engasjér en annen håndverker, dokumenter feilen og krev kostnaden dekket. Sak 116596 bekrefter at omfattende mangler gir prisavslag opp til hundretusener." }, { q: "Kjøkkenmonteringen kostet mye mer enn estimatet. Kan jeg nekte å betale?", a: "HTL § 32 begrenser overskridelse til 15 % av estimat uten forhåndsgodkjenning. Betal estimat pluss maks 15 % og henvis til loven." }]},
  { slug: "parkett-buing-sprekker", title: "Parkett som buer seg eller sprekker etter legging", lawRef: "HTL § 5", cat: "handverkere", desc: "Parkett som ikke ligger flatt er normalt feil legging — håndverkeren er ansvarlig.", bodyText: "Parkett som buer seg opp (kuving) eller sprekker kort tid etter legging er normalt et tegn på feil utførelse. Vanlige årsaker er manglende akklimatisering av parketten før legging, feil underlag, utilstrekkelig dampsperre, for trange ekspansjonsfuger, eller legging under ugunstige fuktforhold. I Forbrukerklageutvalgets sak 64908 ble det gitt prisavslag for feilmontert gulv med knirk og gliper — prinsippet gjelder direkte for parkettlegging.\n\nEtter håndverkertjenesteloven § 5 plikter parkettleggeren å vurdere underlagets egnethet, fuktmåle gulvet, sikre at parketten er akklimatisert, og informere deg om krav til luftfuktighet etter legging. Dersom noen av disse stegene er utelatt, er det faglig svikt. Reklamasjonsfristen er 5 år for arbeid på fast eiendom.\n\nDokumenter problemet med bilder og fuktmålinger. En uavhengig gulvekspert kan vurdere årsaken og gi skriftlig rapport. I sak 116596 ble prisavslag på 250 000 kr gitt for totalrenovering med omfattende mangler — gulvproblemer kan være del av en større sak.", faqs: [{ q: "Parketten buer seg etter 3 måneder. Håndverkeren sier det er luftfuktigheten. Har han rett?", a: "Håndverkeren plikter å informere om krav til luftfuktighet etter HTL § 5. I sak 64908 ble mangelfullt gulvarbeid gitt prisavslag. Uten skriftlig informasjon bærer han risikoen." }, { q: "Sprekker mellom parkettstaver etter vinteren. Er det reklamasjonsgrunnlag?", a: "Store sprekker kan tyde på feil akklimatisering. Sak 64908 fastslår at knirk og gliper fra feil legging er mangel. Normal krymping i tre er begrenset." }, { q: "Kan jeg kreve at hele gulvet legges om?", a: "Ja, dersom mangelen er gjennomgående. Krev full utbedring etter HTL § 5. Dersom håndverkeren nekter, kan du engasjere andre og kreve kostnaden dekket." }]},
  { slug: "flislegging-mangelfull", title: "Flis som løsner eller sprekker etter legging", lawRef: "HTL § 5", cat: "handverkere", desc: "Flis som løsner er klassisk reklamasjonssak mot flislegger.", bodyText: "Flis som løsner, sprekker eller har ujamne fuger kort tid etter legging er et klart tegn på mangelfullt håndverk. Typiske årsaker er feil limtype, utilstrekkelig limdekning på flisens bakside, fuktproblemer i underlaget, manglende membran i våtrom, eller feil fugemetode. I Forbrukerklageutvalgets sak 116596 ble det gitt prisavslag på 250 000 kr for totalrenovering med omfattende mangler — feil flisarbeid i våtrom var et sentralt moment.\n\nEtter håndverkertjenesteloven § 5 skal flislegging utføres fagmessig. For våtrom gjelder i tillegg Byggteknisk forskrift (TEK17) med strenge krav til membran og fuktsperre. Sak 135048 fastslår at manglende dokumentasjon (samsvarserklæring) i seg selv er en mangel — tilsvarende gjelder for manglende membrandokumentasjon i våtrom.\n\nDokumenter løse fliser med video (bank forsiktig — hul lyd betyr at flisen har sluppet underlaget). En takstmann kan vurdere omfanget. I sak 64908 ble feilmontering av gulv gitt prisavslag — prinsippet gjelder tilsvarende for mangelfullt flisarbeid.", faqs: [{ q: "Fliser på badet løsner etter 1 år. Er det reklamasjonsgrunnlag?", a: "Ja. I sak 116596 ble mangelfullt våtromsarbeid vektlagt i prisavslag på 250 000 kr. Flis som løsner etter 1 år er klar indikasjon på feil utførelse." }, { q: "Håndverkeren sier jeg rengjorde feil og løste limet. Kan han ha rett?", a: "Han må dokumentere dette — bevisbyrden er hans. Normal rengjøring skal ikke løse flislim. I sak 64908 ble tilsvarende ansvarsfraskrivelse avvist." }, { q: "Mangler membran under flisene i dusjen. Hva kan jeg kreve?", a: "Manglende membran i våtrom er alvorlig mangel. Sak 135048 fastslår at manglende dokumentasjon er mangel — manglende membran er enda mer alvorlig. Krev full utbedring." }]},
  { slug: "elektriker-feil-installasjon", title: "Feil elektrisk installasjon: Klage på elektriker", lawRef: "HTL § 5", cat: "handverkere", desc: "Feil elektrisk arbeid er både en mangel og en sikkerhetsrisiko.", bodyText: "Feil i elektrisk installasjon er både en mangel og en sikkerhetsrisiko. Typiske feil inkluderer underdimensjonerte kabler, feil sikringstørrelse, manglende jordfeilbryter, dårlige koblinger eller kabelføring som ikke oppfyller NEK 400. I Forbrukerklageutvalgets sak 135048 ble det fastslått at manglende samsvarserklæring i seg selv utgjør en mangel — feil i selve installasjonen er naturligvis enda mer alvorlig.\n\nEtter håndverkertjenesteloven § 5 skal elektrisk arbeid utføres fagmessig og i samsvar med gjeldende regelverk. Elektrikeren plikter å levere samsvarserklæring som bekrefter at arbeidet oppfyller alle krav. I sak 116596 ble prisavslag på 250 000 kr gitt for totalrenovering med omfattende mangler — feil elektrikerarbeid var del av vurderingen.\n\nDersom du opplever gjentatte sikringsutløsninger, varmgang i stikkontakter eller andre tegn på feil, kontakt en annen autorisert elektriker for uavhengig vurdering. Du kan melde forholdet til det lokale eltilsynet (DLE). Reklamasjonsfristen er 5 år etter ferdigstillelse.", faqs: [{ q: "Sikringen løser ut jevnlig etter ny installasjon. Er det en mangel?", a: "Ja. Fungerende installasjon skal ikke utløse sikringer ved normal bruk. Sak 135048 fastslår at elektrikeren må levere fagmessig arbeid med samsvarserklæring." }, { q: "Elektrikeren har ikke levert samsvarserklæring. Hva betyr det?", a: "I sak 135048 ble manglende samsvarserklæring fastslått som mangel i seg selv. Du kan holde tilbake betaling og melde forholdet til DLE." }, { q: "Kan feil elektrisk installasjon gi meg prisavslag?", a: "Ja. I sak 116596 ble prisavslag på 250 000 kr gitt for totalrenovering med mangler — feil elektrikerarbeid ble vektlagt. Alternativt kan du kreve utbedring for elektrikerens regning." }]},
  { slug: "murer-arbeid-mangelfull", title: "Mangelfullt murerarbeid: Sprekker og setninger", lawRef: "HTL § 5", cat: "handverkere", desc: "Sprekker i mur kort tid etter arbeid tyder på feil utførelse.", bodyText: "Mangelfullt murerarbeid viser seg typisk som sprekker, avskallinger, misfarging eller fuktgjennomslag kort tid etter ferdigstilling. Årsaken kan være feil mørtelblanding, feil påføringsmetode, muring under ugunstige temperaturer, eller manglende herdetid mellom lag. I Forbrukerklageutvalgets sak 116596 ble det gitt prisavslag på 250 000 kr for totalrenovering med omfattende mangler — prinsippet gjelder tilsvarende for isolert murerarbeid.\n\nEtter håndverkertjenesteloven § 5 skal murerarbeid utføres fagmessig med riktige materialer og metoder tilpasset forholdene. En profesjonell murer kjenner kravene til temperatur, fuktighet og herdetid. I sak 2021-554 ble en entreprenør holdt ansvarlig for utvendige feil flere år etter ferdigstillelse — reklamasjonsfristen er 5 år for arbeid på fast eiendom.\n\nDokumenter sprekkene med bilder og noter når de oppsto. En bygningskyndig kan vurdere om sprekkene skyldes feil utførelse. Ved alvorlige mangler kan prisavslag beregnes tilsvarende utbedringskostnaden — slik tilfellet var i sak 116596.", faqs: [{ q: "Murpussen sprekker opp etter én vinter. Er det reklamasjonsgrunnlag?", a: "Ja. I sak 2021-554 ble entreprenør holdt ansvarlig for utvendige feil etter flere år. Sprekker i nytt murverk presumeres å skylde feil utførelse etter HTL § 5." }, { q: "Mureren sier sprekkene skyldes naturlig setning i bygget. Kan han ha rett?", a: "Han må dokumentere dette. Bevisbyrden for at feilen skyldes noe utenfor hans kontroll er murens. Sak 116596 bekrefter at mangelfull håndverker bærer risikoen." }, { q: "Kan jeg kreve prisavslag for dårlig murerarbeid?", a: "Ja. Prisavslag beregnes tilsvarende utbedringskostnaden. I sak 116596 ga omfattende mangler prisavslag på 250 000 kr. Du kan alternativt kreve utbedring." }]},
  { slug: "rorlegger-lekkasje", title: "Lekkasje fra rørleggerarbeid: Reklamasjon", lawRef: "HTL § 5", cat: "handverkere", desc: "Rørlekkasje etter ferdigstilt arbeid er mangel rørlegger er ansvarlig for.", bodyText: "Lekkasje fra rørleggerarbeid er en av de mest akutte og kostbare manglene en håndverker kan forårsake. Vannskade kan spre seg raskt og gi følgeskader som tørking, utskifting av gulv og vegger, mugg og soppskade. I Forbrukerklageutvalgets sak 116596 ble det gitt prisavslag på 250 000 kr for totalrenovering med omfattende mangler — vannskader og lekkasjer var sentrale momenter i vurderingen.\n\nEtter håndverkertjenesteloven § 5 skal rørleggerarbeid utføres fagmessig. En lodding, kobling eller pakking som lekker er per definisjon ikke fagmessig utført. Rørleggeren er ansvarlig for både utbedring av feilen og erstatning for alle dokumenterte følgeskader. I sak 2021-554 ble en entreprenør holdt ansvarlig for feil flere år etter ferdigstillelse — reklamasjonsfristen er 5 år.\n\nStans lekkasjen umiddelbart — steng vanntilførselen og begrens skadeomfanget. Dokumenter skaden med bilder og video før du tørker opp. Reklamér skriftlig til rørleggeren og varsle forsikringsselskapet. Sak 135048 fastslår at manglende dokumentasjon er mangel — sørg for at rørleggeren leverer komplett ferdigdokumentasjon.", faqs: [{ q: "Det lekker fra røret rørleggeren byttet for 2 måneder siden. Hva gjør jeg?", a: "Reklamér umiddelbart og stopp lekkasjen. I sak 116596 ble lekkasjer vektlagt i prisavslaget. Rørlegger plikter å utbedre vederlagsfritt og dekke følgeskader." }, { q: "Lekkasjen har gitt vannskader i etasjen under. Kan jeg kreve erstatning?", a: "Ja. Sak 116596 bekrefter at følgeskader er håndverkerens ansvar. Dokumenter tørkekostnader, reparasjon og eventuelt midlertidig bolig." }, { q: "Rørleggeren leverte ikke ferdigdokumentasjon. Er det en mangel?", a: "Ja. Sak 135048 fastslår at manglende dokumentasjon i seg selv er mangel. Hold tilbake sluttbetaling inntil komplett dokumentasjon er levert." }]},
  { slug: "takstein-feil-montering", title: "Feil monterte takstein: Lekkasje og skader", lawRef: "HTL § 5", cat: "handverkere", desc: "Tak som lekker etter ny taklegging er klar mangel med lang reklamasjonsfrist.", bodyText: "Feil monterte takstein er en alvorlig mangel som kan føre til vanninntrengning, vindløfting og i verste fall at takstein blåser av og skader personer eller eiendom. Korrekt montering av takstein krever riktig lekting, undertak, beslag og festemetode tilpasset vindbelastningen på stedet. I Forbrukerklageutvalgets sak 2021-554 ble en entreprenør holdt ansvarlig for feil på utvendig arbeid flere år etter ferdigstillelse — prinsippet gjelder direkte for taksteinmontering.\n\nEtter håndverkertjenesteloven § 5 skal taklegging utføres fagmessig i henhold til produsentens monteringsanvisning og gjeldende byggeforskrifter. Takarbeid som ikke tåler normale norske værforhold er ikke fagmessig utført. I sak 116596 ble prisavslag på 250 000 kr gitt for totalrenovering med omfattende mangler — takfeil er et typisk moment i slike saker.\n\nDokumenter lekkasjen eller løse takstein med bilder og video. En takstmann kan vurdere om monteringen er fagmessig. Reklamér skriftlig og krev utbedring. Dagmulkt-prinsippet (1 promille per dag, maks 100 dager) kan også komme til anvendelse dersom utbedringen forsinkes.", faqs: [{ q: "Taket lekker etter ny takstein ble lagt. Er det håndverkerens ansvar?", a: "Ja. I sak 2021-554 ble entreprenør holdt ansvarlig for utvendige feil etter ferdigstillelse. Et nytt tak skal ikke lekke under normale norske forhold." }, { q: "Håndverkeren sier lekkasjen skyldes ekstremt uvær. Hva gjør jeg?", a: "Be om værdata for perioden. Normalt norsk høstvær er ikke ekstraordinært. Sak 116596 bekrefter at mangelfullt arbeid gir prisavslag — taket skal tåle vanlige forhold." }, { q: "Takstein blåste av i storm. Kan jeg kreve erstatning for skade på naboens bil?", a: "Dersom monteringen var mangelfull etter HTL § 5, er håndverkeren erstatningsansvarlig for følgeskader. Dagmulkt-prinsippet kan gi tilleggskrav ved forsinket utbedring." }]},

  // HÅNDVERKERE (2 nye noder)
  { slug: "maling-flasser-fasade", title: "Maling flasser på husveggen etter kort tid", lawRef: "HTL § 5", cat: "handverkere", desc: "Flassende fasademaling etter kort tid er ikke fagmessig utført og gir reklamasjonsrett.", bodyText: "Fasademaling som begynner å flasse innen 1–3 år er ikke fagmessig utført. Årsaker kan være manglende rengjøring av underlaget, maling på fuktig tre, feil grunnmaling, feil produktvalg for eksponert fasade eller for tynt strøk. Alle disse forholdene er håndverkerens ansvar etter håndverkertjenesteloven § 5.\n\nFotodokumentasjon er viktig — ta bilder av flassingen med dato, helst fra flere vinkler og med tydelig skala. En uavhengig malermester eller bygningsingeniør kan gi skriftlig vurdering av om arbeidet var fagmessig utført, noe som styrker reklamasjonen betraktelig.\n\nReklamér skriftlig til firmaet innen rimelig tid etter at flassingen ble oppdaget. Du har 5 års reklamasjonsrett på arbeid utført på fast eiendom. Krev omarbeiding uten ekstra kostnad — du har ikke plikt til å akseptere prisavslag dersom du vil ha arbeidet utført korrekt.", faqs: [{ q: "Håndverkeren sier det er fukt i veggen som er årsaken. Hvem har rett?", a: "Håndverkeren plikter å undersøke underlaget før maling og varsle om fuktproblemer. Dersom han malte uten å varsle, er han ansvarlig uavhengig av fukt." }, { q: "Firmaet er konkurs. Kan jeg kreve noe?", a: "Du kan melde kravet i konkursboet. Dersom det er tegnet faglig ansvarsforsikring kan du henvende deg direkte til forsikringsselskapet." }, { q: "Har jeg rett til å få en annen håndverker til å gjøre jobben på original firmaets regning?", a: "Ja, dersom firmaet ikke utbedrer innen rimelig tid etter skriftlig reklamasjon kan du la en annen utføre arbeidet og sende regningen til original firmaet." }]},
  { slug: "drenering-kjeller-fukt", title: "Fukt i kjeller etter nylagt drenering", lawRef: "HTL § 5", cat: "handverkere", desc: "Fortsatt fukt etter ny drenering er sterk indikasjon på mangelfullt arbeid.", bodyText: "Drenering er et komplekst arbeid som krever riktig fall, riktig type drensrør, korrekt filterlag og god kobling til eksisterende avløp. Dersom kjelleren fortsatt er fuktig etter at ny drenering er lagt, er det sterk indikasjon på at ett eller flere av disse elementene er feil utført.\n\nFørste steg er å dokumentere fuktproblemet: fuktmåling av gulv og vegger, fotografering av vanninntrengning etter nedbør og gjerne en rapport fra en bygningsingeniør. Deretter reklamér skriftlig til firmaet og krev en faglig vurdering av hva som er galt.\n\nHåndverkeren har rett til å utbedre mangelen én gang. Dersom utbedringen ikke løser problemet, eller firmaet nekter å komme, kan du engasjere en annen entreprenør og kreve kostnadene dekket. Med 5 års reklamasjonsrett på fast eiendom har du god tid til å følge opp.", faqs: [{ q: "Firmaet hevder fukt skyldes setningsskader i grunnmuren, ikke dreneringen. Hvem har bevisbyrden?", a: "Firmaet har bevisbyrden for at årsaken ligger utenfor deres arbeidsomfang. Vag påstand om setningsskader er ikke tilstrekkelig — krev skriftlig teknisk begrunnelse." }, { q: "Det er gått 3 år siden dreneringen ble lagt. Er det for sent å reklamere?", a: "Nei. Du har 5 års reklamasjonsfrist på arbeid på fast eiendom. Reklamér skriftlig snarest etter at fuktproblemet ble oppdaget." }, { q: "Kan jeg kreve erstatning for skader på møbler og gulv i kjelleren?", a: "Ja, dokumenterte følgeskader som følge av mangelfullt arbeid kan kreves erstattet i tillegg til utbedring av selve dreneringen." }]},

  // HÅNDVERKERE (14 nye noder med bodyText og FAQs)
  { slug: "elektriker-feil", title: "Feil utført elektrisk arbeid — rettigheter og krav", lawRef: "HTL § 5", cat: "handverkere", desc: "Feil elektrisk arbeid er farlig og gir rett til utbedring og erstatning.", bodyText: "Feil utført elektrisk arbeid er ikke bare en reklamasjonssak — det er en sikkerhetssak. Kortslutning, brann og elektrisk støt kan forårsakes av feil kabling, manglende jordfeil-bryting, overbelastede kurser og feil dimensjonerte sikringer. Alt elektrisk arbeid skal utføres av autorisert elektrofagarbeider.\n\nDersom du oppdager feil etter elektrisk arbeid — apparater som ikke virker, sikringer som løser ut gjentatte ganger, varmgang i kontakter eller fremmedukt — kontakt elektrikeren umiddelbart og krev utbedring. Dersom feilen innebærer umiddelbar fare, ta kontakt med Elvia eller lokal nettoperatør.\n\nDokumenter alle feil skriftlig. Etter utbedring bør du be om ny samsvarserklæring som bekrefter at anlegget er i forskriftsmessig stand. Manglende samsvarserklæring er i seg selv en mangel.", faqs: [{ q: "Elektrikeren har ikke levert samsvarserklæring. Hva gjør jeg?", a: "Samsvarserklæring er lovpålagt etter avsluttet elektrisk arbeid. Krev den skriftlig — uten den er arbeidet ikke lovlig avsluttet og du kan ikke selge boligen." }, { q: "Det oppsto brann pga. feil elektrisk arbeid. Hvem dekker skadene?", a: "Elektrikerens ansvarsforsikring skal dekke skadene. Kontakt forsikringsselskapet direkte og meld også skaden til din egen hjemforsikring." }, { q: "Kan jeg klage til Elvia eller DSB på feil utført elektrisk arbeid?", a: "Ja, DSB (Direktoratet for samfunnssikkerhet og beredskap) fører tilsyn med elektriske anlegg og kan inspisere arbeidet. Klage til DSB kan støtte reklamasjonsaken din." }]},
  { slug: "taklekkasje-etter-arbeid", title: "Taklekkasje etter håndverkerarbeid", lawRef: "HTL § 5", cat: "handverkere", desc: "Taklekkasje etter takarbeid er mangel med 5 års reklamasjonsrett.", bodyText: "Tak som lekker etter utført takarbeid — enten det er ny taktekking, reparasjon av eksisterende tak eller arbeid med beslag og renner — er en klar mangel etter håndverkertjenesteloven. Takarbeid er krevende og krever riktig produkt, riktig teknikk og riktige beslag.\n\nVanlige årsaker til taklekkasje etter håndverkerarbeid: feil legging av takstein eller takpapp, manglende eller feil utførelse av beslag rundt pipe og takgjennomføringer, for lite overlapp mellom takplatene og feil skrålengde som gir frostsprengning.\n\nDokumenter lekkasjen med foto og fuktmålinger — helst under og etter nedbør. En taktekkermester kan gi uavhengig vurdering av om arbeidet er fagmessig utført. Med 5 års reklamasjonsrett på fast eiendom har du god tid til å følge opp.", faqs: [{ q: "Håndverkeren sier lekkasjen skyldes storm og ikke hans arbeid. Kan han ha rett?", a: "Han må dokumentere at stormen var ekstrem og at arbeidet var fagmessig. Normalt vær i Norge er ikke en gyldig unnskyldning for tak som lekker." }, { q: "Firmaet er nedlagt. Kan jeg kreve noe?", a: "Sjekk om firmaet hadde faglig ansvarsforsikring — da kan du kreve direkte av forsikringsselskapet. Ellers kan du gå mot eieren personlig dersom det var enkeltmannsforetak." }, { q: "Har jeg krav på å få dekket følgeskader som ødelagte møbler og parkett?", a: "Ja, dokumenterte følgeskader som skyldes taklekkasjen kan kreves erstattet av håndverkeren i tillegg til utbedring av selve taket." }]},
  { slug: "murer-feil-grunnmur", title: "Feil i grunnmur eller muring etter håndverkerarbeid", lawRef: "HTL § 5", cat: "handverkere", desc: "Feil muring av grunnmur eller pipe er alvorlig mangel med store konsekvenser.", bodyText: "Muring av grunnmur, pipe, mur og andre konstruksjoner er arbeid der feil kan ha alvorlige strukturelle og sikkerhetsmessige konsekvenser. Sprekker i grunnmur, skjev mur, feil mørtel som ikke tåler frost og pipe som ikke trekker riktig er alle reklamasjonssaker.\n\nSpesielt alvorlig er feil på pipe og ildsted — dette kan forårsake brann og er livstruende. Dersom pipearbeid er feil utført, rapporter umiddelbart til feiervesenet og Brann og redning. Ikke bruk pipen inntil den er faglig godkjent.\n\nUtbedring av feil muring er ofte kostbart og tidkrevende — spesielt dersom grunnmuren må graves opp. Krev faglig vurdering fra uavhengig byggmester eller ingeniør som grunnlag for reklamasjonen.", faqs: [{ q: "Pipa røyker innover og sot setter seg overalt. Er det håndverkerens feil?", a: "Dersom pipa ikke trekker etter at nytt arbeid ble utført, ja. Kontakt feiervesenet for inspeksjon — de kan dokumentere problemet og er uavhengig tredjepart." }, { q: "Grunnmuren har sprekker etter 2 år. Er det normale setningsskader eller håndverkerfeil?", a: "Avhenger av sprekkmønsteret. Horisontale sprekker er mer alvorlige og kan indikere konstruksjonsfeil. En byggingeniør kan vurdere årsaken." }, { q: "Kan jeg bruke pipen til feieren har vært? Hvem betaler for feierens tilsyn?", a: "Ikke bruk pipen inntil den er godkjent — brannrisikoen er for høy. Kostnaden til feierens tilsyn kan kreves dekket av håndverkeren dersom feilen er hans." }]},
  { slug: "ventilasjon-feil", title: "Feil på ventilasjon etter håndverkerarbeid", lawRef: "HTL § 5", cat: "handverkere", desc: "Ventilasjon som ikke fungerer som forutsatt etter installasjon er mangel.", bodyText: "Ventilasjonsanlegg som ikke fungerer korrekt etter installasjon eller service — dårlig luftgjennomstrømning, støy, luktproblemer eller kondensasjonsproblemer — er mangel etter håndverkertjenesteloven. Dårlig ventilasjon kan føre til muggvekst, fuktskader og dårlig inneklima.\n\nVentilasjonsfeil kan skyldes feil dimensjonering av anlegget, feil montering av kanaler og ventiler, manglende balansering av systemet eller feil innstilling av aggregat. En ventilasjonstekniker kan måle luftstrøm og dokumentere avvik fra spesifikasjonene.\n\nFor boliger stilles det krav til minimum ventilasjon etter teknisk forskrift (TEK17). Dersom det installerte anlegget ikke oppfyller disse kravene, er det i tillegg til mangel etter håndverkertjenesteloven også et lovbrudd.", faqs: [{ q: "Det lukter røyk/mat fra naboene gjennom ventilasjonen. Er det en mangel?", a: "Ja, dersom kanaler er feil koblet eller det er trykkfeil som fører til at luft fra andre enheter kommer inn. Dette er en installasjonfeil håndverkeren er ansvarlig for." }, { q: "Ventilasjonsanlegget støyer veldig. Er det reklamasjonsgrunnlag?", a: "Ja, støy over normalt akseptabelt nivå er en mangel. Be om lydmåling og sammenlign med produsentens spesifikasjoner og kontraktens betingelser." }, { q: "Det er kommet mugg i soverommet etter at nytt ventilasjonsanlegg ble montert. Er det en sammenheng?", a: "Muligens. Dårlig ventilasjon er en hovedårsak til muggvekst. Be om faglig vurdering av om muggveksten skyldes utilstrekkelig ventilasjon fra det nye anlegget." }]},
  { slug: "snekker-vinduer-dorer", title: "Vinduer og dører som ikke tetter etter montasje", lawRef: "HTL § 5", cat: "handverkere", desc: "Vinduer og dører som ikke tetter korrekt etter montasje er reklamasjonsgrunnlag.", bodyText: "Vinduer og dører som slipper inn trekk, fukt eller støy etter montering er ikke fagmessig installert. Korrekt montering krever riktig fuging rundt karmen, korrekt justering av hengsler og lås, og riktig avstandsskiver for å sikre jevn spalt.\n\nTrekk fra vinduer og dører kan øke energikostnadene betydelig og er en klar mangel. Kondens på innsiden av vinduer kan indikere at trekk-avstandsskivene er feil plassert eller at isolerglasset er defekt.\n\nFor nye vinduer gjelder produsentgaranti i tillegg til håndverkerens installasjonsansvar. Sprekker i fuging og isolasjonsmansjett rundt karm er håndverkerens ansvar — defekt isolerglass er produsentens ansvar.", faqs: [{ q: "Det er kondens mellom glassene i det nye vinduet. Er det håndverkerens feil?", a: "Nei, kondens mellom glassene skyldes defekt isolerglass — det er produsentens ansvar. Kontakt vindusprodusenten, ikke installatøren." }, { q: "Håndverkeren justerte vinduene men de tetter fortsatt ikke. Hva gjør jeg?", a: "Håndverkeren har brukt sin ene utbedringssjanse uten å løse problemet. Du kan nå engasjere en annen håndverker og kreve kostnadene dekket." }, { q: "Dørene blåste opp i en storm og løsnet fra hengslene. Er det håndverkerens feil?", a: "Dersom hengslene ikke var korrekt montert for dørens vekt og dimensjon, ja. Normal vind i Norge er ikke en gyldig unnskyldning for dører som løsner." }]},
  { slug: "flislegging-feil", title: "Feil flislegging — sprekker, fall og fuging", lawRef: "HTL § 5", cat: "handverkere", desc: "Feil flislegging er mangel som kan gi fuktskader og krav om omlegging.", bodyText: "Flis som sprekker, løsner, har feil fall mot sluk eller har dårlig fuging er mangelfull håndverkerjobb. Feilene kan skyldes feil underlag, feil lim, feil fugemasse for våtrom, manglende bevegelsesfuger eller feil fall.\n\nSpesielt alvorlig er feil fall på gulv i våtrom — dersom vannet ikke renner mot sluket men samler seg i hjørner, kan dette gi fuktskader under flisene og til slutt lekkasje. Korrekt fall er 1:50 (2 cm per meter) mot sluket.\n\nSprekker i fliser kan skyldes feil underlag (for mye svikt), feil lim, for lite lim eller fravær av bevegelsesfuger. En faglig vurdering fra en flisteknikker kan fastslå årsaken og dokumentere omfanget av feilen.", faqs: [{ q: "Flisene på badet begynner å løsne etter 6 måneder. Er det reklamasjonsgrunnlag?", a: "Ja, fliser skal ikke løsne etter 6 måneder. Årsaken er normalt feil underlag, feil lim eller manglende heft. Reklamér skriftlig umiddelbart." }, { q: "Håndverkeren sier flisene sprakk fordi jeg brukte gulvvarme. Kan han ha rett?", a: "Dersom gulvvarme var planlagt og håndverkeren visste om det, pliktet han å velge riktig lim og legge bevegelsesfuger. Han kan ikke skylde på gulvvarme han burde tatt hensyn til." }, { q: "Kan jeg kreve at hele badet flislegges på nytt, eller bare reparasjon av sprekker?", a: "Du kan kreve omlegging av de delene som er mangelfull. Dersom manglene er gjennomgående og delvis reparasjon ikke er mulig uten synlig avvik, kan du kreve full omlegging." }]},
  { slug: "malerfirma-dårlig-jobb", title: "Dårlig malerarbeid — misfarging, striper og drypp", lawRef: "HTL § 5", cat: "handverkere", desc: "Synlige feil i malerarbeid er mangel som gir rett til omarbeiding.", bodyText: "Malerarbeid som ikke holder fagmessig standard — synlige striper, ujevn dekning, drypp og sprutmerker, feil farge eller maling som slipper tidlig — er mangel etter håndverkertjenesteloven. Maling er et synlig arbeid der kunden rimelig kan forvente et estetisk tilfredsstillende resultat.\n\nVanlige malerfeiler: for tynne strøk som gir gjennomsyn, maling uten tilstrekkelig grunnmaling, maling i for kaldt eller fuktig vær, dårlig maskering som gir spillmerker, og feil type maling for overflaten (f.eks. utvendig maling brukt innvendig).\n\nDokumenter alle synlige feil med fotografier i godt lys — helst dagslys fra siden som avslører ujevnheter. Gi håndverkeren skriftlig liste over alle feil og gi en rimelig frist for utbedring.", faqs: [{ q: "Maleren sier resultatet er 'normalt for håndmaling'. Kan han ha rett?", a: "Handmaling kan ha viss variasjon, men synlige striper, drypp og ujevn dekning er ikke akseptabelt. Normal faglig standard tilsier et jevnt resultat uten synlige feil." }, { q: "Malingen lakker seg av etter noen måneder innendørs. Er det malerfirmaets ansvar?", a: "Ja, maling som ikke sitter fast på korrekt forberedt underlag er faglig mangel. Be om dokumentasjon på hvilken maling som ble brukt og om underlaget ble korrekt rengjort." }, { q: "Kan jeg kreve at rommet males helt om, eller bare at feilene rettes?", a: "Du har rett til at resultatet holder fagmessig standard. Dersom enkeltrettinger gir synlige avvik fra resten, kan du kreve at hele flaten males om." }]},
  { slug: "byggeprosjekt-overskridelse", title: "Kostnadsoverskridelse på byggeprosjekt", lawRef: "HTL § 32", cat: "handverkere", desc: "Håndverker kan ikke overskride avtalt pris vesentlig uten varsel.", bodyText: "Kostnadsoverskridelser på byggeprosjekter er en av de vanligste tvistene mellom håndverkere og kunder. Håndverkertjenesteloven stiller klare krav til varsling — dersom arbeidet blir vesentlig dyrere enn anslått, plikter håndverkeren å varsle kunden umiddelbart og gi mulighet til å avbryte prosjektet.\n\nDersom prisoverslaget overskrides med mer enn 15% uten forhåndsvarsel, kan kunden normalt avvise den overskytende regningen. 'Vesentlig overskridelse' vurderes konkret, men 15% er et vanlig referansepunkt fra rettspraksis.\n\nPassiv aksept er ikke det samme som samtykke — dersom håndverkeren fortsetter å jobbe uten å varsle om overskridelse, kan du ikke automatisk holdes ansvarlig for hele regningen selv om arbeidet er utført.", faqs: [{ q: "Håndverkeren sender sluttfaktura som er dobbelt så høy som estimat. Kan jeg nekte å betale?", a: "Du kan nekte å betale den delen som overstiger estimat pluss rimelig margin (ca. 15%), dersom du ikke ble varslet underveis om overskridelsen." }, { q: "Prosjektet tok mye lengre tid enn planlagt og jeg måtte betale mer i dagpenger. Kan jeg kreve erstatning?", a: "Ja, dersom forsinkelsen skyldtes håndverkerens forhold kan du kreve dokumenterte merkostnader som følge av forsinkelsen erstattet." }, { q: "Håndverkeren krever betaling for 'tilleggsarbeid' jeg ikke bestilte. Må jeg betale?", a: "Kun for tilleggsarbeid du eksplisitt bestilte eller godkjente. Arbeid håndverkeren utførte på eget initiativ uten avtale, kan du nekte å betale for." }]},
  { slug: "angrerett-handverkertjenester", title: "Angrerett ved kjøp av håndverkertjenester", lawRef: "Angrerettloven § 22", cat: "handverkere", desc: "Du har 14 dagers angrerett ved kjøp av håndverkertjenester utenfor fast forretningssted.", bodyText: "Angreretten gjelder ved kjøp av håndverkertjenester som inngås utenfor håndverkerens faste forretningssted — typisk når en håndverker oppsøker deg hjemme og du inngår avtale der og da. Du har da 14 dagers angrerett uten å måtte oppgi grunn.\n\nDersom arbeidet allerede er påbegynt innen angrefristen og du angrer, kan håndverkeren kreve betalt for det arbeidet som allerede er utført. Dersom du ikke ble informert om angreretten, utvides fristen til 12 måneder.\n\nAngreretten gjelder ikke for arbeid som er fullført innenfor angrefristen dersom du eksplisitt ba om at arbeidet skulle startes umiddelbart. Sørg alltid for at du forstår hva du inngår avtale om ved besøk hjemme.", faqs: [{ q: "Håndverkeren kom hjem til meg og jeg signerte kontrakt. Har jeg angrerett?", a: "Ja, dersom kontrakten ble inngått hjemme hos deg utenfor håndverkerens faste forretningssted har du 14 dagers angrerett etter angrerettloven." }, { q: "Håndverkeren informerte ikke om angreretten. Hva betyr det?", a: "Fristen for angrerett utvides til 12 måneder dersom selger ikke informerte om angreretten i tråd med loven. Du kan angre opptil ett år etter avtaleinngåelsen." }, { q: "Håndverkeren startet arbeidet umiddelbart etter avtalen. Kan jeg fortsatt angre?", a: "Ja, men du må betale for arbeidet som allerede er utført. Angreretten gjelder for den uutførte delen av kontrakten." }]},
  { slug: "garanti-handverkertjeneste", title: "Garanti og reklamasjon på håndverkerarbeid", lawRef: "HTL § 22", cat: "handverkere", desc: "Reklamasjonsfristen er 5 år på arbeid på fast eiendom — uavhengig av garanti.", bodyText: "Mange håndverkere tilbyr garanti på sitt arbeid — typisk 1–2 år. Men uavhengig av garantien har du lovfestet reklamasjonsrett etter håndverkertjenesteloven: 2 år for løsøre og 5 år for arbeid på fast eiendom.\n\nGarantien er en tilleggsrettighet — den fritar ikke håndverkeren fra det lovfestede ansvaret. En håndverker som sier 'garantien er løpt ut' som begrunnelse for å avvise reklamasjon, gir deg feilinformasjon.\n\nVed reklamasjon innen garantiperioden har håndverkeren normalt bevisbyrden for at feilen ikke skyldtes arbeidet. Etter garantiperiodens utløp (men innen lovfestet reklamasjonsfrist) må du sannsynliggjøre at feilen skyldes arbeidet.", faqs: [{ q: "Håndverkeren har 1 års garanti men avviser reklamasjon etter 18 måneder. Har han rett?", a: "Nei, for arbeid på fast eiendom er den lovfestede reklamasjonsfristen 5 år. Garantien gir ikke uttrykk for den lovfestede fristen." }, { q: "Garantien er utvidet til 5 år i kontrakten. Er det bedre eller bare det samme?", a: "Det er bedre — kontraktsfestet garanti på 5 år betyr at håndverkeren har bevisbyrden i hele perioden, mens lovens 5-år krever at du sannsynliggjør årsaken etter normal garantiperiode." }, { q: "Firmaet er skiftet ut med nytt firma. Gjelder garantien fortsatt?", a: "Avhenger av om det nye firmaet overtok forpliktelsene. Ved virksomhetsoverdragelse kan krav rettes mot det nye firmaet. Spør skriftlig om de tar over ansvaret." }]},
  { slug: "forsinkelse-handverker", title: "Håndverkeren er forsinket med arbeidet", lawRef: "HTL § 10", cat: "handverkere", desc: "Forsinket håndverker gir rett til å heve kontrakten og kreve erstatning.", bodyText: "Dersom håndverkeren ikke overholder avtalt ferdigstillelsesdato uten gyldig grunn, er han i forsinkelse etter håndverkertjenesteloven. Du kan da sette en rimelig tilleggsfrist, og dersom arbeidet ikke er ferdig innen denne fristen, kan du heve kontrakten.\n\nDokumenter den avtalte ferdigstillelsesdatoen — den bør fremgå skriftlig av tilbudet eller kontrakten. Muntlig avtalte datoer er vanskeligere å bevise. Send e-post som bekrefter fristen dersom du ikke har skriftlig kontrakt.\n\nVed heving kan du kreve tilbake eventuell forskuddsbetaling, og du kan engasjere en annen håndverker til å ferdigstille arbeidet. Merkostnader ved bruk av ny håndverker på grunn av forsinkelsen kan kreves erstattet.", faqs: [{ q: "Håndverkeren har ikke dukket opp på 3 uker uten beskjed. Hva gjør jeg?", a: "Send skriftlig varsel med ny rimelig frist for oppstart. Dersom han ikke svarer eller møter opp innen fristen, kan du heve kontrakten og engasjere annen håndverker." }, { q: "Forsinkelsen har kostet meg penger — måtte bo på hotell mens badet var åpent. Kan jeg kreve det tilbake?", a: "Ja, dokumenterte og nødvendige utgifter som følge av håndverkerens forsinkelse kan kreves erstattet. Ta vare på kvitteringer." }, { q: "Håndverkeren sier forsinkelsen skyldes materialforsyning. Er det gyldig grunn?", a: "Kun dersom han ikke med rimelighet kunne forutsett problemet og varslet deg umiddelbart. Generell forsyningssvikt er ikke gyldig dersom andre håndverkere ikke har samme problem." }]},
  { slug: "uautorisert-handverker", title: "Arbeid utført av ufaglært eller uautorisert håndverker", lawRef: "HTL § 5", cat: "handverkere", desc: "Arbeid som krever autorisasjon utført av uautorisert person er ulovlig og gir hevingsrett.", bodyText: "Visse typer håndverkerarbeid krever autorisasjon eller godkjenning — elektrisk arbeid, rørleggerarbeid, arbeid på gass og ventilasjonsarbeid over en viss størrelse. Dersom dette arbeidet utføres av en person uten nødvendig autorisasjon, er det ulovlig og kan ha alvorlige forsikringsmessige konsekvenser.\n\nDersom ufaglært arbeid oppdages i ettertid — typisk ved salg av bolig eller ved skade — kan forsikringsselskapet avslå dekning med begrunnelse i ulovlig arbeid. Dette kan gi deg som huseier enorme tap.\n\nDersom du vet eller mistenker at arbeidet ble utført uten nødvendig autorisasjon, reklamér umiddelbart og krev at autorisert fagperson inspiserer og signerer for arbeidet. Kostnaden for dette kan kreves dekket av den opprinnelige utføreren.", faqs: [{ q: "Rørleggeren hadde ikke autorisasjon. Kan jeg kreve at arbeidet utføres på nytt?", a: "Ja, du kan kreve at autorisert rørlegger inspiserer og signerer for arbeidet. Dersom arbeidet ikke holder standard, krev omgjøring på den uautoriserte utførerens regning." }, { q: "Forsikringen avviste et skadekrav fordi elektrisk arbeid var ulovlig utført. Hva gjør jeg?", a: "Krev erstatning fra den uautoriserte elektrikeren for forsikringstapet. Dette er et direkte tap forårsaket av dennes ulovlige arbeid." }, { q: "Hvordan sjekker jeg om en håndverker er autorisert?", a: "Elektrikere sjekkes i DSBs register, rørleggere i Rørentreprenørenes Landsforening (RRL) og Mesterbrev-registeret. Sjekk alltid før arbeidet starter." }]},
  { slug: "hms-brudd-handverker", title: "HMS-brudd og ulovlig arbeid på byggeplassen", lawRef: "HTL § 5", cat: "handverkere", desc: "Håndverker som bryter HMS-regler setter deg som huseier i ansvar.", bodyText: "Huseier har et medansvar for HMS (helse, miljø og sikkerhet) på sin private byggeplass. Dersom håndverkeren bryter HMS-regler — manglende stilas, feil sikring, arbeid i høyden uten sikring — kan du som huseier bli holdt medansvarlig ved ulykker.\n\nDet er likevel håndverkerens primæransvar å organisere arbeidet på en HMS-forsvarlig måte. Dersom du oppdager grove HMS-brudd, gi skriftlig pålegg om utbedring umiddelbart. Dersom håndverkeren ikke etterkommer, kan du stanse arbeidet.\n\nDokumenter HMS-brudd med foto og dato. Dette kan også brukes som grunnlag for å si opp kontrakten dersom håndverkeren konsekvent ignorerer sikkerhetsregler — slik opptreden er kontraktsbrudd.", faqs: [{ q: "Håndverkeren bruker ikke verneutstyr. Er det mitt problem?", a: "Primæransvaret er håndverkerens, men som huseier bør du påse at arbeidet utføres forsvarlig. Gi skriftlig pålegg om korrekt verneutstyr." }, { q: "En arbeider skadet seg på min tomt. Kan jeg bli ansvarlig?", a: "Muligens, avhengig av om du var informert om risikoen. Sørg for at håndverkeren er forsikret og at arbeidsmiljøloven følges." }, { q: "Kan jeg stoppe arbeidet på grunn av HMS-brudd?", a: "Ja, grove og gjentatte HMS-brudd kan gi grunnlag for å stanse arbeidet og i ytterste konsekvens heve kontrakten." }]},
  { slug: "handverker-forsvunnet", title: "Håndverkeren forsvinner med forskuddet", lawRef: "HTL § 10", cat: "handverkere", desc: "Håndverker som tar forskudd og ikke leverer er i kontraktsbrudd og kan politianmeldes.", bodyText: "Dessverre er det ikke uvanlig at håndverkere tar store forskudd og deretter forsvinner — enten tar de betalt for arbeid de aldri utfører, eller de starter arbeidet men forlater det halvferdig. Begge deler er kontraktsbrudd, og det første er potensielt bedrageri.\n\nDersom håndverkeren har fått forskudd og ikke svarer på henvendelser eller møter opp til avtalt arbeid, send skriftlig varsel med frist. Dersom ingen reaksjon — anmeld forholdet til politiet og gå til sivil sak parallelt.\n\nBetal aldri mer enn 30% i forskudd — det er ingen legitim grunn til høyere forskudd for normale håndverkeroppdrag. Restbeløpet bør betales etter at arbeidet er fullført og godkjent.", faqs: [{ q: "Håndverkeren tok 50% forskudd og er ikke til å få tak i. Hva gjør jeg?", a: "Send skriftlig varsel med 10-dagers frist. Dersom ingen respons — anmeld til politiet som mulig bedrageri og kontakt Forbrukerrådet." }, { q: "Kan jeg kreve pengene tilbake selv om noe av arbeidet er utført?", a: "Du kan kreve tilbake forskuddet fratrukket verdien av det arbeidet som faktisk er utført og godkjent av deg." }, { q: "Håndverkeren er registrert i Brønnøysund. Hjelper det?", a: "Du kan gå til sivil sak mot firmaet og eventuelt begjære det konkurs for å få dekket kravet. Sjekk om firmaet er forsikret — forsikringsselskapet kan da betale." }]},
];

/** Helper: get all nodes for a category */
export function getNodesByCategory(cat: SeoNode["cat"]): SeoNode[] {
  return SEO_NODES.filter((n) => n.cat === cat);
}

/** Helper: get a specific node by cat + slug */
export function getNode(cat: SeoNode["cat"], slug: string): SeoNode | undefined {
  return SEO_NODES.find((n) => n.cat === cat && n.slug === slug);
}

/** Helper: get related nodes (same category, exclude current) */
export function getRelatedNodes(cat: SeoNode["cat"], currentSlug: string, limit = 5): SeoNode[] {
  return SEO_NODES.filter((n) => n.cat === cat && n.slug !== currentSlug).slice(0, limit);
}

